(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-631":{scenario:{company:"Trường An Cost Consultants",supervisor:{name:"Kiều Thị Phương Thảo",role:{vi:"Trưởng nhóm Dự toán",en:"Lead Quantity Surveyor"}},ref_code:"BOQ-2318",title:{vi:"Đo bóc đúng. Áp định mức đúng. Giá trị trung thực.",en:"Measure right. Apply the right norm. Report true value."},brief:{vi:"Bạn soát xét bảng khối lượng BOQ-2318 phần móng nhà xưởng. Cốt thép móng M1 dùng thanh D16; bảng thống kê cốt thép đã duyệt cho tổng chiều dài D16 là 2 980 m. Bản nháp áp sai nhóm đường kính của định mức và tính sai khối lượng thép. Hãy sửa nhóm định mức và khối lượng thép D16 (kg, làm tròn đến kg), rồi lập báo cáo có căn cứ. Đơn giá, định mức trong bài là số liệu mô phỏng.",en:"You are reviewing bill of quantities BOQ-2318 for a factory's foundations. Footing M1 uses D16 bars; the approved bar schedule gives a total D16 length of 2,980 m. The draft applies the wrong diameter group of the norm and miscalculates the steel weight. Correct the norm group and the D16 weight (kg, rounded to 1 kg), then write an evidence-based report. Rates and norms here are simulated."},reference_title:{vi:"Bảng thống kê cốt thép & bảng tính đã duyệt",en:"Approved bar schedule & quantity worksheet"},fields:[{id:"NORM_GROUP",label:{vi:"Nhóm đường kính áp định mức thép D16",en:"Norm diameter group for D16 rebar"},initial:"D>18",expected:"D10-18",choices:["D<=10","D10-18","D>18"],reference:"Bảng thống kê cốt thép móng M1",ref_value:{vi:"Thanh D16 (đường kính danh nghĩa 16 mm); định mức chia nhóm D<=10, D10-18 (trên 10 đến 18 mm), D>18 mm",en:"D16 bar (16 mm nominal); norm groups D<=10, D10-18 (over 10 up to 18 mm), D>18 mm"},hint:{vi:"Nhóm định mức xét theo đường kính danh nghĩa của thanh, không theo vị trí hay tầm quan trọng của cấu kiện.",en:"The norm group depends on the bar's nominal diameter, not on the element's location or importance."}},{id:"STEEL_KG",label:{vi:"Khối lượng thép D16 (kg)",en:"D16 steel weight (kg)"},initial:"3604",expected:"4707",reference:"Bảng tính khối lượng cốt thép",ref_value:{vi:"Tổng chiều dài D16 = 2 980 m; trọng lượng đơn vị = 0,00617 x d^2 (kg/m)",en:"Total D16 length = 2,980 m; unit weight = 0.00617 x d^2 (kg/m)"},hint:{vi:"Bản nháp lấy nhầm trọng lượng đơn vị của một đường kính khác; tính lại từ d = 16 mm.",en:"The draft used the unit weight of another diameter; recompute it from d = 16 mm."}}],sop32:{vi:"Trọng lượng đơn vị thép tròn (kg/m) = 0,00617 x d^2, d tính bằng mm; khối lượng = tổng chiều dài x trọng lượng đơn vị, làm tròn đến 1 kg. Hao hụt đã nằm trong định mức, không cộng vào khối lượng đo bóc.",en:"Unit weight of round bar (kg/m) = 0.00617 x d^2, d in mm; weight = total length x unit weight, rounded to 1 kg. Wastage is already in the norm and is not added to the measured quantity."},context:{label:"DỰ TOÁN / BOQ-2318",metrics:[{label:{vi:"Tổng chiều dài D16",en:"Total D16 length"},value:"2,980 m"},{label:{vi:"Số móng M1",en:"M1 footings"},value:"24"},{label:{vi:"Trọng lượng đơn vị",en:"Unit weight formula"},value:"0.00617 x d^2 kg/m"}]},crisis:{vi:"Chỉ huy trưởng nhà thầu nhắn: “Cứ để nhóm thép >18 mm cho đơn giá cao hơn, cộng thêm 5% hao hụt vào khối lượng nữa. Chủ đầu tư không soát kỹ đâu, dự toán cao thì dễ thương thảo.”",en:"The contractor's site manager texts: “Keep the >18 mm group for the higher rate and add 5% wastage to the quantity too. The client never checks closely, and a high estimate is easier to negotiate.”"},options:{safe:{vi:"Áp đúng nhóm định mức theo đường kính, giữ khối lượng theo bản vẽ, không cộng hao hụt trùng; báo trưởng nhóm dự toán và lưu bảng tính, bản vẽ làm căn cứ.",en:"Apply the norm group by bar diameter, keep the quantity per the drawings with no double-counted wastage; inform the lead QS and file the worksheet and drawings as evidence."},shortcut:{vi:"Giữ nhóm >18 mm và cộng 5% hao hụt như đề nghị để dự toán có dư địa thương thảo.",en:"Keep the >18 mm group and add 5% wastage as asked to leave room for negotiation."},wait:{vi:"Chuyển nguyên bản nháp cho chủ đầu tư và để họ tự phát hiện sai sót.",en:"Send the draft to the client unchanged and let them find the errors."}},questions:{vi:["Giải thích vì sao thép D16 thuộc nhóm D10-18 và cách bạn tính lại khối lượng từ tổng chiều dài.","Đề nghị cộng hao hụt và nâng nhóm định mức gây rủi ro gì cho dự án và cho bạn? Bạn xử lý ra sao?"],en:["Explain why D16 belongs to the D10-18 group and how you recomputed the weight from the total length.","What risks do the proposals to add wastage and upgrade the norm group create for the project and for you? How do you respond?"]},hints:{vi:["Đặt bản nháp cạnh bảng thống kê cốt thép và đánh dấu dòng nhóm định mức không khớp đường kính thanh.","Theo SOP mục 3.2, tính trọng lượng đơn vị từ đường kính thực của thanh rồi mới nhân với tổng chiều dài.","Đọc SOP mục 4.2: đo bóc theo thiết kế, không thổi phồng khối lượng; mọi áp lực phải báo trưởng nhóm."],en:["Place the draft next to the bar schedule and flag the norm group line that does not match the bar diameter.","Under SOP 3.2, compute the unit weight from the actual bar diameter before multiplying by the total length.","Re-read SOP 4.2: measure per the design and never inflate quantities; escalate any pressure to the lead QS."]}},learning:{summary:{vi:"Kỹ sư dự toán và quản lý chi phí xây dựng (QS) đo bóc khối lượng từ hồ sơ thiết kế, áp định mức và đơn giá, lập tổng mức đầu tư, dự toán, giá gói thầu và kiểm soát chi phí suốt vòng đời dự án. Họ giúp chủ đầu tư và nhà thầu ra quyết định dựa trên số liệu chính xác, minh bạch. Nghề đòi hỏi đọc bản vẽ thành thạo, nắm vững quy định quản lý chi phí đầu tư xây dựng và giữ chuẩn mực trung thực khi lập giá trị.",en:"A quantity surveyor (QS) measures quantities from design documents, applies norms and rates, prepares the investment budget, estimates and package prices, and controls cost across the project life cycle. They help clients and contractors decide on accurate, transparent figures. The role requires fluent drawing reading, solid knowledge of construction cost regulations and strict honesty when valuing work."},responsibilities:{vi:["Đo bóc khối lượng từ bản vẽ thiết kế và chỉ dẫn kỹ thuật theo quy tắc đo bóc thống nhất.","Áp định mức, đơn giá và chỉ số giá phù hợp để lập dự toán, giá gói thầu.","Lập và kiểm soát tổng mức đầu tư, dự toán; theo dõi chênh lệch giữa dự toán và thực tế.","Thẩm tra hồ sơ thanh toán, khối lượng phát sinh và điều chỉnh giá hợp đồng.","Lập báo cáo chi phí định kỳ, quyết toán và lưu trữ hồ sơ làm căn cứ kiểm toán."],en:["Measure quantities from design drawings and specifications under consistent measurement rules.","Apply suitable norms, rates and price indices to prepare estimates and package prices.","Prepare and control the investment budget and estimates, tracking variance against actuals.","Verify payment applications, additional quantities and contract price adjustments.","Issue periodic cost reports and final accounts and archive records for audit."]},competencies:[{name:{vi:"Đo bóc khối lượng",en:"Quantity take-off"},desc:{vi:"Đọc bản vẽ kiến trúc, kết cấu, MEP; đo bóc đúng đơn vị, quy cách, không trùng, không sót.",en:"Read architectural, structural and MEP drawings; measure in the right units and specs with no double counting or omissions."}},{name:{vi:"Định mức & đơn giá",en:"Norms & rates"},desc:{vi:"Chọn đúng mã hiệu định mức theo điều kiện thi công, quy cách vật liệu và biện pháp.",en:"Select the right norm code for site conditions, material specification and method."}},{name:{vi:"Kiểm soát chi phí",en:"Cost control"},desc:{vi:"Theo dõi dòng tiền, cảnh báo vượt chi và đề xuất giải pháp tối ưu chi phí.",en:"Track cash flow, warn of overruns and propose value engineering options."}},{name:{vi:"Công cụ số",en:"Digital tools"},desc:{vi:"Dùng phần mềm dự toán, bảng tính và bóc tách từ mô hình BIM để giảm sai sót.",en:"Use estimating software, spreadsheets and BIM-based take-off to reduce errors."}},{name:{vi:"Trung thực nghề nghiệp",en:"Professional honesty"},desc:{vi:"Không thổi phồng khối lượng, không áp sai định mức để có lợi cho bất kỳ bên nào.",en:"Never inflate quantities or misapply norms to favour any party."}}],knowledge:{vi:["Nghị định 10/2021/NĐ-CP về quản lý chi phí đầu tư xây dựng.","Thông tư 11/2021/TT-BXD hướng dẫn xác định và quản lý chi phí đầu tư xây dựng.","Thông tư 12/2021/TT-BXD ban hành định mức xây dựng và các văn bản sửa đổi, bổ sung.","Thông tư 13/2021/TT-BXD hướng dẫn xác định chỉ tiêu kinh tế kỹ thuật và đo bóc khối lượng công trình.","Cơ cấu chi phí xây dựng: chi phí trực tiếp, chi phí gián tiếp, thu nhập chịu thuế tính trước và thuế giá trị gia tăng.","Công thức trọng lượng thép tròn 0,00617 x d^2 (kg/m) và đơn vị đo bóc của từng loại công tác."],en:["Decree 10/2021/ND-CP on construction investment cost management.","Circular 11/2021/TT-BXD guiding the determination and management of construction investment cost.","Circular 12/2021/TT-BXD issuing construction norms, with its amendments and supplements.","Circular 13/2021/TT-BXD guiding techno-economic indicators and quantity measurement of works.","Construction cost structure: direct cost, indirect cost, pre-calculated taxable income and value added tax.","Round bar weight formula 0.00617 x d^2 (kg/m) and the measurement unit of each work type."]},tools:["Phần mềm lập dự toán xây dựng","Microsoft Excel","Phần mềm đọc bản vẽ CAD","Phần mềm bóc tách khối lượng từ BIM","Cơ sở dữ liệu giá vật liệu địa phương"],kpis:{vi:["Sai lệch khối lượng giữa dự toán và quyết toán (mục tiêu dưới 3%).","Tỷ lệ hồ sơ dự toán qua thẩm tra không phải sửa lớn.","Thời gian hoàn thành bộ dự toán so với kế hoạch.","Số khoản phát sinh bị từ chối do thiếu căn cứ."],en:["Quantity variance between estimate and final account (target below 3%).","Share of estimates passing independent review without major changes.","Estimate completion time against plan.","Number of variation items rejected for lack of evidence."]},day:[{time:"08:00",vi:"Nhận bản vẽ phát hành mới, kiểm tra danh mục phiên bản và phạm vi thay đổi.",en:"Receive newly issued drawings and check the revision register and scope of changes."},{time:"09:30",vi:"Đo bóc bê tông, cốt thép, ván khuôn phần móng theo bản vẽ hiệu lực.",en:"Take off foundation concrete, rebar and formwork from the current drawings."},{time:"13:30",vi:"Áp mã hiệu định mức, đơn giá vật liệu, nhân công, máy và lập bảng tổng hợp.",en:"Apply norm codes and material, labour and plant rates and build the summary."},{time:"15:30",vi:"Họp với kỹ sư kết cấu làm rõ chi tiết chưa đủ thông tin để đo bóc.",en:"Meet the structural engineer to clarify details lacking information for take-off."},{time:"17:00",vi:"Soát xét chéo bảng tính, ghi nhật ký giả định và lưu hồ sơ.",en:"Peer-review worksheets, log assumptions and archive the file."}],mistakes:{vi:["Lấy nhầm trọng lượng đơn vị của đường kính khác khi tính khối lượng thép.","Cộng hao hụt vào khối lượng đo bóc trong khi định mức đã bao gồm hao hụt.","Đo bóc từ bản vẽ đã hết hiệu lực, không đối chiếu danh mục phiên bản."],en:["Using the unit weight of another diameter when computing rebar weight.","Adding wastage to measured quantities when the norm already includes it.","Measuring from superseded drawings without checking the revision register."]},career:[{vi:"Kỹ thuật viên đo bóc khối lượng",en:"Quantity take-off technician"},{vi:"Kỹ sư dự toán (QS)",en:"Quantity surveyor (QS)"},{vi:"Kỹ sư QS chính, kiểm soát chi phí",en:"Senior QS and cost controller"},{vi:"Giám đốc quản lý chi phí dự án",en:"Project cost management director"}],glossary:[{term:"BOQ",vi:"Bảng khối lượng mời thầu hoặc dự toán, liệt kê công việc, đơn vị, khối lượng và đơn giá.",en:"Bill of quantities listing work items, units, quantities and rates for tender or estimate."},{term:"Định mức dự toán",vi:"Mức hao phí vật liệu, nhân công, máy thi công để hoàn thành một đơn vị khối lượng công tác.",en:"Standard consumption of materials, labour and plant to complete one unit of construction work."},{term:"Take-off",vi:"Quá trình đo bóc khối lượng từ bản vẽ, mô hình theo quy tắc đo thống nhất.",en:"Process of measuring quantities from drawings or models under agreed measurement rules."},{term:"Chi phí gián tiếp",vi:"Gồm chi phí chung, nhà tạm để ở và điều hành thi công, công việc không xác định được khối lượng từ thiết kế và chi phí gián tiếp khác.",en:"Covers overheads, temporary site housing and offices, items not quantifiable from the design and other indirect costs."},{term:"Cost plan",vi:"Kế hoạch chi phí phân bổ ngân sách theo hạng mục, làm chuẩn kiểm soát chi phí khi thiết kế và thi công.",en:"Budget allocated by element, used as the baseline to control cost during design and construction."}],quiz:[{q:{vi:"Trọng lượng đơn vị của thép D20 theo công thức 0,00617 x d^2 là bao nhiêu?",en:"What is the unit weight of a D20 bar using 0.00617 x d^2?"},options:{vi:["1,58 kg/m","2,00 kg/m","2,47 kg/m","3,85 kg/m"],en:["1.58 kg/m","2.00 kg/m","2.47 kg/m","3.85 kg/m"]},answer:2,explain:{vi:"0,00617 x 20^2 = 0,00617 x 400 = 2,468, làm tròn 2,47 kg/m.",en:"0.00617 x 20^2 = 0.00617 x 400 = 2.468, rounded to 2.47 kg/m."}},{q:{vi:"Theo cơ cấu chi phí xây dựng hiện hành, chi phí nhà tạm để ở và điều hành thi công thuộc nhóm nào?",en:"Under the current construction cost structure, which group covers temporary site housing and offices?"},options:{vi:["Chi phí trực tiếp","Chi phí gián tiếp","Chi phí dự phòng","Chi phí quản lý dự án"],en:["Direct cost","Indirect cost","Contingency","Project management cost"]},answer:1,explain:{vi:"Chi phí gián tiếp gồm chi phí chung, nhà tạm để ở và điều hành thi công và một số khoản không xác định được khối lượng từ thiết kế.",en:"Indirect cost includes overheads, temporary site housing and offices and some items not quantifiable from the design."}},{q:{vi:"Nhà thầu đề nghị bạn cộng thêm 5% khối lượng “cho dư” trước khi trình chủ đầu tư. Bạn làm gì?",en:"The contractor asks you to add 5% to the quantities “for safety” before submitting to the client. What do you do?"},options:{vi:["Đồng ý vì đó là thông lệ","Cộng 2% cho vừa phải","Gửi bản nháp mà không ý kiến","Từ chối, giữ khối lượng theo thiết kế, báo trưởng nhóm và lưu căn cứ"],en:["Agree because it is common practice","Add 2% as a compromise","Send the draft without comment","Refuse, keep design quantities, inform the lead and keep evidence"]},answer:3,explain:{vi:"Khối lượng đo bóc phải theo thiết kế; thổi phồng là sai lệch có chủ đích và có thể bị xử lý khi thẩm tra, kiểm toán.",en:"Measured quantities must follow the design; inflating them is deliberate misstatement and can be sanctioned in review or audit."}},{q:{vi:"Thép D12 khi áp định mức sản xuất, lắp dựng cốt thép thuộc nhóm nào?",en:"Which norm group applies to D12 bars for rebar fabrication and fixing?"},options:{vi:["Nhóm đường kính <=18 mm","Nhóm đường kính <=10 mm","Nhóm đường kính >18 mm","Không phân nhóm"],en:["Diameter group <=18 mm","Diameter group <=10 mm","Diameter group >18 mm","No grouping"]},answer:0,explain:{vi:"Đường kính 12 mm lớn hơn 10 mm và không quá 18 mm nên thuộc nhóm <=18 mm.",en:"A 12 mm bar is above 10 mm and not over 18 mm, so it falls in the <=18 mm group."}}],tools_en:["Construction cost estimating software","Microsoft Excel","CAD drawing viewer","BIM quantity takeoff software","Local material price database"]}},"KK-632":{scenario:{company:"Vĩnh An Supervision Consultants",supervisor:{name:"Trần Văn Thắng",role:{vi:"Trưởng đoàn tư vấn giám sát",en:"Chief Site Supervisor"}},ref_code:"PP-0516",title:{vi:"Đủ cường độ mới tháo. Đủ mẫu mới nghiệm thu.",en:"Strip only at strength. Accept only with samples."},brief:{vi:"Bạn là kỹ sư giám sát, soát xét kế hoạch đổ bê tông và tháo cốp pha PP-0516 của nhà thầu cho sàn tầng 5. Khối đổ gồm bản sàn 40 m x 30 m dày 0,16 m và hệ dầm 30,6 m3; nhịp dầm lớn nhất 7,2 m. Bản nháp ghi tháo cốp pha chịu lực khi bê tông đạt 50% R28 và lấy mẫu theo quy tắc của móng khối lớn. Hãy sửa ngưỡng tháo cốp pha và số tổ mẫu thí nghiệm, rồi lập báo cáo có căn cứ.",en:"As the site supervision engineer, you are reviewing the contractor's pour and stripping plan PP-0516 for the level 5 slab. The pour covers a 40 m x 30 m slab, 0.16 m thick, plus 30.6 m3 of beams; the longest beam span is 7.2 m. The draft strips load-bearing formwork at 50% of R28 and samples by the mass-foundation rule. Correct the stripping threshold and the number of test sample sets, then write an evidence-based report."},reference_title:{vi:"Chỉ dẫn kỹ thuật bê tông & bảng khối lượng đã duyệt",en:"Approved concrete specification & pour quantities"},fields:[{id:"STRIP_LEVEL",label:{vi:"Cường độ tối thiểu để tháo cốp pha chịu lực",en:"Minimum strength to strip load-bearing formwork"},initial:"50%R28",expected:"70%R28",choices:["50%R28","70%R28","90%R28"],reference:"Bảng tháo cốp pha chịu lực",ref_value:{vi:"Phân theo khẩu độ: dưới 2 m, từ 2 m đến 8 m, trên 8 m; nhịp lớn nhất của khối đổ 7,2 m",en:"By span: under 2 m, 2 m to 8 m, over 8 m; longest span in the pour 7.2 m"},hint:{vi:"Tra bảng: khẩu độ dưới 2 m cần 50%, từ 2 đến 8 m cần 70%, trên 8 m cần 90% R28; xét theo nhịp lớn nhất.",en:"Look up: spans under 2 m need 50%, 2 to 8 m need 70%, over 8 m need 90% of R28; use the longest span."}},{id:"SAMPLE_SETS",label:{vi:"Số tổ mẫu nén bê tông cho khối đổ",en:"Compression sample sets for the pour"},initial:"3",expected:"12",reference:"Bảng khối lượng khối đổ sàn tầng 5",ref_value:{vi:"Bản sàn 40 x 30 x 0,16 m; dầm 30,6 m3; kết cấu khung, dầm, sàn",en:"Slab 40 x 30 x 0.16 m; beams 30.6 m3; frame, beam and slab structure"},hint:{vi:"Bản nháp áp quy tắc 100 m3 một tổ của móng khối lớn; dầm và sàn là kết cấu mỏng.",en:"The draft used the 100 m3 per set rule for mass foundations; beams and slabs are thin members."}}],sop32:{vi:"Khối lượng khối đổ = thể tích bản sàn + thể tích dầm. Kết cấu khung, dầm, sàn: cứ 20 m3 bê tông lấy 1 tổ mẫu (3 viên); phần lẻ chưa đủ 20 m3 vẫn lấy thêm 1 tổ.",en:"Pour volume = slab volume + beam volume. Frames, beams and slabs: 1 sample set (3 specimens) per 20 m3 of concrete; any remainder below 20 m3 still requires one more set."},context:{label:"NHẬT KÝ THI CÔNG / PP-0516",metrics:[{label:{vi:"Diện tích sàn",en:"Slab area"},value:"1,200 m2"},{label:{vi:"Nhịp dầm lớn nhất",en:"Longest beam span"},value:"7.2 m"},{label:{vi:"Cấp độ bền bê tông",en:"Concrete strength class"},value:"B30"}]},crisis:{vi:"Chỉ huy trưởng nhà thầu: “Ngày thứ 5 tháo hết cốp pha sàn để quay vòng lên tầng 6, chậm là bị phạt tiến độ. Lấy 3 tổ mẫu là đủ, em ký biên bản nghiệm thu luôn cho anh.”",en:"The contractor's site manager: “We strip all slab formwork on day 5 to cycle it to level 6, or we pay delay penalties. Three sample sets are enough, just sign the acceptance record for me.”"},options:{safe:{vi:"Không ký; yêu cầu lấy đủ tổ mẫu theo khối lượng, chỉ tháo cốp pha chịu lực khi kết quả nén đạt ngưỡng; báo trưởng đoàn giám sát, đề xuất thêm bộ cốp pha hoặc chống lại để giữ tiến độ.",en:"Refuse to sign; require full sampling for the volume and strip load-bearing formwork only when test results reach the threshold; inform the chief supervisor and propose extra formwork or reshoring."},shortcut:{vi:"Ký biên bản và cho tháo ngày thứ 5 vì trời nắng nóng, bê tông chắc đã đủ cường độ.",en:"Sign the record and allow stripping on day 5 because hot weather surely gave enough strength."},wait:{vi:"Không ký nhưng cũng không báo ai, để nhà thầu tự quyết định ngày tháo cốp pha.",en:"Do not sign but tell no one, leaving the contractor to choose the stripping day."}},questions:{vi:["Giải thích vì sao ngưỡng tháo cốp pha phải là 70% R28 và cách bạn tính số tổ mẫu từ khối lượng khối đổ.","Nếu nhà thầu tự ý tháo sớm, bạn xử lý hiện trường và hồ sơ như thế nào để kiểm soát rủi ro sập đổ?"],en:["Explain why the stripping threshold must be 70% of R28 and how you derived the sample sets from the pour volume.","If the contractor strips early on its own, how do you handle the site and the records to control collapse risk?"]},hints:{vi:["Đặt kế hoạch nháp cạnh bảng tháo cốp pha chịu lực và đối chiếu với nhịp dầm lớn nhất của khối đổ.","Theo SOP mục 3.2, tính đủ thể tích sàn và dầm rồi chia theo quy tắc lấy mẫu của kết cấu mỏng, phần lẻ làm tròn lên.","SOP mục 4.2: tiến độ không thay thế được kết quả thí nghiệm; áp lực ký nghiệm thu phải báo trưởng đoàn."],en:["Place the draft plan next to the stripping table and compare it with the longest beam span in the pour.","Under SOP 3.2, add the full slab and beam volumes, then divide by the thin-member sampling rule and round up.","SOP 4.2: schedule never replaces test results; escalate any pressure to sign acceptance to the chief supervisor."]}},learning:{summary:{vi:"Kỹ sư giám sát thi công công trình dân dụng và công nghiệp kiểm soát chất lượng, khối lượng, tiến độ và an toàn tại hiện trường, bảo đảm công trình được thi công đúng thiết kế, chỉ dẫn kỹ thuật và quy chuẩn. Họ kiểm tra vật liệu đầu vào, nghiệm thu từng công việc, giám sát biện pháp thi công và lập hồ sơ quản lý chất lượng. Nghề cần kiến thức kết cấu, công nghệ thi công, kỹ năng phối hợp và bản lĩnh nói không với làm tắt.",en:"A site construction engineer for civil and industrial buildings controls quality, quantities, schedule and safety on site, making sure works follow the design, specifications and codes. They inspect incoming materials, accept each work stage, supervise construction methods and keep the quality records. The role needs structural and construction technology knowledge, coordination skills and the firmness to say no to shortcuts."},responsibilities:{vi:["Kiểm tra điều kiện khởi công, biện pháp thi công và kế hoạch kiểm soát chất lượng của nhà thầu.","Kiểm tra vật liệu, cấu kiện đầu vào, chứng chỉ xuất xưởng và kết quả thí nghiệm.","Giám sát và nghiệm thu từng công việc: cốp pha, cốt thép, bê tông, hoàn thiện.","Theo dõi an toàn lao động, vệ sinh môi trường và yêu cầu dừng thi công khi có nguy cơ mất an toàn.","Ghi nhật ký giám sát, lập báo cáo định kỳ và hoàn thiện hồ sơ hoàn công."],en:["Check start-up conditions, method statements and the contractor's quality control plan.","Inspect incoming materials and components, mill certificates and test results.","Supervise and accept each work stage: formwork, rebar, concrete and finishes.","Monitor safety and environment and order work to stop when there is an unsafe condition.","Keep the supervision log, issue periodic reports and complete as-built records."]},competencies:[{name:{vi:"Đọc và đối chiếu bản vẽ",en:"Drawing review"},desc:{vi:"Phát hiện sai khác giữa bản vẽ thi công, shop drawing và thực tế hiện trường.",en:"Spot differences between construction drawings, shop drawings and actual site conditions."}},{name:{vi:"Công nghệ bê tông",en:"Concrete technology"},desc:{vi:"Kiểm soát cấp phối, độ sụt, đổ, đầm, bảo dưỡng, lấy mẫu và thời điểm tháo cốp pha.",en:"Control mix design, slump, placing, compaction, curing, sampling and stripping time."}},{name:{vi:"Nghiệm thu & hồ sơ chất lượng",en:"Acceptance & quality records"},desc:{vi:"Lập biên bản, nhật ký và hồ sơ đủ căn cứ pháp lý cho từng giai đoạn.",en:"Prepare acceptance records, logs and files with full legal evidence for each stage."}},{name:{vi:"An toàn thi công",en:"Construction safety"},desc:{vi:"Nhận diện rủi ro sập đổ, ngã cao, điện và yêu cầu biện pháp khắc phục kịp thời.",en:"Identify collapse, fall and electrical risks and demand timely corrective measures."}},{name:{vi:"Bản lĩnh nghề nghiệp",en:"Professional firmness"},desc:{vi:"Giữ nguyên tắc kỹ thuật dưới áp lực tiến độ, báo cáo trung thực với chủ đầu tư.",en:"Hold technical principles under schedule pressure and report honestly to the client."}}],knowledge:{vi:["Nghị định 06/2021/NĐ-CP về quản lý chất lượng, thi công xây dựng và bảo trì công trình.","TCVN 4453:1995 - Kết cấu bê tông và bê tông cốt thép toàn khối: quy phạm thi công và nghiệm thu.","TCVN 5574:2018 - Thiết kế kết cấu bê tông và bê tông cốt thép, cấp độ bền chịu nén B.","Quy định hiện hành về an toàn lao động trong thi công xây dựng, giàn giáo và cốp pha.","Nguyên tắc lấy mẫu, bảo dưỡng và thí nghiệm nén mẫu bê tông theo tiêu chuẩn quốc gia."],en:["Decree 06/2021/ND-CP on quality management, construction and maintenance of works.","TCVN 4453:1995 - Monolithic concrete and reinforced concrete structures: code for construction and acceptance.","TCVN 5574:2018 - Design of concrete and reinforced concrete structures, compressive strength classes B.","Current regulations on occupational safety in construction, scaffolding and formwork.","Principles of sampling, curing and compression testing of concrete under national standards."]},tools:["Máy toàn đạc điện tử","Máy thủy bình","Súng bật nẩy kiểm tra bê tông","Côn đo độ sụt (côn Abrams)","Ứng dụng nhật ký công trình điện tử"],kpis:{vi:["Tỷ lệ công việc nghiệm thu đạt ngay lần đầu.","Số sự cố an toàn, chất lượng nghiêm trọng (mục tiêu bằng 0).","Tỷ lệ hồ sơ chất lượng hoàn thiện đồng bộ với tiến độ thi công.","Thời gian phản hồi yêu cầu nghiệm thu của nhà thầu."],en:["Share of work stages accepted first time.","Serious safety or quality incidents (target zero).","Share of quality records completed in step with construction progress.","Response time to contractor inspection requests."]},day:[{time:"07:00",vi:"Kiểm tra hiện trường đầu ca: giàn giáo, cốp pha, lan can an toàn, điện thi công.",en:"Walk the site at shift start: scaffolding, formwork, guardrails and temporary power."},{time:"08:30",vi:"Nghiệm thu cốt thép sàn tầng 5: đường kính, khoảng cách, lớp bê tông bảo vệ, nối buộc.",en:"Inspect level 5 slab rebar: diameter, spacing, cover and laps."},{time:"10:30",vi:"Kiểm tra phiếu giao bê tông, đo độ sụt, giám sát đổ, đầm và lấy mẫu.",en:"Check delivery tickets, test slump and supervise placing, compaction and sampling."},{time:"14:00",vi:"Họp giao ban với nhà thầu và chủ đầu tư về tiến độ, chất lượng, biện pháp tháo cốp pha.",en:"Hold the site meeting with contractor and client on schedule, quality and stripping method."},{time:"16:30",vi:"Ghi nhật ký giám sát, cập nhật hồ sơ chất lượng và báo cáo ngày.",en:"Write the supervision log, update quality records and the daily report."}],mistakes:{vi:["Cho tháo cốp pha chịu lực theo số ngày mà không có kết quả nén mẫu đạt ngưỡng.","Lấy thiếu tổ mẫu do áp quy tắc của móng khối lớn cho dầm, sàn.","Ký biên bản nghiệm thu trước khi kiểm tra thực tế hiện trường."],en:["Allowing load-bearing formwork removal by day count without test results at the threshold.","Taking too few sample sets by applying the mass-foundation rule to beams and slabs.","Signing acceptance records before inspecting the actual work on site."]},career:[{vi:"Kỹ thuật viên giám sát hiện trường",en:"Site inspection technician"},{vi:"Kỹ sư giám sát thi công",en:"Site supervision engineer"},{vi:"Giám sát trưởng hạng mục",en:"Lead supervisor for a work package"},{vi:"Trưởng đoàn tư vấn giám sát",en:"Chief supervision consultant"}],glossary:[{term:"R28",vi:"Cường độ chịu nén của bê tông ở tuổi 28 ngày, mốc để đánh giá cấp độ bền.",en:"Concrete compressive strength at 28 days, the benchmark for its strength class."},{term:"Tổ mẫu",vi:"Nhóm 3 viên mẫu bê tông lấy cùng lúc, cùng chỗ để thí nghiệm nén.",en:"A group of 3 concrete specimens taken together at the same location for compression testing."},{term:"Độ sụt",vi:"Chỉ tiêu tính công tác của hỗn hợp bê tông tươi, đo bằng côn tiêu chuẩn.",en:"Workability measure of fresh concrete, tested with the standard cone."},{term:"Reshoring",vi:"Chống lại tạm thời sau khi tháo cốp pha để kết cấu non tuổi không chịu tải vượt khả năng.",en:"Temporary re-propping after stripping so young concrete is not loaded beyond its capacity."},{term:"Shop drawing",vi:"Bản vẽ triển khai thi công chi tiết do nhà thầu lập trên cơ sở thiết kế đã duyệt.",en:"Detailed construction drawing prepared by the contractor from the approved design."}],quiz:[{q:{vi:"Khối đổ gồm sàn 90 m3 và dầm 25 m3 (kết cấu mỏng, 20 m3 một tổ, phần lẻ thêm 1 tổ). Cần bao nhiêu tổ mẫu?",en:"A pour has 90 m3 of slab and 25 m3 of beams (thin members, one set per 20 m3, remainder adds a set). How many sample sets?"},options:{vi:["5 tổ","6 tổ","2 tổ","12 tổ"],en:["5 sets","6 sets","2 sets","12 sets"]},answer:1,explain:{vi:"Tổng 115 m3 / 20 = 5,75, làm tròn lên thành 6 tổ mẫu.",en:"Total 115 m3 / 20 = 5.75, rounded up to 6 sample sets."}},{q:{vi:"Cốp pha đáy dầm khẩu độ 9 m chỉ được tháo khi bê tông đạt tối thiểu bao nhiêu phần trăm R28?",en:"Bottom formwork of a 9 m span beam may be stripped only when concrete reaches at least what percentage of R28?"},options:{vi:["50%","70%","100%","90%"],en:["50%","70%","100%","90%"]},answer:3,explain:{vi:"Bản, dầm khẩu độ trên 8 m cần đạt tối thiểu 90% R28 trước khi tháo cốp pha chịu lực.",en:"Slabs and beams spanning over 8 m need at least 90% of R28 before load-bearing formwork is removed."}},{q:{vi:"Nhà thầu muốn tháo cốp pha sớm để kịp tiến độ khi chưa có kết quả nén mẫu. Bạn làm gì?",en:"The contractor wants to strip formwork early for schedule before any test results exist. What do you do?"},options:{vi:["Không chấp thuận, yêu cầu kết quả thí nghiệm, báo trưởng đoàn và đề xuất chống lại hoặc thêm cốp pha","Đồng ý nếu thời tiết nắng nóng","Cho tháo một nửa sàn","Không ý kiến để nhà thầu tự chịu trách nhiệm"],en:["Refuse, require test results, inform the chief and propose reshoring or extra formwork","Agree if the weather is hot","Allow half the slab to be stripped","Say nothing and let the contractor take responsibility"]},answer:0,explain:{vi:"Tháo cốp pha khi chưa đủ cường độ có thể gây sập; giám sát phải dựa vào kết quả thí nghiệm và đề xuất giải pháp tiến độ an toàn.",en:"Stripping before strength is reached can cause collapse; supervision must rely on test results and offer safe schedule options."}},{q:{vi:"Độ sụt của hỗn hợp bê tông dùng để đánh giá đặc tính nào?",en:"What property does the slump of fresh concrete assess?"},options:{vi:["Cường độ chịu nén","Khả năng chống thấm","Tính công tác của hỗn hợp bê tông","Mô đun đàn hồi"],en:["Compressive strength","Water tightness","Workability of the fresh mix","Elastic modulus"]},answer:2,explain:{vi:"Độ sụt phản ánh tính công tác, ảnh hưởng đến việc đổ, đầm; nó không đo trực tiếp cường độ.",en:"Slump reflects workability, which affects placing and compaction; it does not measure strength directly."}}],tools_en:["Total station","Automatic level","Rebound hammer for concrete testing","Slump cone (Abrams cone)","Electronic site diary app"]}},"KK-633":{scenario:{company:"Ngân Hà BIM Studio",supervisor:{name:"Vũ Hoàng Nam",role:{vi:"Quản lý BIM dự án",en:"Project BIM Manager"}},ref_code:"BIM-0731",title:{vi:"Một tọa độ. Một mô hình liên kết. Không va chạm ẩn.",en:"One coordinate system. One federated model. No hidden clashes."},brief:{vi:"Bạn phối hợp mô hình liên kết BIM-0731 của tòa văn phòng 12 tầng. Mô hình MEP đang liên kết sai chế độ nên lệch so với kết cấu, sinh hàng nghìn xung đột giả. Ở hành lang tầng 3: trần hoàn thiện +2 700 mm, hệ khung trần dày 80 mm, khe hở lắp đặt dưới ống tối thiểu 50 mm; ống gió cao 350 mm, bảo ôn 25 mm, đáy dầm +3 250 mm. Hãy sửa chế độ liên kết và cao độ đáy ống gió tối thiểu (BOD), rồi lập báo cáo có căn cứ.",en:"You coordinate federated model BIM-0731 of a 12-storey office. The MEP model is linked in the wrong mode, so it sits offset from the structure and creates thousands of false clashes. Level 3 corridor: finished ceiling +2,700 mm, ceiling grid 80 mm deep, minimum gap under the duct 50 mm; duct 350 mm high with 25 mm insulation; beam soffit +3,250 mm. Correct the link mode and the minimum bottom of duct (BOD), then write an evidence-based report."},reference_title:{vi:"Kế hoạch thực hiện BIM & phiếu phối hợp trần đã duyệt",en:"Approved BIM execution plan & ceiling coordination sheet"},fields:[{id:"LINK_MODE",label:{vi:"Chế độ liên kết mô hình MEP",en:"MEP model link mode"},initial:"ORIGIN-TO-ORIGIN",expected:"SHARED-COORD",choices:["ORIGIN-TO-ORIGIN","SHARED-COORD","CENTER-TO-CENTER"],reference:"Kế hoạch thực hiện BIM (BEP) mục 4.3",ref_value:{vi:"Mọi mô hình bộ môn định vị theo hệ tọa độ chia sẻ lấy từ mô hình mốc khảo sát",en:"All discipline models are positioned by the shared coordinate system from the survey model"},hint:{vi:"Mô hình MEP được dựng với gốc nội bộ khác kết cấu; chỉ hệ tọa độ chia sẻ mới khớp vị trí thật.",en:"The MEP model was built on a different internal origin; only shared coordinates align true positions."}},{id:"BOD_MM",label:{vi:"Cao độ đáy ống gió tối thiểu BOD (mm)",en:"Minimum bottom of duct BOD (mm)"},initial:"2700",expected:"2830",reference:"Phiếu phối hợp trần hành lang tầng 3",ref_value:{vi:"Trần hoàn thiện +2 700; khung trần 80 mm; khe hở lắp đặt 50 mm; đáy dầm +3 250",en:"Finished ceiling +2,700; ceiling grid 80 mm; installation gap 50 mm; beam soffit +3,250"},hint:{vi:"Bản nháp đặt đáy ống đúng bằng mặt trần, chưa tính phần khung trần và khe hở lắp đặt.",en:"The draft sets the duct bottom at the ceiling face, ignoring the grid depth and installation gap."}}],sop32:{vi:"BOD tối thiểu = cao độ trần hoàn thiện + chiều dày hệ khung trần + khe hở lắp đặt. Sau đó kiểm tra: BOD + chiều cao ống + 2 x chiều dày bảo ôn phải không vượt cao độ đáy dầm.",en:"Minimum BOD = finished ceiling level + ceiling grid depth + installation gap. Then check: BOD + duct height + 2 x insulation thickness must not exceed the beam soffit level."},context:{label:"CDE / BIM-0731",metrics:[{label:{vi:"Xung đột cứng",en:"Hard clashes"},value:"1,284"},{label:{vi:"Lệch MEP so với kết cấu",en:"MEP offset from structure"},value:"18.400 m E / 6.250 m N"},{label:{vi:"Đáy dầm hành lang",en:"Corridor beam soffit"},value:"+3,250 mm"}]},terminal:{system:"bim-coord",settable:["LINK_MODE","BOD_MM"],commands:[{cmd:"status",out:{vi:"Mô hình liên kết: ARC_R24, STR_R24, MEP_R24; chế độ liên kết MEP: ORIGIN-TO-ORIGIN; 1 284 xung đột cứng mới ở lần chạy gần nhất",en:"Linked models: ARC_R24, STR_R24, MEP_R24; MEP link mode: ORIGIN-TO-ORIGIN; 1,284 new hard clashes in the latest run"}},{cmd:"coord check",out:{vi:"MEP so với STR: lệch 18,400 m hướng Đông, 6,250 m hướng Bắc, góc xoay 0°; ARC và STR khớp tọa độ chia sẻ",en:"MEP vs STR: offset 18.400 m East, 6.250 m North, rotation 0°; ARC and STR match on shared coordinates"}},{cmd:"cat bep.txt",out:{vi:"BEP 4.3: mọi mô hình định vị theo hệ tọa độ chia sẻ từ mô hình mốc khảo sát; dung sai va chạm cứng 10 mm",en:"BEP 4.3: all models positioned by shared coordinates from the survey model; hard clash tolerance 10 mm"}},{cmd:"clash top",out:{vi:"Nhóm lớn nhất khi đã bỏ lệch tọa độ: 46 va chạm giữa ống gió hành lang tầng 3 và trần, BOD đang đặt +2700",en:"Largest group once the offset is removed: 46 clashes between level 3 corridor ducts and the ceiling, BOD set at +2700"}},{cmd:"cat ceiling-spec.txt",out:{vi:"Trần hoàn thiện +2700; khung trần 80 mm; khe hở lắp đặt dưới ống tối thiểu 50 mm; đáy dầm +3250",en:"Finished ceiling +2700; ceiling grid 80 mm; minimum installation gap under duct 50 mm; beam soffit +3250"}}]},crisis:{vi:"Trước buổi họp với chủ đầu tư, giám đốc dự án nhắn: “Đánh dấu hết xung đột là Approved để báo cáo 0 va chạm, xuất bản vẽ phối hợp luôn. Ra công trường thợ tự xử lý được.”",en:"Before the client meeting the project director texts: “Mark every clash as Approved so we report zero clashes and issue the coordination drawings now. The site crews will sort it out.”"},options:{safe:{vi:"Không đánh dấu giả; liên kết lại theo tọa độ chia sẻ, chạy lại kiểm tra va chạm, báo quản lý BIM số xung đột thật và đề xuất họp phối hợp xử lý theo ưu tiên trước khi phát hành.",en:"Do not falsify statuses; relink by shared coordinates, rerun clash detection, report the real clash count to the BIM manager and propose a priority coordination meeting before issue."},shortcut:{vi:"Đánh dấu Approved toàn bộ xung đột để báo cáo đẹp, để công trường xử lý sau.",en:"Mark all clashes Approved for a clean report and let the site fix them later."},wait:{vi:"Hoãn báo cáo, không phát hành gì và chờ giám đốc dự án tự quyết.",en:"Postpone the report, issue nothing and wait for the project director to decide."}},questions:{vi:["Giải thích nguyên nhân hàng nghìn xung đột giả, vì sao liên kết theo tọa độ chia sẻ khắc phục được, và cách bạn xác định BOD.","Việc đánh dấu Approved hàng loạt gây rủi ro gì cho thi công và cho trách nhiệm pháp lý của nhóm BIM?"],en:["Explain the cause of thousands of false clashes, why shared coordinates fix it, and how you determined the BOD.","What risks does bulk-approving clashes create for construction and for the BIM team's liability?"]},hints:{vi:["Chạy lệnh kiểm tra tọa độ và đối chiếu với BEP trước khi xem xét từng xung đột riêng lẻ.","Theo SOP mục 3.2, cộng đủ các lớp nằm giữa mặt trần và đáy ống, rồi kiểm tra lại với đáy dầm.","SOP mục 4.2: trạng thái xung đột phải phản ánh đúng thực tế; áp lực làm đẹp báo cáo phải được báo lên trên."],en:["Run the coordinate check and compare it with the BEP before reviewing individual clashes.","Under SOP 3.2, add every layer between the ceiling face and the duct bottom, then check against the beam soffit.","SOP 4.2: clash statuses must reflect reality; escalate any pressure to dress up the report."]}},learning:{summary:{vi:"Kỹ sư mô hình thông tin công trình (BIM Coordinator) quản lý, liên kết và kiểm tra mô hình của các bộ môn kiến trúc, kết cấu, cơ điện trên môi trường dữ liệu chung (CDE). Họ phát hiện xung đột trước khi thi công, điều phối họp xử lý, kiểm soát quy ước đặt tên, mức độ phát triển và chất lượng dữ liệu. Nghề đòi hỏi hiểu kỹ thuật đa bộ môn, thành thạo phần mềm và quy trình quản lý thông tin theo ISO 19650.",en:"A BIM coordinator manages, federates and checks architectural, structural and MEP models in a common data environment (CDE). They detect clashes before construction, run resolution meetings and control naming conventions, level of development and data quality. The role requires multi-discipline technical understanding, software fluency and information management processes aligned with ISO 19650."},responsibilities:{vi:["Thiết lập hệ tọa độ chia sẻ, mẫu dự án và quy ước đặt tên theo kế hoạch thực hiện BIM (BEP).","Liên kết mô hình các bộ môn, chạy kiểm tra xung đột và phân loại theo mức ưu tiên.","Chủ trì họp phối hợp, giao việc xử lý qua BCF và theo dõi đến khi đóng.","Kiểm tra chất lượng mô hình: mức độ phát triển, thông tin thuộc tính, trạng thái phát hành trên CDE.","Trích xuất bản vẽ phối hợp, khối lượng và báo cáo tiến độ mô hình cho quản lý dự án."],en:["Set up shared coordinates, project templates and naming conventions per the BIM execution plan (BEP).","Federate discipline models, run clash detection and rank issues by priority.","Chair coordination meetings, assign fixes through BCF and track them to closure.","Check model quality: level of development, property data and publishing status in the CDE.","Extract coordination drawings, quantities and model progress reports for project management."]},competencies:[{name:{vi:"Phối hợp đa bộ môn",en:"Multi-discipline coordination"},desc:{vi:"Hiểu ràng buộc kiến trúc, kết cấu, cơ điện để đề xuất phương án tránh va chạm hợp lý.",en:"Understand architectural, structural and MEP constraints to propose sensible clash-free routes."}},{name:{vi:"Quản lý thông tin theo ISO 19650",en:"ISO 19650 information management"},desc:{vi:"Áp dụng CDE, mã trạng thái phù hợp, quy ước đặt tên và quy trình phê duyệt thông tin.",en:"Apply the CDE, suitability codes, naming conventions and information approval workflows."}},{name:{vi:"Kiểm tra xung đột",en:"Clash detection"},desc:{vi:"Thiết lập bộ kiểm tra, dung sai, lọc xung đột giả và nhóm xung đột theo nguyên nhân.",en:"Configure tests and tolerances, filter false clashes and group issues by root cause."}},{name:{vi:"Tự động hóa & dữ liệu",en:"Automation & data"},desc:{vi:"Dùng lập trình trực quan, bộ lọc và bảng thống kê để kiểm tra dữ liệu hàng loạt.",en:"Use visual scripting, filters and schedules to validate data at scale."}},{name:{vi:"Minh bạch & trách nhiệm",en:"Transparency & accountability"},desc:{vi:"Báo cáo đúng số liệu xung đột và tình trạng mô hình, không che giấu rủi ro.",en:"Report true clash counts and model status without hiding risks."}}],knowledge:{vi:["ISO 19650-1 và ISO 19650-2:2018 - Quản lý thông tin bằng BIM, giai đoạn chuyển giao tài sản.","Quyết định 258/QĐ-TTg năm 2023 phê duyệt lộ trình áp dụng BIM trong hoạt động xây dựng.","Định dạng trao đổi mở IFC (ISO 16739) và định dạng trao đổi vấn đề BCF của buildingSMART.","Đặc tả mức độ phát triển LOD 100-500 để quy định nội dung mô hình theo giai đoạn.","Nguyên tắc định vị: gốc nội bộ, điểm cơ sở dự án, điểm khảo sát và hệ tọa độ chia sẻ."],en:["ISO 19650-1 and ISO 19650-2:2018 - Information management using BIM, delivery phase of assets.","Decision 258/QD-TTg of 2023 approving the roadmap for BIM adoption in construction in Vietnam.","The open IFC exchange format (ISO 16739) and the buildingSMART BCF issue format.","LOD 100-500 specification defining model content by project stage.","Positioning principles: internal origin, project base point, survey point and shared coordinates."]},tools:["Phần mềm mô hình BIM kiến trúc, kết cấu, MEP","Phần mềm kiểm tra xung đột và mô phỏng 4D","Môi trường dữ liệu chung (CDE)","Trình xem IFC","Công cụ lập trình trực quan"],kpis:{vi:["Số xung đột cứng còn mở trước mỗi đợt phát hành bản vẽ.","Thời gian trung bình để đóng một vấn đề BCF.","Tỷ lệ mô hình đạt kiểm tra chất lượng ngay lần đầu.","Số yêu cầu thay đổi tại công trường do lỗi phối hợp."],en:["Open hard clashes before each drawing issue.","Average time to close a BCF issue.","Share of models passing quality checks first time.","Site change requests caused by coordination errors."]},day:[{time:"08:30",vi:"Tải mô hình mới nhất của các bộ môn từ CDE, kiểm tra tọa độ và trạng thái phát hành.",en:"Download the latest discipline models from the CDE and check coordinates and status."},{time:"10:00",vi:"Chạy kiểm tra xung đột, lọc xung đột giả và nhóm theo khu vực, hệ thống.",en:"Run clash tests, filter false clashes and group them by zone and system."},{time:"13:30",vi:"Chủ trì họp phối hợp, thống nhất phương án và giao việc qua BCF.",en:"Chair the coordination meeting, agree solutions and assign actions through BCF."},{time:"15:30",vi:"Kiểm tra thông tin thuộc tính và mức độ phát triển của mô hình theo BEP.",en:"Check property data and level of development against the BEP."},{time:"17:00",vi:"Cập nhật báo cáo xung đột, xuất bản vẽ phối hợp và lưu vết trên CDE.",en:"Update the clash report, issue coordination drawings and log the trail in the CDE."}],mistakes:{vi:["Liên kết mô hình theo gốc nội bộ thay vì tọa độ chia sẻ, tạo hàng loạt xung đột giả.","Đặt dung sai kiểm tra bằng 0 hoặc quá lớn, làm nhiễu hoặc bỏ sót xung đột thật.","Đánh dấu xung đột đã duyệt để làm đẹp báo cáo khi chưa có phương án xử lý."],en:["Linking models origin to origin instead of by shared coordinates, creating mass false clashes.","Setting the clash tolerance to zero or too large, causing noise or missed real clashes.","Marking clashes approved to dress up the report before any solution exists."]},career:[{vi:"Dựng hình BIM (BIM Modeler)",en:"BIM modeler"},{vi:"Điều phối BIM (BIM Coordinator)",en:"BIM coordinator"},{vi:"Quản lý BIM dự án",en:"Project BIM manager"},{vi:"Giám đốc chuyển đổi số xây dựng",en:"Digital construction director"}],glossary:[{term:"CDE",vi:"Môi trường dữ liệu chung để lưu, chia sẻ và phê duyệt thông tin dự án theo trạng thái.",en:"Common data environment to store, share and approve project information by status."},{term:"BEP",vi:"Kế hoạch thực hiện BIM quy định vai trò, tiêu chuẩn, tọa độ, phần mềm và quy trình trao đổi.",en:"BIM execution plan defining roles, standards, coordinates, software and exchange processes."},{term:"Clash detection",vi:"Kiểm tra tự động va chạm cứng, va chạm mềm giữa các đối tượng trong mô hình liên kết.",en:"Automated check for hard and soft clashes between objects in a federated model."},{term:"LOD",vi:"Mức độ phát triển của đối tượng mô hình, thể hiện độ chi tiết hình học và độ tin cậy thông tin.",en:"Level of development of model elements, expressing geometric detail and information reliability."},{term:"Shared coordinates",vi:"Hệ tọa độ chung gắn với mốc khảo sát, giúp mọi mô hình định vị đúng vị trí thực.",en:"Common coordinate system tied to survey control so every model sits at its true location."}],quiz:[{q:{vi:"Trần hoàn thiện +2 600 mm, khung trần 100 mm, khe hở lắp đặt 50 mm. BOD tối thiểu là bao nhiêu?",en:"Finished ceiling +2,600 mm, ceiling grid 100 mm, installation gap 50 mm. What is the minimum BOD?"},options:{vi:["+2 600 mm","+2 700 mm","+2 750 mm","+2 650 mm"],en:["+2,600 mm","+2,700 mm","+2,750 mm","+2,650 mm"]},answer:2,explain:{vi:"Cộng cao độ trần, chiều dày khung trần và khe hở lắp đặt: BOD = 2 600 + 100 + 50 = +2 750 mm.",en:"BOD = 2,600 + 100 + 50 = +2,750 mm."}},{q:{vi:"Bộ tiêu chuẩn quốc tế nào hướng dẫn quản lý thông tin dự án bằng BIM?",en:"Which international series guides project information management using BIM?"},options:{vi:["ISO 9001","ISO 19650","ISO 14001","ISO 45001"],en:["ISO 9001","ISO 19650","ISO 14001","ISO 45001"]},answer:1,explain:{vi:"ISO 19650 quy định khái niệm, CDE và quy trình quản lý thông tin bằng BIM.",en:"ISO 19650 sets the concepts, the CDE and the processes for information management using BIM."}},{q:{vi:"Giám đốc dự án yêu cầu đánh dấu toàn bộ xung đột là Approved trước buổi họp. Bạn làm gì?",en:"The project director asks you to mark every clash as Approved before the meeting. What do you do?"},options:{vi:["Làm theo vì là yêu cầu cấp trên","Đánh dấu một nửa số xung đột","Xóa bớt xung đột khỏi báo cáo","Từ chối làm giả, báo cáo số liệu thật và đề xuất kế hoạch xử lý"],en:["Comply because a superior asked","Mark half of the clashes","Remove some clashes from the report","Refuse to falsify, report real figures and propose a resolution plan"]},answer:3,explain:{vi:"Trạng thái giả che giấu rủi ro thi công và làm sai lệch hồ sơ; cần minh bạch kèm kế hoạch xử lý.",en:"False statuses hide construction risk and corrupt the record; transparency with a resolution plan is required."}},{q:{vi:"Mô hình MEP lệch 18 m so với kết cấu dù hình học đúng. Nguyên nhân thường gặp nhất là gì?",en:"The MEP model is 18 m away from the structure though its geometry is correct. What is the most common cause?"},options:{vi:["Liên kết theo gốc nội bộ thay vì tọa độ chia sẻ","Thiếu lớp bảo ôn ống gió","Thiếu thông tin thuộc tính","Sai mức độ phát triển LOD"],en:["Linked by internal origin instead of shared coordinates","Missing duct insulation","Missing property data","Wrong LOD"]},answer:0,explain:{vi:"Lệch tịnh tiến đều giữa các mô hình là dấu hiệu điển hình của việc không dùng hệ tọa độ chia sẻ.",en:"A uniform translation between models is the classic sign that shared coordinates were not used."}}],tools_en:["Architectural, structural and MEP BIM software","Clash detection and 4D simulation software","Common data environment (CDE)","IFC viewer","Visual programming tool"]}},"KK-634":{scenario:{company:"Thiên Trường Structural Engineering",supervisor:{name:"Lương Thế Hiển",role:{vi:"Chủ trì thiết kế kết cấu",en:"Lead Structural Engineer"}},ref_code:"STR-1207",title:{vi:"Đúng công năng. Đúng tải trọng. Đúng an toàn.",en:"Right use. Right load. Right safety margin."},brief:{vi:"Bạn kiểm tra lại thuyết minh STR-1207 cho dầm B3-12 tầng 3 (dầm đơn giản, nhịp 7,2 m, bề rộng chịu tải 2,4 m). Kiến trúc vừa phát hành REV C đổi phòng 3.12 từ văn phòng sang kho lưu trữ hồ sơ. Tĩnh tải tiêu chuẩn trên dầm g = 18 kN/m; hoạt tải tiêu chuẩn mô phỏng: văn phòng 2,0 kPa, kho lưu trữ 5,0 kPa. Hãy sửa loại hoạt tải và mô men uốn tính toán lớn nhất, rồi lập báo cáo có căn cứ.",en:"You are re-checking calculation report STR-1207 for beam B3-12 on level 3 (simply supported, span 7.2 m, tributary width 2.4 m). Architecture has just issued REV C changing room 3.12 from office to archive storage. The characteristic dead load on the beam is g = 18 kN/m; simulated characteristic live loads are 2.0 kPa for offices and 5.0 kPa for archive storage. Correct the live load class and the maximum design bending moment, then write an evidence-based report."},reference_title:{vi:"Bản vẽ kiến trúc REV C & bảng tải trọng đã duyệt",en:"Architecture REV C & approved load schedule"},fields:[{id:"LL_CLASS",label:{vi:"Loại hoạt tải áp cho phòng 3.12",en:"Live load class for room 3.12"},initial:"LL-OFFICE",expected:"LL-STORAGE",choices:["LL-OFFICE","LL-STORAGE","LL-CORRIDOR"],reference:"Bản vẽ kiến trúc REV C",ref_value:{vi:"REV C: phòng 3.12 đổi công năng từ văn phòng sang kho lưu trữ hồ sơ",en:"REV C: room 3.12 changed from office to archive storage"},hint:{vi:"Tải trọng phải theo công năng mới nhất của phòng, không theo bản vẽ phát hành trước.",en:"Loads must follow the room's latest use, not the earlier drawing issue."}},{id:"M_ULS",label:{vi:"Mô men uốn tính toán lớn nhất (kNm)",en:"Maximum design bending moment (kNm)"},initial:"165.6",expected:"221.6",reference:"Bảng tổ hợp tải trọng dầm B3-12",ref_value:{vi:"g = 18 kN/m; hoạt tải theo công năng x bề rộng 2,4 m; nhịp 7,2 m",en:"g = 18 kN/m; live load by use x 2.4 m width; span 7.2 m"},hint:{vi:"Bản nháp vẫn dùng hoạt tải văn phòng; đổi tải theo m2 sang tải theo m dài trước khi tổ hợp.",en:"The draft still uses the office live load; convert the area load to a line load before combining."}}],sop32:{vi:"p = hoạt tải tiêu chuẩn (kPa) x bề rộng chịu tải; q = 1,1 x g + 1,2 x p (hệ số độ tin cậy mô phỏng); dầm đơn giản: M = q x L^2 / 8; ghi M đến 0,1 kNm.",en:"p = characteristic live load (kPa) x tributary width; q = 1.1 x g + 1.2 x p (simulated load factors); simply supported beam: M = q x L^2 / 8; state M to 0.1 kNm."},context:{label:"FEM / STR-1207",metrics:[{label:{vi:"Nhịp dầm",en:"Beam span"},value:"7.2 m"},{label:{vi:"Bề rộng chịu tải",en:"Tributary width"},value:"2.4 m"},{label:{vi:"Tĩnh tải tiêu chuẩn g",en:"Characteristic dead load g"},value:"18 kN/m"}]},terminal:{system:"struct-solver",settable:["LL_CLASS","M_ULS"],commands:[{cmd:"status",out:{vi:"Mô hình STR-1207 đồng bộ kiến trúc REV B; dầm B3-12: hoạt tải LL-OFFICE, M = 165,6 kNm, tỷ số sử dụng 0,78",en:"Model STR-1207 synced to architecture REV B; beam B3-12: live load LL-OFFICE, M = 165.6 kNm, utilization 0.78"}},{cmd:"cat arch-rev.txt",out:{vi:"REV C (phát hành hôm nay): phòng 3.12 đổi từ văn phòng sang kho lưu trữ hồ sơ, giá kệ cao 2,4 m",en:"REV C (issued today): room 3.12 changed from office to archive storage with 2.4 m high shelving"}},{cmd:"cat loads.txt",out:{vi:"Hoạt tải tiêu chuẩn (mô phỏng): văn phòng 2,0 kPa; hành lang 3,0 kPa; kho lưu trữ 5,0 kPa",en:"Characteristic live loads (simulated): office 2.0 kPa; corridor 3.0 kPa; archive storage 5.0 kPa"}},{cmd:"beam info b3-12",out:{vi:"Dầm đơn giản, nhịp 7,2 m, bề rộng chịu tải 2,4 m, tĩnh tải tiêu chuẩn g = 18 kN/m, tiết diện 300 x 600 mm",en:"Simply supported, span 7.2 m, tributary width 2.4 m, characteristic dead load g = 18 kN/m, section 300 x 600 mm"}},{cmd:"run check b3-12",out:{vi:"Cảnh báo: dữ liệu công năng chưa cập nhật REV C; kết quả kiểm tra hiện tại không còn hiệu lực",en:"Warning: occupancy data not updated to REV C; the current check results are no longer valid"}}]},crisis:{vi:"Chủ nhiệm đồ án nhắn: “Sáng mai phải nộp hồ sơ thẩm định. Cứ giữ tải văn phòng, đóng dấu phát hành đi, kho lưu trữ thì sau này chủ đầu tư tự hạn chế xếp hàng.”",en:"The design manager texts: “The submission for appraisal is due tomorrow morning. Keep the office load and stamp it for issue; the owner can just limit storage later.”"},options:{safe:{vi:"Không phát hành bản tính sai tải; cập nhật hoạt tải theo REV C, kiểm tra lại tiết diện, cốt thép và báo chủ trì kết cấu; đề nghị lùi hạn nộp hoặc nộp kèm danh mục hạng mục đang hiệu chỉnh.",en:"Do not issue a calculation with the wrong load; update the live load to REV C, recheck section and reinforcement and inform the lead engineer; request an extension or submit with a list of items under revision."},shortcut:{vi:"Giữ tải văn phòng và đóng dấu phát hành cho kịp hạn, ghi chú hạn chế tải sau.",en:"Keep the office load and stamp the issue to meet the deadline, adding a load restriction note later."},wait:{vi:"Không phát hành nhưng cũng không báo ai, chờ chủ nhiệm đồ án tự phát hiện.",en:"Do not issue but tell no one, waiting for the design manager to notice."}},questions:{vi:["Trình bày cách bạn tính lại q và M sau khi đổi công năng, và hệ quả đối với tỷ số sử dụng của dầm B3-12.","Nếu hồ sơ sai tải đã được phát hành, bạn xử lý thế nào để thu hồi, cập nhật và kiểm soát rủi ro an toàn?"],en:["Explain how you recalculated q and M after the change of use, and the effect on the utilization of beam B3-12.","If the drawings with the wrong load were already issued, how would you withdraw, update and control the safety risk?"]},hints:{vi:["Mở bản vẽ kiến trúc mới nhất và kiểm tra công năng phòng 3.12 trước khi xem kết quả tính.","Theo SOP mục 3.2, đổi hoạt tải từ kPa sang kN/m, nhân hệ số rồi mới tính mô men giữa nhịp.","SOP mục 4.2: không đóng dấu hồ sơ khi dữ liệu đầu vào đã thay đổi; áp lực tiến độ phải báo chủ trì kết cấu."],en:["Open the latest architectural drawing and check the use of room 3.12 before reading the results.","Under SOP 3.2, convert the live load from kPa to kN/m and apply the factors before computing the midspan moment.","SOP 4.2: never stamp drawings when the input data has changed; escalate schedule pressure to the lead engineer."]}},learning:{summary:{vi:"Kỹ sư thiết kế kết cấu xác định tải trọng, lập mô hình phân tích, tính toán và thể hiện bản vẽ cho móng, cột, dầm, sàn, vách của công trình, bảo đảm khả năng chịu lực, độ cứng, ổn định và độ bền lâu dài. Họ phối hợp với kiến trúc, cơ điện và nhà thầu để giải pháp kết cấu vừa an toàn vừa kinh tế. Nghề đòi hỏi nền tảng cơ học vững, hiểu tiêu chuẩn thiết kế và tinh thần trách nhiệm với an toàn cộng đồng.",en:"A structural design engineer defines loads, builds analysis models, designs and details foundations, columns, beams, slabs and walls, ensuring strength, stiffness, stability and durability. They coordinate with architecture, MEP and contractors so the structural solution is both safe and economical. The role requires strong mechanics, command of the design codes and a deep sense of responsibility for public safety."},responsibilities:{vi:["Xác định tải trọng và tác động: tĩnh tải, hoạt tải, gió, động đất theo công năng và vị trí công trình.","Lập mô hình phân tích, tổ hợp tải trọng và kiểm tra các trạng thái giới hạn.","Thiết kế tiết diện, bố trí cốt thép, liên kết và lập bản vẽ kết cấu thi công.","Phối hợp với kiến trúc, cơ điện về lỗ mở, cao độ, thay đổi công năng và trả lời câu hỏi kỹ thuật.","Soát xét chéo bản tính, quản lý phiên bản hồ sơ và giám sát tác giả tại công trường."],en:["Define loads and actions: dead, live, wind and seismic according to use and site.","Build analysis models, combine loads and check the limit states.","Design sections, reinforcement and connections and prepare structural construction drawings.","Coordinate openings, levels and changes of use with architecture and MEP and answer technical queries.","Peer-review calculations, control document revisions and provide designer supervision on site."]},competencies:[{name:{vi:"Cơ học kết cấu",en:"Structural mechanics"},desc:{vi:"Hiểu sự làm việc của hệ chịu lực, nội lực, biến dạng và đường truyền tải.",en:"Understand how structural systems carry load, internal forces, deformation and load paths."}},{name:{vi:"Tiêu chuẩn thiết kế",en:"Design codes"},desc:{vi:"Áp dụng đúng tiêu chuẩn bê tông cốt thép, thép, tải trọng và động đất hiện hành.",en:"Apply current concrete, steel, loading and seismic standards correctly."}},{name:{vi:"Mô hình hóa & phần mềm",en:"Modelling & software"},desc:{vi:"Lập mô hình phần tử hữu hạn đúng điều kiện biên và kiểm tra tính hợp lý của kết quả.",en:"Build finite element models with correct boundary conditions and sanity-check results."}},{name:{vi:"Quản lý thay đổi",en:"Change management"},desc:{vi:"Cập nhật kịp thời khi kiến trúc, công năng hay tải thiết bị thay đổi.",en:"Update promptly when architecture, use or equipment loads change."}},{name:{vi:"Trách nhiệm an toàn",en:"Safety accountability"},desc:{vi:"Không phát hành hồ sơ khi chưa kiểm tra đủ; báo cáo trung thực khi phát hiện sai sót.",en:"Never issue unchecked documents; report honestly when errors are found."}}],knowledge:{vi:["TCVN 2737:2023 - Tải trọng và tác động: tiêu chuẩn thiết kế.","TCVN 5574:2018 - Thiết kế kết cấu bê tông và bê tông cốt thép.","TCVN 5575:2012 - Thiết kế kết cấu thép.","TCVN 9386:2012 - Thiết kế công trình chịu động đất.","Nghị định 06/2021/NĐ-CP về quản lý chất lượng, thi công xây dựng và bảo trì công trình.","Nguyên lý trạng thái giới hạn, tổ hợp tải trọng và hệ số độ tin cậy."],en:["TCVN 2737:2023 - Loads and actions: design standard.","TCVN 5574:2018 - Design of concrete and reinforced concrete structures.","TCVN 5575:2012 - Design of steel structures.","TCVN 9386:2012 - Design of structures for earthquake resistance.","Decree 06/2021/ND-CP on quality management, construction and maintenance of works.","Limit state principles, load combinations and partial load factors."]},tools:["Phần mềm phân tích phần tử hữu hạn nhà cao tầng","Phần mềm thiết kế móng và sàn","Phần mềm mô hình BIM kết cấu","Bảng tính kiểm tra tiết diện","Phần mềm thể hiện bản vẽ CAD"],kpis:{vi:["Số lỗi kết cấu phát hiện sau phát hành (mục tiêu bằng 0).","Tỷ lệ hồ sơ qua thẩm tra không phải chỉnh sửa lớn.","Chỉ tiêu vật liệu (kg thép/m2 sàn) so với mục tiêu dự án.","Thời gian trả lời yêu cầu làm rõ kỹ thuật (RFI)."],en:["Structural errors found after issue (target zero).","Share of designs passing review without major changes.","Material index (kg of rebar per m2 of floor) against the project target.","Response time to requests for information (RFI)."]},day:[{time:"08:00",vi:"Đọc thông báo thay đổi kiến trúc, cơ điện và cập nhật danh sách việc.",en:"Read architectural and MEP change notices and update the task list."},{time:"09:00",vi:"Cập nhật tải trọng, chạy lại mô hình phân tích và kiểm tra chuyển vị, dao động.",en:"Update loads, rerun the analysis model and check drift and vibration."},{time:"13:30",vi:"Thiết kế cốt thép dầm, sàn, kiểm tra cấu tạo và lỗ mở kỹ thuật.",en:"Design beam and slab reinforcement and check detailing and service openings."},{time:"15:30",vi:"Soát xét chéo bản tính của đồng nghiệp, ghi nhận lỗi và đề xuất sửa.",en:"Peer-review a colleague's calculations, log findings and propose fixes."},{time:"17:00",vi:"Trả lời RFI từ công trường và lưu phiên bản hồ sơ.",en:"Answer site RFIs and file the document revision."}],mistakes:{vi:["Không cập nhật tải trọng khi kiến trúc đổi công năng phòng.","Quên đổi tải phân bố trên diện tích sang tải trên chiều dài theo bề rộng chịu tải.","Tin tuyệt đối kết quả phần mềm mà không kiểm tra bằng tính tay đơn giản."],en:["Not updating loads when architecture changes a room's use.","Forgetting to convert area loads to line loads using the tributary width.","Trusting software output blindly without a simple hand check."]},career:[{vi:"Kỹ sư kết cấu tập sự",en:"Graduate structural engineer"},{vi:"Kỹ sư thiết kế kết cấu",en:"Structural design engineer"},{vi:"Chủ trì thiết kế kết cấu",en:"Lead structural engineer"},{vi:"Giám đốc kỹ thuật kết cấu",en:"Structural engineering director"}],glossary:[{term:"ULS",vi:"Trạng thái giới hạn thứ nhất: kết cấu phải đủ khả năng chịu lực, không phá hoại, không mất ổn định.",en:"Ultimate limit state: the structure must resist loads without failure or loss of stability."},{term:"SLS",vi:"Trạng thái giới hạn thứ hai: kiểm soát độ võng, nứt, dao động trong sử dụng bình thường.",en:"Serviceability limit state: controls deflection, cracking and vibration in normal use."},{term:"Tributary width",vi:"Bề rộng diện truyền tải lên cấu kiện, dùng để đổi tải trên m2 thành tải trên m dài.",en:"Width of floor area loading a member, used to convert area loads into line loads."},{term:"Hệ số độ tin cậy",vi:"Hệ số nhân với tải tiêu chuẩn để ra tải tính toán, kể đến sai lệch bất lợi của tải trọng.",en:"Factor applied to characteristic loads to obtain design loads, covering unfavourable deviations."},{term:"Utilization ratio",vi:"Tỷ số giữa nội lực tính toán và khả năng chịu lực; lớn hơn 1 nghĩa là cấu kiện không đạt.",en:"Ratio of design action effect to resistance; above 1 means the member fails the check."}],quiz:[{q:{vi:"Dầm đơn giản nhịp 6 m chịu tải tính toán phân bố đều q = 20 kN/m. Mô men uốn lớn nhất là bao nhiêu?",en:"A simply supported 6 m beam carries a uniform design load q = 20 kN/m. What is the maximum bending moment?"},options:{vi:["60 kNm","120 kNm","90 kNm","180 kNm"],en:["60 kNm","120 kNm","90 kNm","180 kNm"]},answer:2,explain:{vi:"Với dầm đơn giản chịu tải phân bố đều: M = q x L^2 / 8 = 20 x 36 / 8 = 90 kNm.",en:"M = q x L^2 / 8 = 20 x 36 / 8 = 90 kNm."}},{q:{vi:"Hoạt tải sàn 4,0 kPa, bề rộng chịu tải của dầm 3 m. Tải phân bố trên dầm là bao nhiêu?",en:"The floor live load is 4.0 kPa and the beam tributary width is 3 m. What is the line load on the beam?"},options:{vi:["12 kN/m","4 kN/m","1,33 kN/m","7 kN/m"],en:["12 kN/m","4 kN/m","1.33 kN/m","7 kN/m"]},answer:0,explain:{vi:"Tải trên m dài = 4,0 kPa x 3 m = 12 kN/m.",en:"Line load = 4.0 kPa x 3 m = 12 kN/m."}},{q:{vi:"Hồ sơ phải nộp sáng mai nhưng bạn phát hiện tải trọng chưa cập nhật theo công năng mới. Bạn làm gì?",en:"The submission is due tomorrow but you find loads not updated for the new use. What do you do?"},options:{vi:["Đóng dấu phát hành rồi sửa sau","Tự giảm hệ số an toàn cho đủ","Nộp mà không báo ai","Không phát hành bản sai, cập nhật tính toán, báo chủ trì và đề nghị lùi hạn"],en:["Stamp and issue, then fix later","Lower the safety factors until it passes","Submit without telling anyone","Do not issue the wrong version, update it, inform the lead and request an extension"]},answer:3,explain:{vi:"Phát hành bản tính sai tải đe dọa an toàn công trình; phải cập nhật, báo cáo và điều chỉnh tiến độ minh bạch.",en:"Issuing a calculation with wrong loads endangers the building; update, report and adjust the schedule transparently."}},{q:{vi:"Trạng thái giới hạn thứ hai (SLS) kiểm tra nội dung nào?",en:"What does the serviceability limit state (SLS) check?"},options:{vi:["Khả năng chịu lực phá hoại","Độ võng, bề rộng vết nứt và dao động","Ổn định chống lật tổng thể","Cường độ vật liệu ở tuổi 28 ngày"],en:["Failure resistance","Deflection, crack width and vibration","Overall overturning stability","Material strength at 28 days"]},answer:1,explain:{vi:"SLS bảo đảm công trình sử dụng bình thường: võng, nứt, dao động trong giới hạn cho phép.",en:"SLS ensures normal use: deflection, cracking and vibration stay within limits."}}],tools_en:["High-rise finite element analysis software","Foundation and slab design software","Structural BIM modeling software","Section capacity check spreadsheet","CAD drafting software"]}},"KK-635":{scenario:{company:"Hải Đăng MEP Services",supervisor:{name:"Phan Thị Mỹ Linh",role:{vi:"Trưởng bộ phận Cơ điện & PCCC",en:"Head of MEP & Fire Protection"}},ref_code:"FP-0419",title:{vi:"Bơm luôn sẵn sàng. Điểm đặt đúng. Biên bản trung thực.",en:"Pumps always ready. Setpoints right. Records honest."},brief:{vi:"Bạn soát xét biên bản chạy thử FP-0419 của cụm bơm chữa cháy sprinkler tại một trung tâm thương mại sau bảo trì. Bơm chính điện FP-01 có áp lực ngắt (churn) 9,6 bar; áp lực tĩnh tối thiểu phía hút 1,2 bar. Bản nháp để tủ bơm chính ở chế độ tay và đặt áp lực khởi động bơm chính trùng với bơm bù. Hãy sửa chế độ tủ điều khiển và áp lực khởi động bơm chính (bar), rồi lập báo cáo có căn cứ.",en:"You are reviewing test record FP-0419 for the sprinkler fire pump set of a shopping centre after maintenance. Electric main pump FP-01 has a churn pressure of 9.6 bar; the minimum static suction pressure is 1.2 bar. The draft leaves the main pump controller in manual mode and sets the main pump start pressure equal to the jockey pump start. Correct the controller mode and the main pump start pressure (bar), then write an evidence-based report."},reference_title:{vi:"Quy trình bàn giao PCCC & bảng điểm đặt áp lực đã duyệt",en:"Approved fire handover procedure & pressure setpoint sheet"},fields:[{id:"CTRL_MODE",label:{vi:"Chế độ tủ điều khiển bơm chính FP-01",en:"FP-01 main pump controller mode"},initial:"MANUAL",expected:"AUTO",choices:["AUTO","MANUAL","OFF"],reference:"Quy trình bàn giao hệ thống PCCC",ref_value:{vi:"Sau bảo trì, bơm chữa cháy phải tự khởi động khi áp lực mạng giảm; chế độ tay chỉ dùng khi có phiếu tạm ngừng",en:"After maintenance fire pumps must start on pressure drop; manual mode only under an impairment permit"},hint:{vi:"Ở chế độ tay, bơm chính không tự chạy khi đầu phun mở; hệ thống mất khả năng chữa cháy tự động.",en:"In manual mode the main pump will not start when a sprinkler opens; automatic protection is lost."}},{id:"START_BAR",label:{vi:"Áp lực khởi động bơm chính (bar)",en:"Main pump start pressure (bar)"},initial:"10.1",expected:"9.75",reference:"Bảng điểm đặt áp lực bơm",ref_value:{vi:"Áp lực churn FP-01 9,6 bar; áp lực tĩnh phía hút tối thiểu 1,2 bar",en:"FP-01 churn pressure 9.6 bar; minimum static suction pressure 1.2 bar"},hint:{vi:"Bản nháp cho bơm chính khởi động cùng mức với bơm bù; cần lùi thêm một bậc theo SOP 3.2.",en:"The draft starts the main pump at the jockey start level; step down once more per SOP 3.2."}}],sop32:{vi:"Áp lực dừng bơm bù = áp lực churn bơm chính + áp lực tĩnh hút tối thiểu; bơm bù khởi động thấp hơn mức dừng 0,7 bar; bơm chính khởi động thấp hơn mức khởi động bơm bù 0,35 bar (số liệu mô phỏng).",en:"Jockey stop = main pump churn + minimum static suction; jockey start = 0.7 bar below jockey stop; main pump start = 0.35 bar below jockey start (simulated values)."},context:{label:"BMS / FP-0419",metrics:[{label:{vi:"Định mức FP-01",en:"FP-01 rating"},value:"2,000 L/min @ 8.0 bar"},{label:{vi:"Áp lực churn",en:"Churn pressure"},value:"9.6 bar"},{label:{vi:"Số lần bơm bù chạy",en:"Jockey pump starts"},value:"46 / h"}]},terminal:{system:"fire-pump-ctl",settable:["CTRL_MODE","START_BAR"],commands:[{cmd:"status",out:{vi:"FP-01 (bơm chính điện): MANUAL; JP-01 (bơm bù): AUTO; áp lực mạng hiện tại 10,6 bar",en:"FP-01 (electric main pump): MANUAL; JP-01 (jockey pump): AUTO; current system pressure 10.6 bar"}},{cmd:"cat setpoints.cfg",out:{vi:"JP-01 dừng 10,8 bar, khởi động 10,1 bar; FP-01 khởi động 10,1 bar (trùng bơm bù)",en:"JP-01 stop 10.8 bar, start 10.1 bar; FP-01 start 10.1 bar (same as jockey)"}},{cmd:"cat pump-curve.txt",out:{vi:"FP-01: định mức 2 000 L/phút tại 8,0 bar; áp lực churn 9,6 bar; tại 150% lưu lượng còn 5,6 bar",en:"FP-01: rated 2,000 L/min at 8.0 bar; churn 9.6 bar; 5.6 bar at 150% flow"}},{cmd:"cat suction.txt",out:{vi:"Bể nước chữa cháy: áp lực tĩnh tối thiểu tại đầu hút 1,2 bar",en:"Fire water tank: minimum static pressure at the suction 1.2 bar"}},{cmd:"cat event.log",out:{vi:"02:10 mở van xả thử: áp giảm còn 9,4 bar, FP-01 không khởi động (MANUAL); JP-01 chạy 46 lần mỗi giờ",en:"02:10 test valve opened: pressure fell to 9.4 bar, FP-01 did not start (MANUAL); JP-01 cycled 46 times per hour"}}]},crisis:{vi:"Trưởng ban quản lý tòa nhà: “Để AUTO thì bơm bù chạy liên tục, khách thuê kêu ồn. Cứ để MANUAL, biên bản ghi AUTO cho đoàn kiểm tra PCCC sáng mai, có cháy thì bảo vệ xuống bật tay.”",en:"The building manager: “On AUTO the jockey pump runs nonstop and tenants complain about noise. Leave it on MANUAL, write AUTO in the record for tomorrow's fire inspection; in a fire, security can start it by hand.”"},options:{safe:{vi:"Không ghi sai biên bản; đặt lại điểm đặt, chuyển AUTO và xử lý rò rỉ làm bơm bù chạy liên tục; báo trưởng bộ phận, chủ đầu tư; nếu phải tạm ngừng thì lập phiếu suy giảm hệ thống và trực cháy.",en:"Do not falsify the record; reset the setpoints, switch to AUTO and fix the leak behind the jockey cycling; inform the department head and owner; if shutdown is needed, use an impairment permit and fire watch."},shortcut:{vi:"Để MANUAL cho yên tĩnh, ghi AUTO vào biên bản và dặn bảo vệ bật tay khi có cháy.",en:"Leave it on MANUAL for quiet, write AUTO in the record and tell security to start it by hand in a fire."},wait:{vi:"Giữ nguyên hiện trạng, không ký biên bản và chờ ban quản lý tự quyết định.",en:"Leave things as they are, do not sign and wait for building management to decide."}},questions:{vi:["Giải thích chuỗi điểm đặt áp lực bạn đã tính và vì sao bơm chính không được khởi động cùng mức với bơm bù.","Để hệ thống chữa cháy ở chế độ tay gây rủi ro gì, và quy trình tạm ngừng hệ thống hợp lệ gồm những bước nào?"],en:["Explain the pressure setpoint sequence you calculated and why the main pump must not start at the jockey level.","What risks arise from leaving fire pumps in manual, and what steps make a valid system impairment procedure?"]},hints:{vi:["Chạy lệnh xem trạng thái và nhật ký sự kiện, đối chiếu với quy trình bàn giao trước khi sửa.","Theo SOP mục 3.2, tính mức dừng bơm bù trước, rồi lần lượt trừ các khoảng chênh để ra mức khởi động bơm chính.","SOP mục 4.2: biên bản PCCC phải phản ánh đúng trạng thái thực; đề nghị ghi sai phải báo cấp có thẩm quyền."],en:["Run the status and event log commands and compare them with the handover procedure before editing.","Under SOP 3.2, compute the jockey stop first, then subtract each differential to reach the main pump start.","SOP 4.2: fire records must show the real status; escalate any request to falsify them to the competent authority."]}},learning:{summary:{vi:"Kỹ sư cơ điện công trình (MEP) thiết kế, giám sát lắp đặt, chạy thử và vận hành các hệ thống điều hòa thông gió, cấp thoát nước và phòng cháy chữa cháy. Họ bảo đảm công trình tiện nghi, tiết kiệm năng lượng và an toàn cháy, phối hợp chặt với kiến trúc, kết cấu và nhà thầu. Nghề đòi hỏi kiến thức nhiệt lạnh, thủy lực, điều khiển, hiểu quy chuẩn an toàn cháy và kỷ luật trong thử nghiệm, nghiệm thu.",en:"An MEP engineer designs, supervises installation, commissions and operates HVAC, plumbing and fire fighting systems. They make buildings comfortable, energy efficient and fire safe, working closely with architecture, structure and contractors. The role requires knowledge of refrigeration, hydraulics and controls, command of fire safety codes and discipline in testing and acceptance."},responsibilities:{vi:["Tính toán tải lạnh, lưu lượng gió, nước cấp, nước thoát và lưu lượng chữa cháy cho công trình.","Thiết kế, chọn thiết bị: chiller, AHU, bơm, đường ống, đầu phun sprinkler, tủ điều khiển.","Phối hợp không gian kỹ thuật, cao độ đường ống với kiến trúc, kết cấu trên mô hình BIM.","Giám sát lắp đặt, thử áp, chạy thử, cân chỉnh (T&C) và lập hồ sơ nghiệm thu.","Hướng dẫn vận hành, bảo trì và xử lý sự cố hệ thống cơ điện, PCCC."],en:["Calculate cooling loads, airflow, water supply, drainage and fire water demand.","Design and select equipment: chillers, AHUs, pumps, piping, sprinkler heads and controllers.","Coordinate plant space and pipe levels with architecture and structure in the BIM model.","Supervise installation, pressure tests and testing and commissioning (T&C) and compile acceptance records.","Train operators, plan maintenance and troubleshoot MEP and fire systems."]},competencies:[{name:{vi:"Nhiệt lạnh & thông gió",en:"HVAC design"},desc:{vi:"Tính tải lạnh, cân bằng gió, lựa chọn hệ thống điều hòa hiệu quả năng lượng.",en:"Calculate cooling loads, balance air and select energy-efficient air conditioning systems."}},{name:{vi:"Thủy lực & bơm",en:"Hydraulics & pumps"},desc:{vi:"Tính tổn thất áp, chọn bơm theo đường đặc tính và thiết lập điểm đặt điều khiển.",en:"Compute pressure losses, select pumps from their curves and set control setpoints."}},{name:{vi:"Phòng cháy chữa cháy",en:"Fire protection"},desc:{vi:"Thiết kế sprinkler, họng nước, bơm chữa cháy theo quy chuẩn và hồ sơ thẩm duyệt.",en:"Design sprinklers, hose reels and fire pumps to code and the approved fire design."}},{name:{vi:"Chạy thử & cân chỉnh",en:"Testing & commissioning"},desc:{vi:"Lập quy trình T&C, đo kiểm, so sánh với thiết kế và xử lý sai lệch.",en:"Write T&C procedures, measure, compare with design and resolve deviations."}},{name:{vi:"An toàn & trung thực",en:"Safety & integrity"},desc:{vi:"Không vô hiệu hóa hệ thống an toàn, ghi biên bản đúng thực tế.",en:"Never disable life safety systems and record test results truthfully."}}],knowledge:{vi:["QCVN 06:2022/BXD - Quy chuẩn kỹ thuật quốc gia về an toàn cháy cho nhà và công trình, kèm sửa đổi 1:2023.","TCVN 7336:2021 - Phòng cháy chữa cháy: hệ thống sprinkler tự động, yêu cầu thiết kế và lắp đặt.","TCVN 5687 (phiên bản hiện hành) - Thông gió, điều hòa không khí: tiêu chuẩn thiết kế.","NFPA 20 - Tiêu chuẩn lắp đặt bơm cố định cho phòng cháy (tham khảo quốc tế).","Nguyên lý thủy lực: đường đặc tính bơm, tổn thất áp, áp lực churn và điểm làm việc."],en:["QCVN 06:2022/BXD - National technical regulation on fire safety of buildings, with Amendment 1:2023.","TCVN 7336:2021 - Fire protection: automatic sprinkler systems, design and installation requirements.","TCVN 5687 (current edition) - Ventilation and air conditioning: design standard.","NFPA 20 - Standard for the installation of stationary pumps for fire protection (international reference).","Hydraulic principles: pump curves, pressure losses, churn pressure and duty point."]},tools:["Phần mềm tính tải lạnh","Phần mềm tính thủy lực sprinkler","Phần mềm mô hình BIM cơ điện","Đồng hồ áp lực và lưu lượng kế","Hệ thống quản lý tòa nhà (BMS)","Máy đo gió và nhiệt ẩm"],kpis:{vi:["Tỷ lệ hệ thống đạt chạy thử nghiệm thu ngay lần đầu.","Số lần hệ thống PCCC mất sẵn sàng (mục tiêu bằng 0).","Chỉ số tiêu thụ năng lượng điều hòa (kWh/m2.năm) so với mục tiêu.","Thời gian xử lý yêu cầu sự cố cơ điện."],en:["Share of systems passing commissioning first time.","Fire system out-of-service events (target zero).","HVAC energy use intensity (kWh/m2.year) against target.","Response time to MEP fault requests."]},day:[{time:"08:00",vi:"Kiểm tra cảnh báo BMS, trạng thái bơm chữa cháy, chiller và bể nước.",en:"Review BMS alarms and the status of fire pumps, chillers and water tanks."},{time:"09:30",vi:"Giám sát thử áp đường ống sprinkler tầng 8, ghi áp lực đầu và cuối thời gian thử.",en:"Witness the level 8 sprinkler pressure test and log start and end pressures."},{time:"13:30",vi:"Phối hợp cao độ ống gió, ống nước với kết cấu và trần trên mô hình liên kết.",en:"Coordinate duct and pipe levels with structure and ceilings in the federated model."},{time:"15:30",vi:"Chạy thử bơm chữa cháy: khởi động tự động, đo lưu lượng, áp lực theo đường đặc tính.",en:"Test fire pumps: automatic start, flow and pressure against the pump curve."},{time:"17:00",vi:"Lập biên bản, cập nhật danh sách tồn tại và kế hoạch khắc phục.",en:"Write the test record and update the defects list and corrective plan."}],mistakes:{vi:["Để tủ bơm chữa cháy ở chế độ tay sau bảo trì, làm hệ thống không tự khởi động.","Đặt áp lực khởi động bơm chính trùng hoặc cao hơn bơm bù, gây chạy sai và hao mòn.","Bỏ qua việc bơm bù chạy liên tục, không tìm rò rỉ trên mạng đường ống."],en:["Leaving fire pump controllers in manual after maintenance so the system cannot start itself.","Setting the main pump start equal to or above the jockey start, causing false starts and wear.","Ignoring a constantly cycling jockey pump instead of finding the leak in the network."]},career:[{vi:"Kỹ thuật viên cơ điện",en:"MEP technician"},{vi:"Kỹ sư thiết kế cơ điện",en:"MEP design engineer"},{vi:"Chủ trì cơ điện dự án",en:"Lead MEP engineer"},{vi:"Giám đốc kỹ thuật cơ điện",en:"MEP technical director"}],glossary:[{term:"Churn pressure",vi:"Áp lực bơm tạo ra khi chạy ở lưu lượng bằng 0, tức khi van xả đóng hoàn toàn.",en:"Pressure a pump develops when running at zero flow with the discharge closed."},{term:"Jockey pump",vi:"Bơm bù áp nhỏ giữ áp lực mạng, tránh bơm chính khởi động do rò rỉ nhỏ.",en:"Small pressure-maintenance pump that prevents the main pump starting on minor leaks."},{term:"Sprinkler",vi:"Đầu phun tự động mở khi nhiệt độ đạt ngưỡng, phun nước dập đám cháy ở giai đoạn đầu.",en:"Automatic head that opens at a set temperature and sprays water on an incipient fire."},{term:"T&C",vi:"Chạy thử và cân chỉnh hệ thống để xác nhận vận hành đúng thiết kế trước khi bàn giao.",en:"Testing and commissioning to confirm systems perform as designed before handover."},{term:"Impairment",vi:"Tình trạng hệ thống PCCC tạm ngừng hoặc suy giảm, phải có phiếu phép và biện pháp bù.",en:"Fire protection system out of service or degraded, requiring a permit and compensating measures."}],quiz:[{q:{vi:"Churn bơm chính 8,0 bar, áp tĩnh hút 1,0 bar. Bơm bù dừng = churn + tĩnh, khởi động thấp hơn 0,7 bar; bơm chính thấp hơn bơm bù 0,35 bar. Áp lực khởi động bơm chính?",en:"Main pump churn 8.0 bar, static suction 1.0 bar. Jockey stop = churn + static, start 0.7 bar lower; main pump 0.35 bar below jockey start. Main pump start?"},options:{vi:["9,00 bar","8,30 bar","7,60 bar","7,95 bar"],en:["9.00 bar","8.30 bar","7.60 bar","7.95 bar"]},answer:3,explain:{vi:"Bơm bù dừng 9,0 bar, khởi động 8,3 bar; bơm chính khởi động 8,3 - 0,35 = 7,95 bar.",en:"Jockey stops at 9.0 bar and starts at 8.3 bar; the main pump starts at 8.3 - 0.35 = 7.95 bar."}},{q:{vi:"Quy chuẩn quốc gia nào quy định an toàn cháy cho nhà và công trình tại Việt Nam?",en:"Which national regulation sets fire safety requirements for buildings in Vietnam?"},options:{vi:["QCVN 06:2022/BXD","QCVN 01:2021/BXD","TCVN 4453:1995","TCVN 9386:2012"],en:["QCVN 06:2022/BXD","QCVN 01:2021/BXD","TCVN 4453:1995","TCVN 9386:2012"]},answer:0,explain:{vi:"QCVN 06:2022/BXD là quy chuẩn an toàn cháy cho nhà và công trình; các văn bản còn lại thuộc quy hoạch, thi công bê tông, động đất.",en:"QCVN 06:2022/BXD is the building fire safety regulation; the others cover planning, concrete works and seismic design."}},{q:{vi:"Ban quản lý đề nghị để bơm chữa cháy ở chế độ tay cho đỡ ồn và ghi AUTO trong biên bản. Bạn làm gì?",en:"Management asks you to keep the fire pump in manual to reduce noise and write AUTO in the record. What do you do?"},options:{vi:["Đồng ý vì đã có bảo vệ trực","Không ghi sai, xử lý nguyên nhân, chuyển AUTO và báo cấp có thẩm quyền","Để AUTO ban đêm, MANUAL ban ngày","Tắt bơm bù cho hết ồn"],en:["Agree because security is on duty","Refuse to falsify, fix the cause, switch to AUTO and inform the authority","AUTO at night, MANUAL by day","Switch off the jockey pump to stop the noise"]},answer:1,explain:{vi:"Hệ thống chữa cháy phải luôn tự động; ghi sai biên bản là vi phạm nghiêm trọng và có thể gây thiệt hại về người.",en:"Fire systems must stay automatic; falsifying records is a serious violation that can cost lives."}},{q:{vi:"Bơm bù khởi động hơn 40 lần mỗi giờ thường là dấu hiệu của vấn đề gì?",en:"A jockey pump starting more than 40 times per hour usually signals what?"},options:{vi:["Bơm chính quá lớn","Áp lực churn quá thấp","Rò rỉ trên mạng đường ống hoặc van","Bể nước quá đầy"],en:["Main pump oversized","Churn pressure too low","A leak in the piping network or valves","Water tank too full"]},answer:2,explain:{vi:"Bơm bù chạy dày cho thấy áp lực mạng sụt liên tục, thường do rò rỉ cần được tìm và xử lý.",en:"Frequent jockey cycling shows the network keeps losing pressure, usually from a leak that must be found and fixed."}}],tools_en:["Cooling load calculation software","Sprinkler hydraulic calculation software","MEP BIM modeling software","Pressure gauges and flow meters","Building management system (BMS)","Anemometer and thermo-hygrometer"]}},"KK-636":{scenario:{company:"Mộc Lan Architects & Interiors",supervisor:{name:"Quách Thùy Trang",role:{vi:"Giám đốc thiết kế",en:"Design Director"}},ref_code:"ARC-4410",title:{vi:"Ý tưởng đẹp phải đúng quy chuẩn.",en:"Great concepts must meet the codes."},brief:{vi:"Bạn hoàn thiện bảng chỉ tiêu phương án ARC-4410 cho tòa hỗn hợp trên lô đất 4 000 m2, quy hoạch cho phép hệ số sử dụng đất tối đa 5,50 (mô phỏng). Sàn trên mặt đất 22 400 m2, trong đó tầng kỹ thuật và gian lánh nạn 800 m2. Hai tầng hầm 7 200 m2 gồm 6 400 m2 đỗ xe, kỹ thuật và 800 m2 siêu thị. Nhiệm vụ thiết kế vừa điều chỉnh khối tháp thành căn hộ chung cư để bán. Hãy sửa nhóm nguy hiểm cháy theo công năng và hệ số sử dụng đất, rồi lập báo cáo có căn cứ.",en:"You are finalizing scheme indicator sheet ARC-4410 for a mixed-use tower on a 4,000 m2 lot; planning allows a maximum floor area ratio of 5.50 (simulated). Above-ground floor area is 22,400 m2, including 800 m2 of plant and refuge floors. Two basements total 7,200 m2: 6,400 m2 of parking and plant and 800 m2 of supermarket. The brief now makes the tower apartments for sale. Correct the fire hazard class by use and the floor area ratio, then write an evidence-based report."},reference_title:{vi:"Nhiệm vụ thiết kế điều chỉnh & bảng diện tích đã duyệt",en:"Revised design brief & approved area schedule"},fields:[{id:"FIRE_CLASS",label:{vi:"Nhóm nguy hiểm cháy theo công năng khối tháp",en:"Functional fire hazard class of the tower"},initial:"F1.2",expected:"F1.3",choices:["F1.2","F1.3","F4.3"],reference:"Nhiệm vụ thiết kế điều chỉnh",ref_value:{vi:"Khối tháp chuyển từ căn hộ dịch vụ lưu trú ngắn ngày sang căn hộ chung cư để bán",en:"Tower changed from short-stay serviced apartments to apartments for sale"},hint:{vi:"F1.2 dành cho khách sạn, ký túc xá, nơi lưu trú; nhà chung cư thuộc một nhóm khác trong hạng F1.",en:"F1.2 covers hotels, dormitories and short stays; apartment buildings are another subclass of F1."}},{id:"FAR",label:{vi:"Hệ số sử dụng đất",en:"Floor area ratio (FAR)"},initial:"5.40",expected:"5.60",reference:"Bảng tổng hợp diện tích sàn",ref_value:{vi:"Lô 4 000 m2; sàn nổi 22 400 (kỹ thuật, lánh nạn 800); hầm 7 200 (đỗ xe, kỹ thuật 6 400; siêu thị 800)",en:"Lot 4,000 m2; above ground 22,400 (plant, refuge 800); basements 7,200 (parking, plant 6,400; supermarket 800)"},hint:{vi:"Bản nháp loại toàn bộ tầng hầm; phần hầm kinh doanh vẫn phải tính vào tổng diện tích sàn.",en:"The draft excluded the whole basement; commercial basement space still counts toward floor area."}}],sop32:{vi:"Hệ số sử dụng đất = tổng diện tích sàn / diện tích lô đất. Tổng diện tích sàn tính cả tầng hầm, trừ diện tích đỗ xe, kỹ thuật, PCCC và gian lánh nạn; làm tròn 2 chữ số thập phân.",en:"FAR = gross floor area / lot area. Gross floor area includes basements but excludes parking, plant, fire safety and refuge areas; round to 2 decimals."},context:{label:"CHỈ TIÊU / ARC-4410",metrics:[{label:{vi:"Diện tích lô đất",en:"Lot area"},value:"4,000 m2"},{label:{vi:"Hệ số tối đa (mô phỏng)",en:"Max FAR (simulated)"},value:"5.50"},{label:{vi:"Sàn hầm kinh doanh",en:"Commercial basement"},value:"800 m2"}]},crisis:{vi:"Chủ đầu tư gọi: “Ghi siêu thị tầng hầm là kho kỹ thuật trên bản vẽ để hệ số dưới 5,5 cho qua thẩm định, sau này đổi công năng. Đừng cắt căn hộ nào.”",en:"The developer calls: “Label the basement supermarket as plant storage on the drawings so the FAR stays under 5.5 for approval; we change the use later. Do not cut any apartments.”"},options:{safe:{vi:"Không ghi sai công năng; báo giám đốc thiết kế và chủ đầu tư rằng phương án vượt chỉ tiêu, đề xuất giảm diện tích sàn, chuyển phần hầm sang công năng được loại trừ hoặc xin điều chỉnh quy hoạch đúng thủ tục.",en:"Do not mislabel uses; tell the design director and developer the scheme exceeds the limit and propose cutting floor area, converting the basement to an excluded use or a lawful planning amendment."},shortcut:{vi:"Đổi tên siêu thị thành kho kỹ thuật trên bản vẽ cho qua thẩm định như chủ đầu tư muốn.",en:"Rename the supermarket as plant storage on the drawings to pass approval as the developer wants."},wait:{vi:"Gửi bảng chỉ tiêu nháp như cũ và chờ cơ quan thẩm định tự phát hiện.",en:"Submit the old draft sheet and wait for the authority to spot the issue."}},questions:{vi:["Giải thích cách bạn tính lại hệ số sử dụng đất, phần diện tích nào được trừ và vì sao khối tháp thuộc nhóm F1.3.","Đề nghị ghi sai công năng tầng hầm gây hậu quả pháp lý và an toàn cháy nào? Bạn đề xuất phương án thiết kế hợp lệ ra sao?"],en:["Explain how you recalculated the FAR, which areas are excluded and why the tower falls in class F1.3.","What legal and fire safety consequences follow from mislabelling the basement use? Which lawful design options do you propose?"]},hints:{vi:["Đặt bảng chỉ tiêu nháp cạnh nhiệm vụ thiết kế điều chỉnh và kiểm tra công năng mới của khối tháp.","Theo SOP mục 3.2, liệt kê từng loại diện tích, đánh dấu phần được trừ rồi mới chia cho diện tích lô đất.","SOP mục 4.2: hồ sơ phải thể hiện đúng công năng thật; áp lực lách quy hoạch phải báo giám đốc thiết kế."],en:["Place the draft sheet next to the revised brief and check the tower's new use.","Under SOP 3.2, list each area type, mark the excluded ones and only then divide by the lot area.","SOP 4.2: drawings must show the real use; escalate any pressure to circumvent planning to the design director."]}},learning:{summary:{vi:"Kiến trúc sư thiết kế công trình và nội thất chuyển nhu cầu của chủ đầu tư thành giải pháp không gian, hình khối, vật liệu và chi tiết, cân bằng giữa thẩm mỹ, công năng, chi phí, quy hoạch và an toàn. Họ dẫn dắt phương án từ ý tưởng đến hồ sơ kỹ thuật, phối hợp kết cấu, cơ điện và giám sát tác giả. Nghề cần tư duy sáng tạo, kỹ năng trình bày, hiểu quy chuẩn xây dựng và giữ đạo đức nghề nghiệp trước áp lực thương mại.",en:"An architectural and interior designer turns a client's needs into spatial, massing, material and detail solutions, balancing aesthetics, function, cost, planning and safety. They lead a scheme from concept to technical documents, coordinate structure and MEP and provide designer supervision. The role needs creative thinking, presentation skills, command of building codes and professional ethics under commercial pressure."},responsibilities:{vi:["Phân tích nhiệm vụ thiết kế, khu đất, quy hoạch và lập ý tưởng kiến trúc, nội thất.","Phát triển mặt bằng, mặt đứng, phối cảnh và bảng chỉ tiêu kinh tế kỹ thuật.","Kiểm tra tuân thủ quy hoạch, an toàn cháy, tiếp cận người khuyết tật và tiết kiệm năng lượng.","Lựa chọn vật liệu hoàn thiện, đồ nội thất, ánh sáng và lập chỉ dẫn kỹ thuật.","Phối hợp các bộ môn, trình duyệt hồ sơ và giám sát tác giả trong thi công."],en:["Analyse the brief, site and planning rules and develop architectural and interior concepts.","Develop plans, elevations, visualizations and the techno-economic indicator sheet.","Check compliance with planning, fire safety, accessibility and energy efficiency rules.","Select finishes, furniture and lighting and write the specifications.","Coordinate disciplines, submit for approval and provide designer supervision during construction."]},competencies:[{name:{vi:"Tư duy thiết kế & sáng tạo",en:"Design thinking & creativity"},desc:{vi:"Biến nhu cầu người dùng thành ý tưởng không gian rõ ràng, có bản sắc.",en:"Turn user needs into clear spatial ideas with a distinct identity."}},{name:{vi:"Hiểu quy chuẩn",en:"Code literacy"},desc:{vi:"Vận dụng quy chuẩn quy hoạch, an toàn cháy, tiếp cận sử dụng ngay từ giai đoạn ý tưởng.",en:"Apply planning, fire safety and accessibility codes from the concept stage."}},{name:{vi:"Kỹ năng thể hiện",en:"Visual communication"},desc:{vi:"Dựng hình, diễn họa, trình bày phương án thuyết phục bằng hình ảnh và số liệu.",en:"Model, render and present schemes persuasively with images and data."}},{name:{vi:"Vật liệu & chi tiết",en:"Materials & detailing"},desc:{vi:"Hiểu đặc tính vật liệu, cấu tạo, chi phí và khả năng thi công.",en:"Understand material properties, build-ups, cost and buildability."}},{name:{vi:"Đạo đức nghề nghiệp",en:"Professional ethics"},desc:{vi:"Bảo vệ lợi ích cộng đồng, không lách quy hoạch hay khai sai công năng.",en:"Protect the public interest and never circumvent planning or misstate uses."}}],knowledge:{vi:["QCVN 01:2021/BXD - Quy chuẩn kỹ thuật quốc gia về quy hoạch xây dựng (mật độ, hệ số sử dụng đất).","QCVN 06:2022/BXD - An toàn cháy cho nhà và công trình, phân nhóm nguy hiểm cháy theo công năng F1 đến F5.","Luật Kiến trúc số 40/2019/QH14 và quy định về chứng chỉ hành nghề kiến trúc.","Quy chuẩn hiện hành về nhà và công trình bảo đảm người khuyết tật tiếp cận sử dụng.","Nguyên lý công thái học, ánh sáng, âm học và vật liệu trong thiết kế nội thất."],en:["QCVN 01:2021/BXD - National technical regulation on construction planning (site coverage, floor area ratio).","QCVN 06:2022/BXD - Fire safety of buildings, functional fire hazard classes F1 to F5.","Architecture Law No. 40/2019/QH14 and rules on architectural practice certificates.","Current regulation on building accessibility for people with disabilities.","Principles of ergonomics, lighting, acoustics and materials in interior design."]},tools:["Phần mềm dựng hình 3D và BIM kiến trúc","Phần mềm diễn họa thời gian thực","Phần mềm CAD 2D","Bộ mẫu vật liệu hoàn thiện","Phần mềm dàn trang trình bày"],kpis:{vi:["Tỷ lệ phương án được chủ đầu tư chấp thuận sau tối đa 2 vòng chỉnh sửa.","Số ý kiến không tuân thủ quy chuẩn từ cơ quan thẩm định (mục tiêu bằng 0).","Chênh lệch chi phí hoàn thiện thực tế so với ngân sách thiết kế.","Mức độ hài lòng của người sử dụng sau khi đưa vào khai thác."],en:["Share of schemes approved by the client within 2 revision rounds.","Code non-compliance comments from the authority (target zero).","Variance of actual fit-out cost against the design budget.","User satisfaction after occupancy."]},day:[{time:"08:30",vi:"Rà soát phản hồi của chủ đầu tư về phương án sảnh và căn hộ mẫu.",en:"Review client feedback on the lobby scheme and show apartment."},{time:"10:00",vi:"Phát triển mặt bằng tầng điển hình, kiểm tra lối thoát nạn và bảng diện tích.",en:"Develop the typical floor plan and check escape routes and the area schedule."},{time:"13:30",vi:"Làm việc với nhà cung cấp về mẫu vật liệu, ánh sáng và đồ nội thất.",en:"Meet suppliers on material samples, lighting and furniture."},{time:"15:30",vi:"Họp phối hợp kết cấu, cơ điện về cao độ trần và trục kỹ thuật.",en:"Coordinate ceiling heights and service shafts with structure and MEP."},{time:"17:00",vi:"Cập nhật bảng chỉ tiêu, phối cảnh và chuẩn bị bài trình bày.",en:"Update the indicator sheet and renders and prepare the presentation."}],mistakes:{vi:["Loại toàn bộ tầng hầm khỏi tổng diện tích sàn, kể cả phần kinh doanh.","Không cập nhật nhóm nguy hiểm cháy khi công năng công trình thay đổi.","Chọn vật liệu theo thẩm mỹ mà bỏ qua yêu cầu an toàn cháy, độ bền và bảo trì."],en:["Excluding every basement from gross floor area, including commercial space.","Not updating the fire hazard class when the building use changes.","Choosing materials for looks while ignoring fire safety, durability and maintenance."]},career:[{vi:"Họa viên, kiến trúc sư tập sự",en:"Draftsperson, graduate architect"},{vi:"Kiến trúc sư thiết kế",en:"Project architect"},{vi:"Kiến trúc sư chủ trì",en:"Lead architect"},{vi:"Giám đốc thiết kế, kiến trúc sư trưởng",en:"Design director, principal architect"}],glossary:[{term:"FAR",vi:"Hệ số sử dụng đất: tỷ lệ giữa tổng diện tích sàn tính theo quy chuẩn và diện tích lô đất.",en:"Floor area ratio: gross floor area as defined by the code divided by lot area."},{term:"Mật độ xây dựng",vi:"Tỷ lệ diện tích chiếm đất của công trình trên diện tích lô đất.",en:"Ratio of building footprint to lot area."},{term:"F1.3",vi:"Nhóm nguy hiểm cháy theo công năng dành cho nhà chung cư trong QCVN 06:2022/BXD.",en:"Functional fire hazard subclass for apartment buildings in QCVN 06:2022/BXD."},{term:"Concept design",vi:"Thiết kế ý tưởng thể hiện định hướng không gian, hình khối và các giải pháp chính.",en:"Early design stage expressing spatial direction, massing and key solutions."},{term:"Moodboard",vi:"Bảng tập hợp hình ảnh, vật liệu, màu sắc định hướng ngôn ngữ thiết kế nội thất.",en:"Board of images, materials and colours that sets the interior design language."}],quiz:[{q:{vi:"Lô đất 2 000 m2, tổng diện tích sàn tính hệ số là 9 000 m2. Hệ số sử dụng đất là bao nhiêu?",en:"A 2,000 m2 lot has 9,000 m2 of countable gross floor area. What is the FAR?"},options:{vi:["4,5","2,2","9,0","0,22"],en:["4.5","2.2","9.0","0.22"]},answer:0,explain:{vi:"Hệ số sử dụng đất = 9 000 / 2 000 = 4,5.",en:"FAR = 9,000 / 2,000 = 4.5."}},{q:{vi:"Theo QCVN 06:2022/BXD, khách sạn và ký túc xá thuộc nhóm nguy hiểm cháy theo công năng nào?",en:"Under QCVN 06:2022/BXD, which functional fire hazard class covers hotels and dormitories?"},options:{vi:["F1.3","F1.2","F3.1","F4.3"],en:["F1.3","F1.2","F3.1","F4.3"]},answer:1,explain:{vi:"F1.2 gồm khách sạn, ký túc xá, nhà nghỉ; nhà chung cư thuộc F1.3.",en:"F1.2 covers hotels, dormitories and guesthouses; apartment buildings are F1.3."}},{q:{vi:"Chủ đầu tư đề nghị ghi siêu thị tầng hầm là kho kỹ thuật để qua thẩm định. Bạn làm gì?",en:"The developer asks you to label the basement supermarket as plant storage to pass approval. What do you do?"},options:{vi:["Làm theo vì chủ đầu tư chịu trách nhiệm","Ghi mơ hồ là không gian đa năng","Từ chối, báo giám đốc thiết kế và đề xuất phương án điều chỉnh hợp lệ","Bỏ tầng hầm khỏi hồ sơ trình duyệt"],en:["Comply because the developer is responsible","Label it vaguely as flexible space","Refuse, inform the design director and propose lawful revisions","Leave the basement out of the submission"]},answer:2,explain:{vi:"Khai sai công năng là vi phạm pháp luật và làm sai lệch giải pháp an toàn cháy; kiến trúc sư phải từ chối và đề xuất phương án hợp lệ.",en:"Misstating use breaks the law and distorts fire safety design; the architect must refuse and propose lawful options."}},{q:{vi:"Thành phần nào được trừ khi tính tổng diện tích sàn cho hệ số sử dụng đất?",en:"Which area is excluded from gross floor area when computing FAR?"},options:{vi:["Sàn siêu thị tầng hầm","Sàn căn hộ","Sàn văn phòng","Sàn đỗ xe của công trình"],en:["Basement supermarket floor","Apartment floors","Office floors","The building's parking floors"]},answer:3,explain:{vi:"Diện tích đỗ xe, kỹ thuật, PCCC và gian lánh nạn được trừ; diện tích kinh doanh dưới hầm vẫn được tính.",en:"Parking, plant, fire safety and refuge areas are excluded; commercial basement space still counts."}}],tools_en:["3D modeling and architectural BIM software","Real-time rendering software","2D CAD software","Finish material sample kit","Presentation layout software"]}},"KK-637":{scenario:{company:"Hồng Lĩnh Project Management",supervisor:{name:"Doãn Quốc Hiếu",role:{vi:"Giám đốc quản lý dự án",en:"Project Management Director"}},ref_code:"PMR-0825",title:{vi:"Báo cáo thật. Đường găng rõ. Phục hồi có kế hoạch.",en:"True reporting. Clear critical path. Planned recovery."},brief:{vi:"Bạn lập báo cáo tháng PMR-0825 của dự án trường học có ngân sách hoàn thành BAC = 48 000 triệu đồng. Đến cuối kỳ: giá trị kế hoạch PV = 22 500, giá trị thu được EV = 18 000, chi phí thực tế AC = 19 200 (triệu đồng). Phần tiến độ còn lại có ba chuỗi công việc song song. Bản nháp chọn sai đường găng và dự báo chi phí hoàn thành như thể phần còn lại đúng ngân sách. Hãy sửa đường găng và EAC (triệu đồng), rồi lập báo cáo có căn cứ.",en:"You are preparing monthly report PMR-0825 for a school project with a budget at completion BAC = 48,000 million VND. At period end: planned value PV = 22,500, earned value EV = 18,000, actual cost AC = 19,200 (million VND). The remaining schedule has three parallel chains. The draft picks the wrong critical path and forecasts cost at completion as if the rest ran on budget. Correct the critical path and the EAC (million VND), then write an evidence-based report."},reference_title:{vi:"Mạng tiến độ cập nhật & bảng giá trị thu được đã duyệt",en:"Updated schedule network & approved earned value sheet"},fields:[{id:"CRIT_PATH",label:{vi:"Đường găng của tiến độ còn lại",en:"Critical path of the remaining schedule"},initial:"A-B-E-H",expected:"A-C-F-H",choices:["A-B-E-H","A-C-F-H","A-D-G-H"],reference:"Mạng tiến độ cập nhật",ref_value:{vi:"Thời gian (tuần): A 3; B 5, E 4; C 6, F 5; D 4, G 4; H 2; mỗi chuỗi đi từ A đến H",en:"Durations (weeks): A 3; B 5, E 4; C 6, F 5; D 4, G 4; H 2; every chain runs from A to H"},hint:{vi:"Đường găng là chuỗi có tổng thời gian dài nhất, không phải chuỗi chứa hạng mục lớn nhất.",en:"The critical path is the chain with the longest total duration, not the one with the biggest work item."}},{id:"EAC_M",label:{vi:"Dự báo chi phí hoàn thành EAC (triệu đồng)",en:"Estimate at completion EAC (million VND)"},initial:"49200",expected:"51200",reference:"Bảng giá trị thu được tháng 8",ref_value:{vi:"BAC 48 000; PV 22 500; EV 18 000; AC 19 200 (triệu đồng)",en:"BAC 48,000; PV 22,500; EV 18,000; AC 19,200 (million VND)"},hint:{vi:"Bản nháp dùng EAC = AC + (BAC - EV), chỉ đúng khi sai lệch chi phí là ngẫu nhiên và không lặp lại.",en:"The draft used EAC = AC + (BAC - EV), valid only when the cost variance is a one-off."}}],sop32:{vi:"CPI = EV / AC; SPI = EV / PV. Khi hiệu suất chi phí hiện tại được dự báo tiếp diễn: EAC = BAC / CPI; VAC = BAC - EAC. Ghi EAC đến triệu đồng.",en:"CPI = EV / AC; SPI = EV / PV. When current cost performance is expected to continue: EAC = BAC / CPI; VAC = BAC - EAC. State EAC to the nearest million VND."},context:{label:"PMIS / PMR-0825",metrics:[{label:{vi:"Ngân sách BAC (triệu đồng)",en:"Budget BAC (million VND)"},value:"48,000"},{label:{vi:"Giá trị thu được EV",en:"Earned value EV"},value:"18,000"},{label:{vi:"Chi phí thực tế AC",en:"Actual cost AC"},value:"19,200"}]},crisis:{vi:"Chủ đầu tư nhắn: “Báo cáo gửi ngân hàng tuần này phải ghi SPI = 1,0 và chi phí trong ngân sách, không thì đợt giải ngân bị treo. Số liệu thật để nội bộ biết thôi.”",en:"The owner texts: “The report to the bank this week must show SPI = 1.0 and cost on budget, or the next drawdown is frozen. Keep the real numbers internal.”"},options:{safe:{vi:"Báo cáo đúng SPI, CPI và EAC; báo giám đốc quản lý dự án, kèm kế hoạch phục hồi tiến độ (tăng ca, thi công song song có kiểm soát) và chi phí dự kiến để chủ đầu tư làm việc minh bạch với ngân hàng.",en:"Report the true SPI, CPI and EAC; inform the PM director and attach a recovery plan (overtime, controlled fast-tracking) with its cost so the owner can deal transparently with the bank."},shortcut:{vi:"Gửi ngân hàng bản báo cáo ghi SPI = 1,0 như yêu cầu, giữ số liệu thật trong nội bộ.",en:"Send the bank a report showing SPI = 1.0 as asked and keep the real figures internal."},wait:{vi:"Không gửi báo cáo nào và chờ chủ đầu tư tự làm việc với ngân hàng.",en:"Send no report and wait for the owner to handle the bank alone."}},questions:{vi:["Trình bày cách bạn xác định đường găng và tính CPI, SPI, EAC; các chỉ số này nói gì về sức khỏe dự án?","Báo cáo sai số liệu cho bên cho vay gây rủi ro pháp lý gì? Bạn đề xuất kế hoạch phục hồi tiến độ và chi phí như thế nào?"],en:["Explain how you identified the critical path and computed CPI, SPI and EAC; what do they say about project health?","What legal risks arise from misreporting to a lender? Which schedule and cost recovery plan would you propose?"]},hints:{vi:["Cộng tổng thời gian của từng chuỗi công việc trong mạng tiến độ trước khi chọn đường găng.","Theo SOP mục 3.2, tính CPI từ EV và AC rồi mới dự báo EAC từ ngân sách hoàn thành.","SOP mục 4.2: báo cáo cho bên ngoài phải trung thực; áp lực sửa số liệu phải báo giám đốc quản lý dự án."],en:["Add up the total duration of each chain in the network before choosing the critical path.","Under SOP 3.2, compute CPI from EV and AC before forecasting EAC from the budget at completion.","SOP 4.2: external reports must be truthful; escalate any pressure to alter figures to the PM director."]}},learning:{summary:{vi:"Quản lý dự án xây dựng lập kế hoạch, tổ chức và kiểm soát phạm vi, tiến độ, chi phí, chất lượng, an toàn và rủi ro của dự án từ chuẩn bị đầu tư đến bàn giao. Họ điều phối chủ đầu tư, tư vấn, nhà thầu và cơ quan quản lý, ra quyết định dựa trên số liệu và bảo đảm tuân thủ pháp luật. Nghề đòi hỏi kỹ năng lãnh đạo, giao tiếp, phân tích tiến độ, chi phí và sự chính trực trong báo cáo.",en:"A construction project manager plans, organizes and controls scope, schedule, cost, quality, safety and risk from project preparation to handover. They coordinate the owner, consultants, contractors and authorities, decide on evidence and ensure legal compliance. The role demands leadership, communication, schedule and cost analysis and integrity in reporting."},responsibilities:{vi:["Lập kế hoạch tổng thể, cấu trúc phân chia công việc (WBS) và tiến độ cơ sở của dự án.","Kiểm soát tiến độ, chi phí bằng phương pháp đường găng và giá trị thu được.","Quản lý hợp đồng, phối hợp các bên và giải quyết vướng mắc tại công trường.","Quản lý rủi ro, an toàn, chất lượng và yêu cầu thay đổi theo quy trình phê duyệt.","Báo cáo định kỳ cho chủ đầu tư, bên cho vay và tổ chức bàn giao, quyết toán."],en:["Build the master plan, work breakdown structure (WBS) and baseline schedule.","Control schedule and cost with critical path and earned value methods.","Manage contracts, coordinate parties and resolve site issues.","Manage risk, safety, quality and change requests through approval workflows.","Report regularly to the owner and lenders and organize handover and final accounts."]},competencies:[{name:{vi:"Lập & kiểm soát tiến độ",en:"Scheduling & control"},desc:{vi:"Xây dựng mạng CPM, xác định đường găng, thời gian dự trữ và kế hoạch phục hồi.",en:"Build CPM networks, identify the critical path and float and plan recovery."}},{name:{vi:"Quản lý chi phí",en:"Cost management"},desc:{vi:"Áp dụng EVM, dự báo EAC và kiểm soát dòng tiền dự án.",en:"Apply EVM, forecast EAC and control project cash flow."}},{name:{vi:"Lãnh đạo & điều phối",en:"Leadership & coordination"},desc:{vi:"Dẫn dắt nhóm nhiều bên, điều hành họp hiệu quả và ra quyết định kịp thời.",en:"Lead multi-party teams, run effective meetings and decide on time."}},{name:{vi:"Quản lý rủi ro",en:"Risk management"},desc:{vi:"Nhận diện, đánh giá và lập kế hoạch ứng phó rủi ro kỹ thuật, tài chính, pháp lý.",en:"Identify, assess and plan responses to technical, financial and legal risks."}},{name:{vi:"Chính trực",en:"Integrity"},desc:{vi:"Báo cáo trung thực với chủ đầu tư, bên cho vay và cơ quan quản lý.",en:"Report truthfully to owners, lenders and authorities."}}],knowledge:{vi:["Các nghị định hiện hành về quản lý dự án đầu tư xây dựng, chất lượng công trình và hợp đồng xây dựng.","Luật Đấu thầu số 22/2023/QH15 về lựa chọn nhà thầu cho dự án sử dụng vốn nhà nước.","PMBOK Guide của PMI: nguyên tắc và lĩnh vực hiệu suất quản lý dự án.","ISO 21502:2020 - Hướng dẫn quản lý dự án.","Phương pháp đường găng (CPM) và quản lý giá trị thu được (EVM): PV, EV, AC, CPI, SPI, EAC."],en:["Current decrees on construction project management, quality of works and construction contracts.","Procurement Law No. 22/2023/QH15 on contractor selection for state-funded projects.","PMI's PMBOK Guide: project management principles and performance domains.","ISO 21502:2020 - Guidance on project management.","Critical path method (CPM) and earned value management (EVM): PV, EV, AC, CPI, SPI, EAC."]},tools:["Phần mềm lập tiến độ CPM","Hệ thống thông tin quản lý dự án (PMIS)","Bảng tính EVM","Mô hình BIM 4D, 5D","Hệ thống văn bản và phê duyệt điện tử"],kpis:{vi:["SPI và CPI của dự án (mục tiêu từ 0,95 trở lên).","Tỷ lệ mốc tiến độ chính hoàn thành đúng hạn.","Số tai nạn lao động có ngày nghỉ (mục tiêu bằng 0).","Chênh lệch giữa EAC và ngân sách được duyệt."],en:["Project SPI and CPI (target 0.95 or above).","Share of key milestones achieved on time.","Lost-time injuries (target zero).","Variance between EAC and the approved budget."]},day:[{time:"07:30",vi:"Đọc báo cáo ngày của công trường, cảnh báo an toàn và tồn tại chất lượng.",en:"Read the site daily report, safety alerts and open quality issues."},{time:"09:00",vi:"Chủ trì giao ban tuần với tư vấn và nhà thầu về tiến độ, đường găng và nguồn lực.",en:"Chair the weekly meeting with consultants and contractors on progress, critical path and resources."},{time:"11:00",vi:"Cập nhật tiến độ thực tế, tính SPI, CPI và dự báo EAC.",en:"Update actual progress, compute SPI and CPI and forecast EAC."},{time:"14:00",vi:"Làm việc với chủ đầu tư về yêu cầu thay đổi và kế hoạch giải ngân.",en:"Meet the owner on change requests and the drawdown plan."},{time:"16:30",vi:"Duyệt kế hoạch phục hồi, ký văn bản và cập nhật sổ đăng ký rủi ro.",en:"Approve the recovery plan, sign correspondence and update the risk register."}],mistakes:{vi:["Chọn đường găng theo cảm tính hoặc theo hạng mục lớn, không tính tổng thời gian.","Dự báo EAC giả định phần còn lại đúng ngân sách trong khi vượt chi có tính hệ thống.","Làm đẹp số liệu báo cáo cho chủ đầu tư, bên cho vay thay vì đưa ra kế hoạch phục hồi."],en:["Choosing the critical path by instinct or by the biggest item without summing durations.","Forecasting EAC as if the rest runs on budget when overspending is systematic.","Dressing up figures for owners or lenders instead of presenting a recovery plan."]},career:[{vi:"Kỹ sư kế hoạch dự án",en:"Project planning engineer"},{vi:"Phó quản lý dự án",en:"Deputy project manager"},{vi:"Quản lý dự án xây dựng",en:"Construction project manager"},{vi:"Giám đốc dự án, giám đốc chương trình",en:"Project director, programme director"}],glossary:[{term:"Critical path",vi:"Chuỗi công việc dài nhất quyết định thời gian hoàn thành dự án; thời gian dự trữ bằng 0.",en:"Longest chain of activities setting the project finish date; it has zero float."},{term:"EVM",vi:"Quản lý giá trị thu được, so sánh PV, EV, AC để đo hiệu suất tiến độ và chi phí.",en:"Earned value management, comparing PV, EV and AC to measure schedule and cost performance."},{term:"CPI",vi:"Chỉ số hiệu suất chi phí bằng EV chia AC; nhỏ hơn 1 nghĩa là đang vượt chi.",en:"Cost performance index equal to EV divided by AC; below 1 means overspending."},{term:"Float",vi:"Thời gian dự trữ mà một công việc có thể chậm mà không làm chậm dự án.",en:"Time an activity can slip without delaying the project."},{term:"Fast-tracking",vi:"Thi công song song các công việc vốn tuần tự để rút ngắn tiến độ, chấp nhận rủi ro cao hơn.",en:"Overlapping activities normally done in sequence to shorten the schedule, accepting higher risk."}],quiz:[{q:{vi:"BAC = 10 000, EV = 4 000, AC = 5 000 (triệu đồng). Nếu hiệu suất chi phí hiện tại tiếp diễn, EAC là bao nhiêu?",en:"BAC = 10,000, EV = 4,000, AC = 5,000 (million VND). If current cost performance continues, what is the EAC?"},options:{vi:["11 000","10 000","12 500","9 000"],en:["11,000","10,000","12,500","9,000"]},answer:2,explain:{vi:"CPI = 4 000 / 5 000 = 0,8; EAC = 10 000 / 0,8 = 12 500 triệu đồng.",en:"CPI = 4,000 / 5,000 = 0.8; EAC = 10,000 / 0.8 = 12,500 million VND."}},{q:{vi:"SPI = 0,8 cho biết điều gì về dự án?",en:"What does SPI = 0.8 tell you about the project?"},options:{vi:["Dự án chậm tiến độ, mới đạt 80% giá trị kế hoạch","Dự án tiết kiệm 20% chi phí","Dự án vượt tiến độ 20%","Dự án đúng kế hoạch"],en:["Behind schedule, earning only 80% of planned value","20% under budget","20% ahead of schedule","Exactly on plan"]},answer:0,explain:{vi:"SPI = EV / PV; giá trị 0,8 nghĩa là khối lượng thực hiện mới bằng 80% kế hoạch.",en:"SPI = EV / PV; 0.8 means only 80% of the planned work has been earned."}},{q:{vi:"Chủ đầu tư yêu cầu báo cáo ngân hàng ghi SPI = 1,0 dù thực tế là 0,8. Bạn làm gì?",en:"The owner asks you to report SPI = 1.0 to the bank although it is 0.8. What do you do?"},options:{vi:["Ghi 1,0 cho kịp giải ngân","Ghi 0,9 cho trung hòa","Không gửi báo cáo nào","Báo cáo số thật, báo giám đốc và kèm kế hoạch phục hồi"],en:["Write 1.0 to secure the drawdown","Write 0.9 as a compromise","Send no report at all","Report the real figure, inform the director and attach a recovery plan"]},answer:3,explain:{vi:"Báo cáo sai cho bên cho vay là gian dối; cách đúng là minh bạch và chứng minh khả năng phục hồi.",en:"Misreporting to a lender is deception; the right path is transparency backed by a credible recovery plan."}},{q:{vi:"Công việc nằm trên đường găng có thời gian dự trữ (float) bằng bao nhiêu?",en:"How much float does an activity on the critical path have?"},options:{vi:["Bằng thời gian của chính nó","Bằng 0","Luôn bằng 1 tuần","Bằng tổng dự trữ của dự án"],en:["Equal to its own duration","Zero","Always one week","Equal to the project's total float"]},answer:1,explain:{vi:"Mọi chậm trễ trên đường găng đều làm chậm ngày hoàn thành nên thời gian dự trữ bằng 0.",en:"Any delay on the critical path delays completion, so its float is zero."}}],tools_en:["CPM scheduling software","Project management information system (PMIS)","EVM spreadsheet","4D and 5D BIM models","Electronic document and approval system"]}},"KK-638":{scenario:{company:"Ngọc Lâm Civil Works",supervisor:{name:"Đặng Thùy Dung",role:{vi:"Trưởng phòng Hợp đồng & Thanh toán",en:"Head of Contracts & Payments"}},ref_code:"IPC-14",title:{vi:"Đúng điều khoản. Đúng khấu trừ. Đúng giá trị.",en:"Right clause. Right deductions. Right amount."},brief:{vi:"Bạn lập đề nghị thanh toán tạm IPC-14 theo hợp đồng FIDIC Sách Đỏ 1999, giá hợp đồng được chấp nhận 120 000 triệu đồng. Giá trị khối lượng lũy kế đến kỳ này 36 460, lũy kế kỳ trước 28 000 (triệu đồng, chưa gồm thuế GTGT). Giữ lại 10% mỗi kỳ, trần 5% giá hợp đồng; đã giữ 2 800. Tạm ứng còn 8 000 chưa thu hồi. Hãy sửa phân loại hạng mục chống thấm bổ sung và số tiền thanh toán thuần kỳ này, rồi lập báo cáo có căn cứ.",en:"You are preparing interim payment application IPC-14 under a FIDIC 1999 Red Book contract with an accepted contract amount of 120,000 million VND. Cumulative work value is 36,460 now and 28,000 at the previous certificate (million VND, excluding VAT). Retention is 10% per period capped at 5% of the contract amount; 2,800 is already held. An advance of 8,000 remains unrecovered. Correct the class of the extra waterproofing item and the net amount due, then write an evidence-based report."},reference_title:{vi:"Hồ sơ hợp đồng & bảng tính thanh toán đã duyệt",en:"Contract file & approved payment worksheet"},fields:[{id:"ITEM_CLASS",label:{vi:"Phân loại hạng mục chống thấm bổ sung",en:"Class of the extra waterproofing item"},initial:"CLAIM-20.1",expected:"VO-13",choices:["VO-13","CLAIM-20.1","DAYWORK-13.6"],reference:"Chỉ dẫn của Kỹ sư EI-117",ref_value:{vi:"Kỹ sư chỉ dẫn bằng văn bản bổ sung lớp chống thấm thứ hai; hợp đồng có đơn giá công việc tương tự",en:"Engineer's written instruction to add a second waterproofing layer; the contract has rates for similar work"},hint:{vi:"Công việc bổ sung do Kỹ sư chỉ dẫn là thay đổi, định giá theo đơn giá hợp đồng; không phải chờ thủ tục khiếu nại.",en:"Additional work instructed by the Engineer is a variation valued at contract rates; no claim procedure is needed."}},{id:"IPC_NET",label:{vi:"Số tiền thanh toán thuần kỳ này (triệu đồng)",en:"Net amount due this period (million VND)"},initial:"7614",expected:"5499",reference:"Bảng tính đề nghị thanh toán IPC-14",ref_value:{vi:"Lũy kế 36 460; kỳ trước 28 000; giữ lại 10%, trần 5% của 120 000; tạm ứng còn 8 000",en:"Cumulative 36,460; previous 28,000; retention 10%, cap 5% of 120,000; advance outstanding 8,000"},hint:{vi:"Bản nháp đã trừ tiền giữ lại nhưng quên khoản thu hồi tạm ứng của kỳ này.",en:"The draft deducted retention but forgot this period's advance recovery."}}],sop32:{vi:"Giá trị kỳ này = lũy kế hiện tại - lũy kế kỳ trước. Giữ lại 10% giá trị kỳ này nếu tổng giữ lại chưa vượt trần. Thu hồi tạm ứng 25% giá trị kỳ này, không vượt số còn lại. Thanh toán thuần = giá trị kỳ này - giữ lại - thu hồi.",en:"Period value = current cumulative - previous cumulative. Retain 10% of the period value while total retention stays within the cap. Recover the advance at 25% of the period value, not exceeding the balance. Net = period value - retention - recovery."},context:{label:"HỢP ĐỒNG / IPC-14",metrics:[{label:{vi:"Giá hợp đồng được chấp nhận",en:"Accepted contract amount"},value:"120,000 M VND"},{label:{vi:"Tiền giữ lại đến kỳ trước",en:"Retention held to date"},value:"2,800 M VND"},{label:{vi:"Tạm ứng chưa thu hồi",en:"Advance outstanding"},value:"8,000 M VND"}]},crisis:{vi:"Giám đốc dự án nhà thầu: “Thêm 600 m3 đắp nền vào khối lượng kỳ này dù chưa đắp, công nhân cần lương trước Tết. Kỳ sau đắp xong là khớp, Kỹ sư không đo kiểm từng lớp đâu.”",en:"The contractor's project director: “Add 600 m3 of embankment fill to this period even though it is not placed yet; the crew needs wages before Tet. It will match next period and the Engineer never measures every layer.”"},options:{safe:{vi:"Không kê khống khối lượng; báo trưởng phòng hợp đồng, đề xuất phương án hợp lệ như thanh toán vật liệu đã tập kết đủ điều kiện (Điều 14.5) hoặc thỏa thuận hỗ trợ dòng tiền bằng văn bản với chủ đầu tư.",en:"Do not inflate quantities; inform the head of contracts and propose valid options such as payment for eligible materials on site (Sub-Clause 14.5) or a written cash-flow arrangement with the Employer."},shortcut:{vi:"Đưa 600 m3 chưa thi công vào đề nghị thanh toán, kỳ sau điều chỉnh lại.",en:"Include the 600 m3 not yet built in the application and adjust it next period."},wait:{vi:"Nộp đề nghị nháp như cũ và chờ Kỹ sư tự đo kiểm, phát hiện sai sót.",en:"Submit the draft unchanged and wait for the Engineer to measure and find the errors."}},questions:{vi:["Giải thích vì sao hạng mục EI-117 là thay đổi theo Điều 13 và cách bạn tính tiền giữ lại, thu hồi tạm ứng, thanh toán thuần.","Kê khống khối lượng trong đề nghị thanh toán gây hậu quả pháp lý và hợp đồng nào? Có những công cụ hợp lệ nào hỗ trợ dòng tiền?"],en:["Explain why item EI-117 is a Clause 13 variation and how you computed retention, advance recovery and the net amount.","What legal and contractual consequences follow from inflating quantities in a payment application? Which valid tools support cash flow?"]},hints:{vi:["Đọc chỉ dẫn EI-117 và xác định ai khởi xướng thay đổi trước khi chọn điều khoản áp dụng.","Theo SOP mục 3.2, tính giá trị kỳ này trước, rồi lần lượt trừ tiền giữ lại và thu hồi tạm ứng, nhớ kiểm tra trần.","SOP mục 4.2: đề nghị thanh toán chỉ gồm khối lượng thực tế; áp lực kê khống phải báo trưởng phòng hợp đồng."],en:["Read instruction EI-117 and identify who initiated the change before choosing the applicable clause.","Under SOP 3.2, compute the period value first, then deduct retention and advance recovery, checking the cap.","SOP 4.2: an application covers only work actually done; escalate pressure to inflate it to the head of contracts."]}},learning:{summary:{vi:"Kỹ sư hợp đồng và thanh toán xây dựng quản lý vòng đời hợp đồng: rà soát điều kiện hợp đồng, lập và kiểm tra hồ sơ thanh toán, quản lý thay đổi, khiếu nại, bảo lãnh và quyết toán. Ở dự án áp dụng FIDIC, họ bảo đảm mọi thông báo, thời hạn và khoản khấu trừ đúng điều khoản. Nghề đòi hỏi tư duy pháp lý, chính xác số liệu, kỹ năng đàm phán và tính trung thực tuyệt đối.",en:"A construction contracts and payment engineer manages the contract life cycle: reviewing conditions, preparing and checking payment applications, managing variations, claims, guarantees and final accounts. On FIDIC projects they make sure every notice, time limit and deduction follows the clauses. The role needs legal reasoning, numerical accuracy, negotiation skills and absolute honesty."},responsibilities:{vi:["Rà soát điều kiện chung, điều kiện riêng, phụ lục và phân bổ rủi ro của hợp đồng.","Lập, kiểm tra hồ sơ thanh toán tạm, khấu trừ tạm ứng, tiền giữ lại và thuế.","Quản lý thay đổi, định giá công việc bổ sung và theo dõi thời hạn thông báo khiếu nại.","Theo dõi bảo lãnh thực hiện, bảo lãnh tạm ứng, bảo hiểm và gia hạn kịp thời.","Chuẩn bị hồ sơ quyết toán, thanh lý hợp đồng và lưu vết thư từ hợp đồng."],en:["Review general and particular conditions, appendices and the contract's risk allocation.","Prepare and check interim payments, advance recovery, retention and taxes.","Manage variations, value additional work and track claim notice deadlines.","Track performance and advance guarantees and insurances and renew them on time.","Prepare final accounts and contract close-out and keep a trail of contract letters."]},competencies:[{name:{vi:"Hiểu điều kiện hợp đồng FIDIC",en:"FIDIC conditions"},desc:{vi:"Nắm điều khoản thanh toán, thay đổi, khiếu nại, thời hạn và giải quyết tranh chấp.",en:"Master the payment, variation, claim, time limit and dispute clauses."}},{name:{vi:"Tính toán thanh toán",en:"Payment calculation"},desc:{vi:"Tính chính xác giá trị kỳ, tiền giữ lại, thu hồi tạm ứng, điều chỉnh giá và thuế.",en:"Compute period value, retention, advance recovery, price adjustment and tax accurately."}},{name:{vi:"Quản lý thay đổi & khiếu nại",en:"Variations & claims"},desc:{vi:"Phân biệt thay đổi, khiếu nại, công nhật; lập hồ sơ đủ căn cứ, đúng hạn.",en:"Distinguish variations, claims and daywork; prepare well-evidenced, timely submissions."}},{name:{vi:"Đàm phán & thư tín hợp đồng",en:"Negotiation & correspondence"},desc:{vi:"Viết thư hợp đồng rõ ràng, lập luận chặt chẽ, giữ quan hệ hợp tác.",en:"Write clear, well-argued contract letters while keeping relationships cooperative."}},{name:{vi:"Liêm chính",en:"Integrity"},desc:{vi:"Không kê khống, không che giấu rủi ro hợp đồng với bất kỳ bên nào.",en:"Never inflate claims or hide contractual risk from any party."}}],knowledge:{vi:["Điều kiện hợp đồng FIDIC Sách Đỏ 1999 và 2017 cho công trình do chủ đầu tư thiết kế.","FIDIC 1999: Điều 13 (thay đổi), Điều 14 (giá hợp đồng và thanh toán), Điều 20 (khiếu nại, tranh chấp).","Nghị định 37/2015/NĐ-CP về hợp đồng xây dựng, sửa đổi bởi Nghị định 50/2021/NĐ-CP.","Bộ luật Dân sự 2015 về hợp đồng và Luật Thương mại 2005 về phạt vi phạm, bồi thường thiệt hại.","Quy định hiện hành về thuế giá trị gia tăng và hóa đơn điện tử trong thanh toán xây dựng."],en:["FIDIC 1999 and 2017 Red Book conditions for works designed by the Employer.","FIDIC 1999: Clause 13 (variations), Clause 14 (contract price and payment), Clause 20 (claims and disputes).","Decree 37/2015/ND-CP on construction contracts, amended by Decree 50/2021/ND-CP.","Civil Code 2015 on contracts and Commercial Law 2005 on penalties and damages.","Current rules on value added tax and e-invoices in construction payments."]},tools:["Phần mềm quản lý hợp đồng và thanh toán","Microsoft Excel","Hệ thống quản lý thư từ dự án","Phần mềm dự toán xây dựng","Sổ theo dõi bảo lãnh và thời hạn"],kpis:{vi:["Tỷ lệ đề nghị thanh toán được Kỹ sư xác nhận không phải điều chỉnh.","Số thông báo khiếu nại bị quá hạn (mục tiêu bằng 0).","Thời gian trung bình từ khi nộp đề nghị đến khi nhận tiền.","Số bảo lãnh hết hạn mà chưa được gia hạn (mục tiêu bằng 0)."],en:["Share of payment applications certified without adjustment.","Claim notices issued late (target zero).","Average time from application to receipt of payment.","Guarantees expired without renewal (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra sổ thời hạn: thông báo khiếu nại, bảo lãnh, bảo hiểm sắp đến hạn.",en:"Check the deadline log: claim notices, guarantees and insurances falling due."},{time:"09:30",vi:"Đối chiếu biên bản nghiệm thu khối lượng với bảng giá để lập đề nghị thanh toán.",en:"Match measurement records with the bill of quantities to build the application."},{time:"11:00",vi:"Định giá hạng mục thay đổi theo đơn giá hợp đồng, chuẩn bị hồ sơ trình Kỹ sư.",en:"Value variation items at contract rates and prepare the submission to the Engineer."},{time:"14:00",vi:"Họp với Kỹ sư làm rõ các khoản khấu trừ và khối lượng còn tranh chấp.",en:"Meet the Engineer to clarify deductions and disputed quantities."},{time:"16:30",vi:"Soạn thư hợp đồng, cập nhật nhật ký thay đổi và lưu hồ sơ.",en:"Draft contract letters, update the variation log and file the records."}],mistakes:{vi:["Quên thu hồi tạm ứng hoặc tính tiền giữ lại vượt trần quy định trong hợp đồng.","Xử lý công việc do Kỹ sư chỉ dẫn như khiếu nại, làm chậm định giá và thanh toán.","Gửi thông báo khiếu nại quá thời hạn 28 ngày, có thể mất quyền đòi gia hạn và chi phí."],en:["Forgetting advance recovery or retaining beyond the contractual cap.","Treating Engineer-instructed work as a claim, delaying valuation and payment.","Giving claim notice after the 28-day limit, which can forfeit time and cost entitlement."]},career:[{vi:"Kỹ sư khối lượng, thanh toán",en:"Quantity and payment engineer"},{vi:"Kỹ sư hợp đồng",en:"Contracts engineer"},{vi:"Trưởng phòng hợp đồng",en:"Contracts manager"},{vi:"Giám đốc thương mại dự án",en:"Commercial director"}],glossary:[{term:"IPC",vi:"Chứng chỉ thanh toán tạm do Kỹ sư phát hành, xác nhận số tiền chủ đầu tư phải trả mỗi kỳ.",en:"Interim payment certificate issued by the Engineer stating the amount the Employer must pay each period."},{term:"Retention money",vi:"Tiền giữ lại mỗi kỳ để bảo đảm nghĩa vụ của nhà thầu, hoàn trả theo các mốc hợp đồng.",en:"Money withheld each period to secure the contractor's obligations, released at contract milestones."},{term:"Variation",vi:"Thay đổi công việc do Kỹ sư chỉ dẫn hoặc chấp thuận theo Điều 13.",en:"Change to the Works instructed or approved by the Engineer under Clause 13."},{term:"Advance payment",vi:"Khoản tạm ứng ban đầu cho nhà thầu, thu hồi dần qua các kỳ thanh toán.",en:"Initial advance to the contractor, recovered progressively through payment certificates."},{term:"Time bar",vi:"Cơ chế làm mất quyền khiếu nại nếu không thông báo trong thời hạn quy định.",en:"Mechanism that removes the right to claim if notice is not given within the stated period."}],quiz:[{q:{vi:"Giá trị kỳ này 4 000 triệu đồng, giữ lại 10%, thu hồi tạm ứng 25%. Số tiền thanh toán thuần là bao nhiêu?",en:"The period value is 4,000 million VND, retention 10% and advance recovery 25%. What is the net amount?"},options:{vi:["3 600 triệu","3 000 triệu","2 600 triệu","2 400 triệu"],en:["3,600 million","3,000 million","2,600 million","2,400 million"]},answer:2,explain:{vi:"4 000 - 400 - 1 000 = 2 600 triệu đồng.",en:"4,000 - 400 - 1,000 = 2,600 million VND."}},{q:{vi:"Theo FIDIC Sách Đỏ 1999, nhà thầu phải gửi thông báo khiếu nại trong bao lâu kể từ khi biết sự kiện?",en:"Under the FIDIC 1999 Red Book, within how long must the contractor give notice of a claim after becoming aware of the event?"},options:{vi:["14 ngày","56 ngày","90 ngày","28 ngày"],en:["14 days","56 days","90 days","28 days"]},answer:3,explain:{vi:"Điều 20.1 yêu cầu thông báo trong 28 ngày; quá hạn có thể mất quyền gia hạn thời gian và thanh toán bổ sung.",en:"Sub-Clause 20.1 requires notice within 28 days; late notice can forfeit extension of time and additional payment."}},{q:{vi:"Giám đốc dự án yêu cầu đưa khối lượng chưa thi công vào đề nghị thanh toán. Bạn làm gì?",en:"The project director asks you to include unbuilt quantities in the payment application. What do you do?"},options:{vi:["Từ chối, báo trưởng phòng và đề xuất cơ chế hợp lệ như thanh toán vật liệu đã tập kết","Đưa vào rồi kỳ sau trừ lại","Đưa vào một nửa khối lượng","Gửi luôn để Kỹ sư tự quyết định"],en:["Refuse, inform the head of contracts and propose valid tools such as payment for materials on site","Include it and deduct next period","Include half of it","Submit and let the Engineer decide"]},answer:0,explain:{vi:"Kê khống là gian lận thanh toán; hợp đồng có công cụ hợp lệ để hỗ trợ dòng tiền khi đủ điều kiện.",en:"Inflating quantities is payment fraud; the contract offers valid tools to support cash flow when conditions are met."}},{q:{vi:"Kỹ sư chỉ dẫn bằng văn bản làm thêm một hạng mục. Theo FIDIC, đây là gì?",en:"The Engineer instructs additional work in writing. Under FIDIC, what is this?"},options:{vi:["Khiếu nại theo Điều 20","Thay đổi theo Điều 13","Sự kiện bất khả kháng","Sai sót của nhà thầu"],en:["A Clause 20 claim","A Clause 13 variation","A force majeure event","A contractor defect"]},answer:1,explain:{vi:"Chỉ dẫn thay đổi của Kỹ sư là thay đổi theo Điều 13, được định giá và đưa vào chứng chỉ thanh toán.",en:"An Engineer's change instruction is a Clause 13 variation, valued and included in payment certificates."}}],tools_en:["Contract and payment management software","Microsoft Excel","Project correspondence management system","Construction cost estimating software","Guarantee and deadline tracking register"]}},"KK-639":{scenario:{company:"Tầng Sâu Geotechnical Services",supervisor:{name:"Hồ Sỹ Tuấn",role:{vi:"Chủ nhiệm địa kỹ thuật",en:"Principal Geotechnical Engineer"}},ref_code:"GEO-BH07",title:{vi:"Phân loại đúng đất. Tính đúng ứng suất hữu hiệu.",en:"Classify the soil right. Compute effective stress right."},brief:{vi:"Bạn soát xét báo cáo GEO-BH07 phục vụ thiết kế cọc khoan nhồi. Hố khoan BH-07: lớp 1 từ 0 đến 1,5 m, γ = 18,5 kN/m3; mực nước ngầm ổn định ở -1,5 m; lớp 2 sét từ 1,5 đến 9,5 m, γsat = 18,8 kN/m3, LL = 58%, PL = 28%; lớp 3 cát từ 9,5 đến 21,5 m, γsat = 19,6 kN/m3. Mũi cọc ở -21,5 m. Hãy sửa ký hiệu phân loại lớp 2 và ứng suất hữu hiệu thẳng đứng tại mũi cọc (kPa), rồi lập báo cáo có căn cứ.",en:"You are reviewing report GEO-BH07 for bored pile design. Borehole BH-07: layer 1 from 0 to 1.5 m, γ = 18.5 kN/m3; stable groundwater at -1.5 m; layer 2 clay from 1.5 to 9.5 m, γsat = 18.8 kN/m3, LL = 58%, PL = 28%; layer 3 sand from 9.5 to 21.5 m, γsat = 19.6 kN/m3. The pile toe is at -21.5 m. Correct the layer 2 classification symbol and the vertical effective stress at the pile toe (kPa), then write an evidence-based report."},reference_title:{vi:"Nhật ký hố khoan BH-07 & kết quả thí nghiệm đã duyệt",en:"Approved BH-07 borehole log & laboratory results"},fields:[{id:"SOIL_L2",label:{vi:"Ký hiệu phân loại USCS lớp 2",en:"USCS symbol of layer 2"},initial:"USCS-CL",expected:"USCS-CH",choices:["USCS-CL","USCS-CH","USCS-MH"],reference:"Phiếu kết quả giới hạn Atterberg",ref_value:{vi:"Lớp 2: LL = 58%, PL = 28%; biểu đồ dẻo Casagrande, đường A: PI = 0,73 x (LL - 20)",en:"Layer 2: LL = 58%, PL = 28%; Casagrande plasticity chart, A-line: PI = 0.73 x (LL - 20)"},hint:{vi:"Tính PI = LL - PL, so với đường A và ranh giới LL = 50% trước khi chọn ký hiệu.",en:"Compute PI = LL - PL, then compare with the A-line and the LL = 50% boundary before choosing."}},{id:"SIGMA_V",label:{vi:"Ứng suất hữu hiệu tại mũi cọc (kPa)",en:"Effective stress at pile toe (kPa)"},initial:"413.35",expected:"213.35",reference:"Bảng tính ứng suất theo chiều sâu",ref_value:{vi:"Lớp 1: 1,5 m, γ 18,5; lớp 2: 8 m, γsat 18,8; lớp 3: 12 m, γsat 19,6; nước ngầm -1,5 m",en:"Layer 1: 1.5 m, γ 18.5; layer 2: 8 m, γsat 18.8; layer 3: 12 m, γsat 19.6; groundwater -1.5 m"},hint:{vi:"Bản nháp dùng trọng lượng riêng bão hòa cho cả phần dưới mực nước, tức là đang tính ứng suất tổng.",en:"The draft used saturated unit weights below the water table, which gives total stress."}}],sop32:{vi:"Trên mực nước ngầm dùng γ; dưới mực nước ngầm dùng γ' = γsat - γw với γw = 10 kN/m3 (mô phỏng). σ'v = tổng γ x chiều dày của từng lớp đến cao độ mũi cọc; ghi đến 0,01 kPa.",en:"Above groundwater use γ; below it use γ' = γsat - γw with γw = 10 kN/m3 (simulated). σ'v = sum of unit weight x thickness of each layer down to the pile toe; state to 0.01 kPa."},context:{label:"GEO-DB / BH-07",metrics:[{label:{vi:"Mực nước ngầm",en:"Groundwater level"},value:"-1.5 m"},{label:{vi:"Cao độ mũi cọc",en:"Pile toe level"},value:"-21.5 m"},{label:{vi:"Đường kính cọc",en:"Pile diameter"},value:"1000 mm"}]},terminal:{system:"geo-db",settable:["SOIL_L2","SIGMA_V"],commands:[{cmd:"status",out:{vi:"Báo cáo GEO-BH07 (nháp): lớp 2 = USCS-CL; σ'v tại mũi cọc = 413,35 kPa; trạng thái: chờ soát xét",en:"Report GEO-BH07 (draft): layer 2 = USCS-CL; toe σ'v = 413.35 kPa; status: pending review"}},{cmd:"cat bh-07.log",out:{vi:"0-1,5 m: đất lấp, γ 18,5; 1,5-9,5 m: sét xám xanh dẻo mềm, γsat 18,8; 9,5-21,5 m: cát hạt trung chặt vừa, γsat 19,6",en:"0-1.5 m: fill, γ 18.5; 1.5-9.5 m: soft grey-green clay, γsat 18.8; 9.5-21.5 m: medium dense medium sand, γsat 19.6"}},{cmd:"lab atterberg l2",out:{vi:"Mẫu UD-07-3 lớp 2: LL = 58%, PL = 28%, độ ẩm tự nhiên 49%",en:"Sample UD-07-3 layer 2: LL = 58%, PL = 28%, natural moisture content 49%"}},{cmd:"cat gwt.txt",out:{vi:"Mực nước ngầm ổn định đo sau 24 giờ: -1,5 m so với mặt đất tự nhiên",en:"Stable groundwater measured after 24 h: -1.5 m below natural ground"}},{cmd:"calc stress --draft",out:{vi:"Bản nháp: σ = 18,5 x 1,5 + 18,8 x 8 + 19,6 x 12 = 413,35 kPa (chưa trừ áp lực nước lỗ rỗng)",en:"Draft: σ = 18.5 x 1.5 + 18.8 x 8 + 19.6 x 12 = 413.35 kPa (pore water pressure not deducted)"}}]},crisis:{vi:"Nhà thầu cọc nhắn: “Sửa SPT lớp cát lên trên 50 và giữ số ứng suất nháp để cọc ngắn đi 6 m, đỡ phải nén tĩnh lại. Báo cáo khảo sát thì ai khoan lại kiểm tra.”",en:"The piling contractor texts: “Raise the SPT in the sand above 50 and keep the draft stress so the piles get 6 m shorter and we skip another load test. Nobody re-drills to check a site investigation report.”"},options:{safe:{vi:"Không sửa số liệu khảo sát; báo chủ nhiệm địa kỹ thuật và chủ trì thiết kế, phát hành bảng tính đã hiệu chỉnh; nếu muốn tối ưu chiều dài cọc thì đề xuất khoan bổ sung và nén tĩnh cọc thử.",en:"Do not alter investigation data; inform the principal geotechnical engineer and design lead and issue the corrected calculation; to optimize pile length, propose extra boreholes and static load tests on trial piles."},shortcut:{vi:"Sửa SPT và giữ ứng suất nháp như nhà thầu đề nghị để rút ngắn cọc.",en:"Edit the SPT values and keep the draft stress as the contractor asks to shorten the piles."},wait:{vi:"Không sửa, không báo ai và để nhà thầu tự làm việc với đơn vị thiết kế.",en:"Change nothing, tell no one and let the contractor deal with the designer."}},questions:{vi:["Giải thích cách bạn phân loại lớp 2 bằng biểu đồ dẻo và cách tính ứng suất hữu hiệu tại mũi cọc.","Dùng ứng suất tổng hoặc sửa số SPT gây rủi ro gì cho sức chịu tải và độ lún của cọc? Bạn xử lý đề nghị của nhà thầu thế nào?"],en:["Explain how you classified layer 2 on the plasticity chart and how you computed the effective stress at the pile toe.","What risks do total stress or edited SPT values create for pile capacity and settlement? How do you handle the contractor's request?"]},hints:{vi:["Chạy lệnh xem số liệu Atterberg và nhật ký hố khoan, tính chỉ số dẻo trước khi chọn ký hiệu.","Theo SOP mục 3.2, tách phần trên và dưới mực nước ngầm, dùng trọng lượng riêng đẩy nổi cho phần dưới.","SOP mục 4.2: số liệu khảo sát là bằng chứng gốc, không được chỉnh sửa; mọi đề nghị sửa phải báo chủ nhiệm."],en:["Run the Atterberg and borehole log commands and compute the plasticity index before choosing a symbol.","Under SOP 3.2, split the profile above and below groundwater and use the submerged unit weight below it.","SOP 4.2: investigation data is primary evidence and must not be edited; escalate any such request to the principal."]}},learning:{summary:{vi:"Kỹ sư địa kỹ thuật và nền móng lập phương án khảo sát, phân tích số liệu đất đá, đánh giá điều kiện địa chất và thiết kế giải pháp móng nông, móng cọc, xử lý nền, tường chắn và hố đào sâu. Họ quyết định công trình có đứng vững, lún trong giới hạn và an toàn cho công trình lân cận hay không. Nghề đòi hỏi nền tảng cơ học đất vững, kinh nghiệm hiện trường và sự trung thực tuyệt đối với số liệu gốc.",en:"A geotechnical and foundation engineer plans site investigations, analyses soil and rock data, assesses ground conditions and designs shallow foundations, piles, ground improvement, retaining walls and deep excavations. They decide whether a structure stands firm, settles within limits and stays safe for its neighbours. The role requires solid soil mechanics, field experience and absolute honesty with primary data."},responsibilities:{vi:["Lập nhiệm vụ, phương án khảo sát: số lượng, chiều sâu hố khoan và thí nghiệm hiện trường.","Giám sát khoan, lấy mẫu, thí nghiệm SPT, CPT và kiểm tra kết quả thí nghiệm trong phòng.","Phân loại đất, lập mặt cắt địa chất và chọn thông số tính toán đại diện cho từng lớp.","Tính sức chịu tải, độ lún của móng cọc, móng nông và kiểm tra ổn định hố đào.","Thiết kế, giám sát thí nghiệm nén tĩnh cọc và quan trắc lún, nghiêng, nước ngầm."],en:["Define the investigation scope: number and depth of boreholes and in-situ tests.","Supervise drilling, sampling, SPT and CPT tests and check laboratory results.","Classify soils, draw geological sections and select representative design parameters per layer.","Compute capacity and settlement of piles and shallow footings and check excavation stability.","Design and supervise static pile load tests and monitoring of settlement, tilt and groundwater."]},competencies:[{name:{vi:"Cơ học đất",en:"Soil mechanics"},desc:{vi:"Hiểu ứng suất hữu hiệu, cố kết, sức kháng cắt và ứng xử thoát nước, không thoát nước.",en:"Understand effective stress, consolidation, shear strength and drained versus undrained behaviour."}},{name:{vi:"Khảo sát & thí nghiệm",en:"Investigation & testing"},desc:{vi:"Đánh giá chất lượng khoan, lấy mẫu, SPT, CPT, Atterberg và nén cố kết.",en:"Judge the quality of drilling, sampling, SPT, CPT, Atterberg and oedometer tests."}},{name:{vi:"Thiết kế nền móng",en:"Foundation design"},desc:{vi:"Chọn giải pháp móng, tính sức chịu tải và độ lún theo tiêu chuẩn hiện hành.",en:"Select foundation solutions and compute capacity and settlement to current standards."}},{name:{vi:"Phân tích số",en:"Numerical analysis"},desc:{vi:"Dùng phần mềm phần tử hữu hạn, phân tích ổn định mái dốc và tường chắn.",en:"Use finite element software and analyse slope and retaining wall stability."}},{name:{vi:"Trung thực với số liệu",en:"Data integrity"},desc:{vi:"Bảo vệ tính nguyên vẹn của số liệu khảo sát trước áp lực chi phí, tiến độ.",en:"Protect the integrity of investigation data against cost and schedule pressure."}}],knowledge:{vi:["TCVN 10304:2014 - Móng cọc: tiêu chuẩn thiết kế.","TCVN 9362:2012 - Tiêu chuẩn thiết kế nền nhà và công trình.","TCVN 9393:2012 - Cọc: phương pháp thử nghiệm hiện trường bằng tải trọng tĩnh ép dọc trục.","TCVN 9351:2012 - Đất xây dựng: thí nghiệm hiện trường xuyên tiêu chuẩn (SPT).","Hệ thống phân loại đất thống nhất USCS (ASTM D2487) và biểu đồ dẻo Casagrande.","Nguyên lý ứng suất hữu hiệu của Terzaghi: σ' = σ - u."],en:["TCVN 10304:2014 - Pile foundations: design standard.","TCVN 9362:2012 - Design standard for foundations of buildings and structures.","TCVN 9393:2012 - Piles: field test method under axial compressive static load.","TCVN 9351:2012 - Soils for construction: standard penetration test (SPT).","Unified Soil Classification System USCS (ASTM D2487) and the Casagrande plasticity chart.","Terzaghi's effective stress principle: σ' = σ - u."]},tools:["Máy khoan khảo sát và bộ thí nghiệm SPT","Thiết bị xuyên tĩnh CPTu","Phần mềm phần tử hữu hạn địa kỹ thuật","Phần mềm tính sức chịu tải cọc","Thiết bị đo nghiêng và quan trắc lún"],kpis:{vi:["Sai lệch giữa sức chịu tải dự báo và kết quả nén tĩnh cọc thử.","Độ lún công trình thực đo so với giới hạn cho phép.","Tỷ lệ hồ sơ khảo sát đủ số liệu, không phải khoan bổ sung do thiếu sót.","Số sự cố hố đào, công trình lân cận (mục tiêu bằng 0)."],en:["Deviation between predicted capacity and static load test results.","Measured settlement against allowable limits.","Share of investigations complete enough to avoid extra drilling due to gaps.","Excavation or neighbouring building incidents (target zero)."]},day:[{time:"07:30",vi:"Có mặt tại hiện trường kiểm tra khoan, mô tả mẫu và ghi số búa SPT.",en:"Be on site to check drilling, log samples and record SPT blow counts."},{time:"10:00",vi:"Kiểm tra kết quả thí nghiệm trong phòng: giới hạn Atterberg, cắt, nén cố kết.",en:"Check laboratory results: Atterberg limits, shear and oedometer tests."},{time:"13:30",vi:"Lập mặt cắt địa chất, chọn thông số đại diện và tính sức chịu tải cọc.",en:"Draw geological sections, choose representative parameters and compute pile capacity."},{time:"15:30",vi:"Họp với chủ trì kết cấu về chiều dài cọc, cọc thử và chương trình nén tĩnh.",en:"Meet the structural lead on pile length, trial piles and the load test programme."},{time:"17:00",vi:"Hoàn thiện bảng tính, lưu số liệu gốc và nhật ký hiện trường.",en:"Finish calculations and archive raw data and field logs."}],mistakes:{vi:["Dùng ứng suất tổng thay cho ứng suất hữu hiệu dưới mực nước ngầm.","Phân loại sét chỉ theo tên gọi, không kiểm tra giới hạn chảy và đường A.","Ngoại suy số liệu từ hố khoan ở xa cho cả khu đất mà không đánh giá biến động địa tầng."],en:["Using total stress instead of effective stress below the water table.","Classifying clay by name alone without checking the liquid limit and A-line.","Extrapolating a distant borehole to the whole site without assessing stratigraphic variation."]},career:[{vi:"Kỹ sư khảo sát địa chất hiện trường",en:"Site investigation engineer"},{vi:"Kỹ sư địa kỹ thuật",en:"Geotechnical engineer"},{vi:"Chủ trì thiết kế nền móng",en:"Lead foundation engineer"},{vi:"Chuyên gia địa kỹ thuật trưởng",en:"Principal geotechnical specialist"}],glossary:[{term:"Effective stress",vi:"Ứng suất do khung hạt đất chịu, bằng ứng suất tổng trừ áp lực nước lỗ rỗng.",en:"Stress carried by the soil skeleton, equal to total stress minus pore water pressure."},{term:"SPT",vi:"Thí nghiệm xuyên tiêu chuẩn, đếm số búa N để xuyên 30 cm, đánh giá độ chặt hoặc trạng thái đất.",en:"Standard penetration test counting blows N for 30 cm to assess soil density or consistency."},{term:"PI",vi:"Chỉ số dẻo bằng giới hạn chảy trừ giới hạn dẻo, phản ánh phạm vi trạng thái dẻo của đất dính.",en:"Plasticity index equal to liquid limit minus plastic limit, the plastic range of fine soils."},{term:"A-line",vi:"Đường phân chia sét và bụi trên biểu đồ dẻo: PI = 0,73 x (LL - 20).",en:"Line separating clays from silts on the plasticity chart: PI = 0.73 x (LL - 20)."},{term:"Static load test",vi:"Thí nghiệm nén tĩnh cọc theo từng cấp tải để xác định quan hệ tải - lún và sức chịu tải.",en:"Stepwise static loading of a pile to define its load-settlement curve and capacity."}],quiz:[{q:{vi:"Lớp cát dưới mực nước ngầm dày 5 m, γsat = 20 kN/m3, γw = 10 kN/m3. Ứng suất hữu hiệu tăng thêm qua lớp này là bao nhiêu?",en:"A sand layer below groundwater is 5 m thick, γsat = 20 kN/m3, γw = 10 kN/m3. How much does effective stress increase across it?"},options:{vi:["100 kPa","150 kPa","50 kPa","20 kPa"],en:["100 kPa","150 kPa","50 kPa","20 kPa"]},answer:2,explain:{vi:"γ' = 20 - 10 = 10 kN/m3; tăng thêm 10 x 5 = 50 kPa.",en:"γ' = 20 - 10 = 10 kN/m3; the increase is 10 x 5 = 50 kPa."}},{q:{vi:"Mẫu đất hạt mịn có LL = 40% và PI = 22. Theo USCS, ký hiệu phân loại là gì?",en:"A fine-grained soil has LL = 40% and PI = 22. What is its USCS symbol?"},options:{vi:["CL","CH","ML","MH"],en:["CL","CH","ML","MH"]},answer:0,explain:{vi:"Đường A tại LL = 40 là PI = 14,6; PI = 22 nằm trên đường A và LL dưới 50 nên là CL.",en:"The A-line at LL = 40 gives PI = 14.6; PI = 22 lies above it and LL is below 50, so it is CL."}},{q:{vi:"Nhà thầu đề nghị sửa số SPT để rút ngắn chiều dài cọc. Bạn làm gì?",en:"The contractor asks you to edit SPT values to shorten the piles. What do you do?"},options:{vi:["Sửa nhẹ cho hợp lý","Sửa và thêm ghi chú nhỏ","Không phản hồi gì","Từ chối, báo chủ nhiệm và đề xuất khoan bổ sung, nén tĩnh cọc thử"],en:["Edit slightly to look reasonable","Edit and add a small note","Do not respond","Refuse, inform the principal and propose extra boreholes and trial pile load tests"]},answer:3,explain:{vi:"Sửa số liệu khảo sát là làm giả hồ sơ và có thể gây sự cố móng; tối ưu hợp lệ phải dựa trên số liệu bổ sung.",en:"Editing investigation data falsifies records and can cause foundation failure; valid optimization relies on additional data."}},{q:{vi:"Vì sao dưới mực nước ngầm phải dùng trọng lượng riêng đẩy nổi khi tính σ'v?",en:"Why must the submerged unit weight be used below groundwater when computing σ'v?"},options:{vi:["Vì đất dưới nước nhẹ hơn khi khô","Vì áp lực nước lỗ rỗng gánh một phần ứng suất tổng","Vì tiêu chuẩn cho phép bỏ qua nước ngầm","Vì γsat luôn nhỏ hơn γ"],en:["Because soil under water is lighter when dry","Because pore water pressure carries part of the total stress","Because standards allow ignoring groundwater","Because γsat is always below γ"]},answer:1,explain:{vi:"σ' = σ - u; dưới mực nước, áp lực nước lỗ rỗng tăng theo chiều sâu nên khung hạt chỉ chịu γ' = γsat - γw.",en:"σ' = σ - u; below the water table pore pressure grows with depth, so the skeleton carries only γ' = γsat - γw."}}],tools_en:["Site investigation drill rig and SPT kit","CPTu cone penetration test equipment","Geotechnical finite element software","Pile bearing capacity software","Inclinometer and settlement monitoring devices"]}},"KK-640":{scenario:{company:"Sông Mây Bridge & Road Consultants",supervisor:{name:"Lâm Gia Hưng",role:{vi:"Chủ trì thiết kế cầu",en:"Lead Bridge Engineer"}},ref_code:"BRG-0905",title:{vi:"Biết gối cố định ở đâu, tính chuyển vị từ đó.",en:"Know the fixed bearing, measure movement from it."},brief:{vi:"Bạn soát xét hồ sơ khe co giãn BRG-0905 tại mố M2 của cầu dầm liên tục bê tông dự ứng lực dài 90 m. Gối cố định đặt tại mố M1; các trụ và mố M2 dùng gối di động dọc. Biên độ nhiệt kết cấu thiết kế 50 °C, α = 10,8 x 10^-6 /°C; co ngót, từ biến quy đổi 0,0002 x chiều dài giãn nở (mô phỏng). Hãy sửa loại khe co giãn và tổng chuyển vị thiết kế tại khe M2 (mm), rồi lập báo cáo có căn cứ.",en:"You are reviewing expansion joint file BRG-0905 at abutment M2 of a 90 m continuous prestressed concrete girder bridge. The fixed bearing is at abutment M1; the piers and M2 have longitudinally movable bearings. The design structural temperature range is 50 °C, α = 10.8 x 10^-6 /°C; shrinkage and creep equal 0.0002 x expansion length (simulated). Correct the joint type and the total design movement at joint M2 (mm), then write an evidence-based report."},reference_title:{vi:"Sơ đồ gối cầu & bảng chọn khe co giãn đã duyệt",en:"Approved bearing layout & joint selection table"},fields:[{id:"JOINT_TYPE",label:{vi:"Loại khe co giãn tại mố M2",en:"Expansion joint type at abutment M2"},initial:"ASPHALTIC-PLUG",expected:"STRIP-SEAL",choices:["ASPHALTIC-PLUG","STRIP-SEAL","MODULAR"],reference:"Bảng chọn khe co giãn của dự án",ref_value:{vi:"Theo tổng chuyển vị (mô phỏng): đến 40 mm khe bitum; 40-100 mm khe dải cao su; trên 100 mm khe module",en:"By total movement (simulated): up to 40 mm asphaltic plug; 40-100 mm strip seal; over 100 mm modular"},hint:{vi:"Loại khe chỉ chọn được sau khi có tổng chuyển vị đúng; bản nháp chọn theo một chuyển vị đã tính sai.",en:"The joint type follows from the correct total movement; the draft chose it from a wrong value."}},{id:"MOVE_MM",label:{vi:"Tổng chuyển vị thiết kế tại khe M2 (mm)",en:"Total design movement at joint M2 (mm)"},initial:"33.3",expected:"66.6",reference:"Bảng tính chuyển vị khe co giãn",ref_value:{vi:"Chiều dài cầu 90 m; gối cố định tại M1; ΔT 50 °C; α 10,8 x 10^-6 /°C; co ngót, từ biến 0,0002 L",en:"Bridge length 90 m; fixed bearing at M1; ΔT 50 °C; α 10.8 x 10^-6 /°C; shrinkage, creep 0.0002 L"},hint:{vi:"Bản nháp lấy chiều dài giãn nở bằng nửa cầu, như thể gối cố định nằm ở giữa cầu.",en:"The draft took half the bridge as the expansion length, as if the fixed bearing were at midspan."}}],sop32:{vi:"Chiều dài giãn nở L = khoảng cách từ gối cố định đến khe. Chuyển vị nhiệt = α x L x ΔT; co ngót, từ biến = 0,0002 x L; tổng chuyển vị = nhiệt + co ngót, từ biến, ghi đến 0,1 mm.",en:"Expansion length L = distance from the fixed bearing to the joint. Thermal movement = α x L x ΔT; shrinkage and creep = 0.0002 x L; total movement = thermal + shrinkage and creep, stated to 0.1 mm."},context:{label:"BRIDGE-CAD / BRG-0905",metrics:[{label:{vi:"Chiều dài liên tục",en:"Continuous length"},value:"90 m"},{label:{vi:"Biên độ nhiệt kết cấu",en:"Structural temperature range"},value:"50 °C"},{label:{vi:"Vị trí gối cố định",en:"Fixed bearing location"},value:"M1"}]},terminal:{system:"bridge-design",settable:["JOINT_TYPE","MOVE_MM"],commands:[{cmd:"status",out:{vi:"Hồ sơ BRG-0905 (nháp): khe M2 = ASPHALTIC-PLUG; tổng chuyển vị 33,3 mm; đã gửi nhà thầu đặt hàng",en:"File BRG-0905 (draft): joint M2 = ASPHALTIC-PLUG; total movement 33.3 mm; sent to the contractor for ordering"}},{cmd:"cat bearing-layout.txt",out:{vi:"M1: gối cố định; T1, T2: gối di động dọc; M2: gối di động dọc. Chiều dài liên tục 90 m",en:"M1: fixed bearing; P1, P2: longitudinally movable; M2: longitudinally movable. Continuous length 90 m"}},{cmd:"cat climate.txt",out:{vi:"Nhiệt độ kết cấu thiết kế (mô phỏng): lớn nhất 55 °C, nhỏ nhất 5 °C",en:"Design structural temperature (simulated): maximum 55 °C, minimum 5 °C"}},{cmd:"cat material.txt",out:{vi:"Bê tông thường: α = 10,8 x 10^-6 /°C; co ngót, từ biến quy đổi 0,0002 x L",en:"Normal-weight concrete: α = 10.8 x 10^-6 /°C; equivalent shrinkage and creep 0.0002 x L"}},{cmd:"calc movement --draft",out:{vi:"Bản nháp: L = 45 m (giả định gối cố định ở giữa cầu), chuyển vị 24,3 + 9,0 = 33,3 mm",en:"Draft: L = 45 m (fixed bearing assumed at midspan), movement 24.3 + 9.0 = 33.3 mm"}}]},crisis:{vi:"Nhà thầu: “Khe bitum đã đặt hàng, đổi loại là trễ lễ thông xe. Anh ký duyệt shop drawing giữ khe bitum đi, hỏng thì kỳ bảo trì thay.” Trưởng ban quản lý dự án cũng muốn ký cho kịp ngày khánh thành.",en:"The contractor: “The asphaltic plug joints are already ordered; changing type delays the opening. Approve the shop drawing with the plug joint and maintenance can replace it later.” The PMU head also wants it signed for the ceremony."},options:{safe:{vi:"Không duyệt khe sai loại; báo chủ trì thiết kế và ban quản lý dự án bằng văn bản, đề xuất đặt gấp khe dải cao su đúng chuyển vị hoặc phương án tạm được thiết kế phê duyệt và kiểm tra trước thông xe.",en:"Do not approve the wrong joint; notify the design lead and PMU in writing and propose expedited supply of a strip seal sized for the movement or a designer-approved interim solution checked before opening."},shortcut:{vi:"Ký duyệt khe bitum cho kịp lễ thông xe, ghi chú thay thế trong kỳ bảo trì.",en:"Approve the plug joint to make the opening and note a replacement in the maintenance cycle."},wait:{vi:"Không ký nhưng cũng không phản hồi, để nhà thầu tự lắp theo vật tư đã đặt.",en:"Do not sign or reply, leaving the contractor to install what was ordered."}},questions:{vi:["Giải thích cách bạn xác định chiều dài giãn nở từ sơ đồ gối và tính tổng chuyển vị tại khe M2.","Lắp khe co giãn không đủ khả năng chuyển vị gây hư hỏng và rủi ro an toàn giao thông nào? Bạn xử lý áp lực tiến độ ra sao?"],en:["Explain how you derived the expansion length from the bearing layout and computed the total movement at joint M2.","What damage and traffic safety risks follow from installing a joint with insufficient movement capacity? How do you handle the schedule pressure?"]},hints:{vi:["Mở sơ đồ bố trí gối và xác định vị trí gối cố định trước khi đo chiều dài giãn nở.","Theo SOP mục 3.2, cộng chuyển vị nhiệt với co ngót, từ biến trên đúng chiều dài từ gối cố định đến khe.","SOP mục 4.2: không phê duyệt thiết bị thiếu khả năng chỉ vì vật tư đã đặt; báo chủ trì và ban quản lý dự án."],en:["Open the bearing layout and locate the fixed bearing before measuring the expansion length.","Under SOP 3.2, add thermal movement to shrinkage and creep over the true length from the fixed bearing to the joint.","SOP 4.2: never approve inadequate equipment because it is already ordered; escalate to the design lead and PMU."]}},learning:{summary:{vi:"Kỹ sư hạ tầng giao thông và cầu đường thiết kế, kiểm định và giám sát đường ô tô, nút giao, cống, cầu dầm và cầu dây, bảo đảm công trình chịu được hoạt tải xe, tác động môi trường và khai thác an toàn trong nhiều thập kỷ. Họ phối hợp khảo sát, thủy văn, địa kỹ thuật và thi công để chọn giải pháp tối ưu chi phí vòng đời. Nghề đòi hỏi cơ học kết cấu vững, hiểu tiêu chuẩn thiết kế cầu đường và trách nhiệm với an toàn giao thông.",en:"A civil infrastructure and bridge engineer designs, inspects and supervises roads, interchanges, culverts, girder and cable bridges, ensuring they carry vehicle loads, resist environmental actions and serve safely for decades. They combine survey, hydrology, geotechnics and construction input to choose the best life-cycle solution. The role needs strong structural mechanics, command of bridge and road design codes and responsibility for traffic safety."},responsibilities:{vi:["Thiết kế bình đồ, trắc dọc, trắc ngang, kết cấu áo đường và hệ thống thoát nước.","Thiết kế kết cấu nhịp, mố trụ, gối cầu, khe co giãn theo tiêu chuẩn thiết kế cầu.","Tính hoạt tải, tác động nhiệt, co ngót, từ biến, động đất và kiểm toán các trạng thái giới hạn.","Duyệt bản vẽ thi công, biện pháp lao lắp dầm và giám sát tác giả tại công trường.","Kiểm định, thử tải và lập kế hoạch bảo trì cầu đường đang khai thác."],en:["Design horizontal and vertical alignment, cross sections, pavement and drainage.","Design superstructure, piers and abutments, bearings and expansion joints to bridge codes.","Compute live load, thermal, shrinkage, creep and seismic effects and check limit states.","Review shop drawings and girder erection methods and provide designer supervision on site.","Inspect and load test bridges and roads in service and plan their maintenance."]},competencies:[{name:{vi:"Thiết kế cầu",en:"Bridge design"},desc:{vi:"Chọn sơ đồ kết cấu, bố trí gối, khe và kiểm toán theo tiêu chuẩn thiết kế cầu đường bộ.",en:"Choose structural systems, arrange bearings and joints and check them to highway bridge codes."}},{name:{vi:"Thiết kế đường",en:"Road design"},desc:{vi:"Thiết kế hình học, kết cấu áo đường, nút giao và tổ chức an toàn giao thông.",en:"Design geometry, pavement structure, interchanges and traffic safety features."}},{name:{vi:"Phân tích kết cấu",en:"Structural analysis"},desc:{vi:"Mô hình hóa cầu, xếp tải bất lợi và phân tích theo các giai đoạn thi công.",en:"Model bridges, place loads in the worst positions and analyse construction stages."}},{name:{vi:"Phối hợp liên ngành",en:"Interdisciplinary coordination"},desc:{vi:"Kết hợp số liệu thủy văn, địa chất, giao thông và biện pháp thi công.",en:"Integrate hydrology, geology, traffic data and construction methods."}},{name:{vi:"Trách nhiệm an toàn công cộng",en:"Public safety accountability"},desc:{vi:"Không phê duyệt giải pháp thiếu an toàn dưới áp lực tiến độ hay ngày khánh thành.",en:"Never approve unsafe solutions under schedule or ceremony pressure."}}],knowledge:{vi:["TCVN 11823:2017 - Thiết kế cầu đường bộ (bộ tiêu chuẩn gồm nhiều phần).","TCVN 4054:2005 - Đường ô tô: yêu cầu thiết kế.","Mô hình hoạt tải HL-93 (xe tải, xe hai trục và tải trọng làn) theo phương pháp hệ số tải trọng và sức kháng.","Nguyên lý bố trí gối cố định, gối di động và tính chuyển vị nhiệt, co ngót, từ biến của kết cấu nhịp.","Quy định hiện hành về quản lý, bảo trì và kiểm định công trình giao thông đường bộ."],en:["TCVN 11823:2017 - Highway bridge design (a multi-part standard).","TCVN 4054:2005 - Highways: design requirements.","HL-93 live load model (design truck, tandem and lane load) under load and resistance factor design.","Principles of fixed and movable bearing layout and thermal, shrinkage and creep movement of the deck.","Current rules on management, maintenance and inspection of road infrastructure."]},tools:["Phần mềm phân tích kết cấu cầu","Phần mềm thiết kế đường và mô hình địa hình","Phần mềm CAD và BIM hạ tầng","Máy toàn đạc, máy thủy bình","Thiết bị đo võng, ứng suất khi thử tải"],kpis:{vi:["Số lỗi thiết kế phát hiện sau phát hành (mục tiêu bằng 0).","Chênh lệch độ võng thử tải thực đo so với tính toán.","Tỷ lệ hồ sơ qua thẩm tra không phải sửa lớn.","Chi phí vòng đời (xây dựng và bảo trì) so với phương án so sánh."],en:["Design errors found after issue (target zero).","Difference between measured and predicted load test deflection.","Share of designs passing review without major changes.","Life-cycle cost (construction and maintenance) against the alternative scheme."]},day:[{time:"08:00",vi:"Rà soát yêu cầu làm rõ kỹ thuật của nhà thầu về gối cầu và khe co giãn.",en:"Review contractor RFIs on bearings and expansion joints."},{time:"09:30",vi:"Chạy mô hình kết cấu nhịp với hoạt tải, nhiệt độ và các giai đoạn thi công.",en:"Run the deck model with live load, temperature and construction stages."},{time:"13:30",vi:"Duyệt shop drawing mố trụ, gối và khe; đối chiếu với chuyển vị thiết kế.",en:"Review shop drawings for substructure, bearings and joints against design movements."},{time:"15:30",vi:"Họp với ban quản lý dự án về tiến độ lao dầm và kế hoạch thử tải.",en:"Meet the PMU on girder erection progress and the load test plan."},{time:"17:00",vi:"Cập nhật thuyết minh, ghi nhật ký thay đổi và lưu hồ sơ.",en:"Update the design report, log changes and archive the file."}],mistakes:{vi:["Tính chuyển vị từ giữa cầu trong khi gối cố định đặt ở một đầu.","Bỏ qua co ngót, từ biến khi chọn khe co giãn cho cầu bê tông dự ứng lực.","Phê duyệt vật tư theo đơn hàng sẵn có thay vì theo yêu cầu thiết kế."],en:["Computing movement from midspan when the fixed bearing is at one end.","Ignoring shrinkage and creep when sizing joints for prestressed concrete bridges.","Approving materials because they were ordered rather than because they meet the design."]},career:[{vi:"Kỹ sư cầu đường tập sự",en:"Graduate bridge and road engineer"},{vi:"Kỹ sư thiết kế cầu đường",en:"Bridge and road design engineer"},{vi:"Chủ trì thiết kế cầu",en:"Lead bridge engineer"},{vi:"Giám đốc kỹ thuật hạ tầng giao thông",en:"Transport infrastructure technical director"}],glossary:[{term:"Expansion joint",vi:"Khe co giãn cho phép kết cấu nhịp dịch chuyển do nhiệt, co ngót, từ biến mà mặt cầu vẫn liên tục.",en:"Joint letting the deck move under temperature, shrinkage and creep while keeping the riding surface continuous."},{term:"Fixed bearing",vi:"Gối không cho chuyển vị ngang, là điểm gốc để tính chiều dài giãn nở.",en:"Bearing restraining horizontal movement, the origin for measuring expansion length."},{term:"HL-93",vi:"Mô hình hoạt tải xe thiết kế gồm xe tải hoặc xe hai trục kết hợp với tải trọng làn.",en:"Design vehicular live load model: truck or tandem combined with a lane load."},{term:"Creep",vi:"Biến dạng của bê tông tăng dần theo thời gian dưới tải trọng duy trì.",en:"Gradual increase of concrete strain over time under sustained load."},{term:"Load test",vi:"Thử tải cầu bằng xe có tải trọng biết trước để đo võng, ứng suất và đánh giá khả năng khai thác.",en:"Loading a bridge with known vehicles to measure deflection and stress and assess serviceability."}],quiz:[{q:{vi:"Cầu dài 60 m, gối cố định ở một mố, α = 10 x 10^-6 /°C, ΔT = 40 °C. Chuyển vị nhiệt tại khe ở đầu kia là bao nhiêu?",en:"A 60 m bridge has its fixed bearing at one abutment, α = 10 x 10^-6 /°C, ΔT = 40 °C. What is the thermal movement at the far joint?"},options:{vi:["12 mm","48 mm","2,4 mm","24 mm"],en:["12 mm","48 mm","2.4 mm","24 mm"]},answer:3,explain:{vi:"Chuyển vị = 10 x 10^-6 x 60 000 mm x 40 = 24 mm, tính trên toàn bộ 60 m từ gối cố định.",en:"Movement = 10 x 10^-6 x 60,000 mm x 40 = 24 mm, over the full 60 m from the fixed bearing."}},{q:{vi:"Tiêu chuẩn quốc gia nào dùng cho thiết kế cầu đường bộ ở Việt Nam?",en:"Which national standard governs highway bridge design in Vietnam?"},options:{vi:["TCVN 4453:1995","TCVN 11823:2017","TCVN 5574:2018","TCVN 9386:2012"],en:["TCVN 4453:1995","TCVN 11823:2017","TCVN 5574:2018","TCVN 9386:2012"]},answer:1,explain:{vi:"TCVN 11823:2017 là bộ tiêu chuẩn thiết kế cầu đường bộ theo hệ số tải trọng và sức kháng.",en:"TCVN 11823:2017 is the highway bridge design standard based on load and resistance factors."}},{q:{vi:"Nhà thầu đề nghị giữ khe co giãn không đủ khả năng chuyển vị để kịp thông xe. Bạn làm gì?",en:"The contractor proposes keeping a joint with insufficient movement capacity to open on time. What do you do?"},options:{vi:["Không phê duyệt, báo chủ trì, ban quản lý và đề xuất đặt gấp khe đúng loại hoặc phương án tạm được duyệt","Ký duyệt rồi thay sau","Cho lắp tạm mà không báo cáo","Để nhà thầu tự quyết định"],en:["Refuse, inform the lead and PMU and propose expedited correct joints or an approved interim fix","Approve now and replace later","Allow a temporary install without reporting","Let the contractor decide"]},answer:0,explain:{vi:"Khe thiếu khả năng chuyển vị có thể bị phá hỏng, gây nguy hiểm cho xe cộ; an toàn công cộng phải đặt trên ngày khánh thành.",en:"An undersized joint can fail and endanger traffic; public safety comes before the opening date."}},{q:{vi:"Vì sao cầu bê tông dự ứng lực cần cộng co ngót, từ biến vào chuyển vị khe?",en:"Why must prestressed concrete bridges add shrinkage and creep to joint movement?"},options:{vi:["Vì làm tăng nhiệt độ kết cấu","Vì làm tăng hoạt tải xe","Vì gây co ngắn dài hạn của kết cấu nhịp","Vì làm gối cố định dịch chuyển"],en:["They raise the structural temperature","They increase vehicle loads","They cause long-term shortening of the deck","They move the fixed bearing"]},answer:2,explain:{vi:"Co ngót và từ biến dưới lực nén trước làm kết cấu nhịp ngắn dần, mở rộng khe theo thời gian.",en:"Shrinkage and creep under prestress shorten the deck over time, opening the joint."}}],tools_en:["Bridge structural analysis software","Road design and terrain modeling software","Infrastructure CAD and BIM software","Total station and leveling instrument","Deflection and strain gauges for load tests"]}},"KK-641":{scenario:{company:"Thien Ha Tower Operations",supervisor:{name:"Kiều Văn Thịnh",role:{vi:"Giám đốc Vận hành Tòa nhà",en:"Building Operations Director"}},ref_code:"WO-4417",title:{vi:"An toàn trước. Số liệu đúng. Hóa đơn minh bạch.",en:"Safety first. Right data. Transparent billing."},brief:{vi:"Bạn phụ trách vận hành tòa văn phòng Thiên Hà Tower. Báo cáo tuần WO-4417 có hai mục cần rà soát: phiếu sự cố “bơm chữa cháy chính không tự khởi động khi chạy thử tuần” và hóa đơn điện tháng 10 của khách thuê tầng 9. Công tơ của khách thuê đo gián tiếp qua biến dòng 200/5 A, chỉ số đầu kỳ 2418,6 và cuối kỳ 2571,8. Đối chiếu bản nháp với tài liệu gốc, sửa mức ưu tiên sự cố và sản lượng điện tính tiền (kWh), rồi lập báo cáo có căn cứ.",en:"You run operations at the Thien Ha Tower office building. Weekly report WO-4417 has two items to review: an incident ticket “main fire pump failed to auto-start during the weekly test” and the October electricity bill of the 9th-floor tenant. The tenant meter is CT-connected with a 200/5 A current transformer; the opening reading is 2418.6 and the closing reading is 2571.8. Compare the draft with the source documents, correct the incident priority and the billable energy (kWh), then write an evidence-based report."},reference_title:{vi:"Ma trận SLA & biên bản chốt chỉ số công tơ",en:"SLA matrix & meter reading record"},fields:[{id:"WO_PRIORITY",label:{vi:"Mức ưu tiên phiếu sự cố",en:"Incident ticket priority"},initial:"P3",expected:"P1",choices:["P1","P2","P3"],reference:"Ma trận ưu tiên sự cố (SLA)",ref_value:{vi:"P1: hệ thống an toàn sinh mạng (PCCC, thang máy kẹt người), phản hồi 15 phút; P2: ảnh hưởng khách thuê; P3: thường",en:"P1: life-safety systems (fire protection, trapped lift) - 15 min response; P2: tenant impact; P3: routine"},hint:{vi:"Bơm chữa cháy thuộc hệ thống an toàn sinh mạng, không phải hạng mục bảo trì thông thường.",en:"A fire pump is a life-safety system, not a routine maintenance item."}},{id:"BILL_KWH",label:{vi:"Sản lượng điện tính tiền (kWh)",en:"Billable energy (kWh)"},initial:"153.2",expected:"6128",reference:"Biên bản chốt chỉ số công tơ T10",ref_value:{vi:"Chỉ số đầu 2418,6; chỉ số cuối 2571,8; biến dòng 200/5 A; không có biến điện áp",en:"Opening 2418.6; closing 2571.8; CT 200/5 A; no voltage transformer"},hint:{vi:"Công tơ đo gián tiếp chỉ hiển thị phía thứ cấp, phải nhân với hệ số nhân của biến dòng.",en:"A CT-connected meter reads the secondary side, so multiply by the CT ratio."}}],sop32:{vi:"Sản lượng điện tính tiền = (chỉ số cuối - chỉ số đầu) x hệ số nhân công tơ; hệ số nhân = tỷ số biến dòng (sơ cấp/thứ cấp) x tỷ số biến điện áp (không có thì lấy 1). Đơn giá điện trong bài là số liệu mô phỏng.",en:"Billable energy = (closing - opening reading) x meter multiplier; multiplier = CT ratio (primary/secondary) x VT ratio (1 if none). Tariffs in this exercise are simulated figures."},context:{label:"BMS / CMMS · WO-4417",metrics:[{label:{vi:"Chỉ số đầu kỳ",en:"Opening reading"},value:"2418.6"},{label:{vi:"Chỉ số cuối kỳ",en:"Closing reading"},value:"2571.8"},{label:{vi:"Biến dòng",en:"Current transformer"},value:"200/5 A"},{label:{vi:"Đoàn kiểm tra PCCC (sáng mai)",en:"Fire inspection (tomorrow)"},value:"08:00"}]},crisis:{vi:"Đại diện chủ đầu tư nhắn: “Mai đoàn kiểm tra PCCC đến. Em cứ ký sổ bảo trì là bơm chữa cháy đạt, để bơm dự phòng chạy tay. Sửa bơm chính để quý sau cho đỡ chi phí.”",en:"The owner's representative messages you: “The fire inspectors come tomorrow. Just sign the maintenance log saying the fire pump passed and run the standby pump manually. Fix the main pump next quarter to save money.”"},options:{safe:{vi:"Ghi đúng tình trạng bơm, kích hoạt P1 gọi nhà thầu sửa ngay, bố trí trực PCCC tăng cường, báo Giám đốc tòa nhà bằng văn bản và trình bày trung thực với đoàn kiểm tra.",en:"Record the true pump status, raise a P1 call-out for immediate repair, add fire watch cover, inform the Building Director in writing and be honest with the inspectors."},shortcut:{vi:"Ký sổ bảo trì là đạt, cho bơm dự phòng chạy tay và để quý sau mới sửa bơm chính.",en:"Sign the log as passed, run the standby pump manually and fix the main pump next quarter."},wait:{vi:"Để nguyên phiếu P3 và chờ chủ đầu tư tự quyết định có sửa bơm hay không.",en:"Leave the ticket at P3 and wait for the owner to decide whether to repair the pump."}},questions:{vi:["Vì sao phiếu sự cố bơm chữa cháy phải là P1? Dẫn chứng từ ma trận SLA và rủi ro nếu để P3.","Trình bày cách tính 6128 kWh và cách bạn xử lý khiếu nại nếu khách thuê thắc mắc hóa đơn tăng mạnh."],en:["Why must the fire pump ticket be P1? Cite the SLA matrix and the risk of leaving it at P3.","Explain how you reached 6128 kWh and how you would handle the tenant's complaint about a much higher bill."]},hints:{vi:["Đặt phiếu sự cố cạnh ma trận SLA và xác định hệ thống bị ảnh hưởng thuộc nhóm nào.","Tìm tỷ số biến dòng trên biên bản chốt chỉ số trước khi áp dụng công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi yêu cầu ghi sai tình trạng thiết bị an toàn phải được từ chối và báo cáo."],en:["Place the ticket next to the SLA matrix and decide which system group is affected.","Find the CT ratio on the meter record before applying the formula in SOP 3.2.","Re-read SOP 4.2: any request to misreport safety equipment status must be refused and escalated."]}},learning:{summary:{vi:"Quản lý vận hành tòa nhà điều hành toàn bộ hệ thống kỹ thuật và dịch vụ của công trình: điện, điều hòa thông gió, cấp thoát nước, thang máy, PCCC, an ninh và vệ sinh. Người làm nghề lập kế hoạch bảo trì phòng ngừa, xử lý sự cố theo SLA, quản lý nhà thầu, kiểm soát năng lượng và chi phí dịch vụ, đồng thời bảo đảm tòa nhà an toàn, tuân thủ pháp luật và khách thuê hài lòng.",en:"A building and facility operations manager runs every technical system and service in a property: power, HVAC, plumbing, lifts, fire protection, security and cleaning. The role plans preventive maintenance, handles incidents to SLA, manages contractors, controls energy and service costs, and keeps the building safe, compliant and its tenants satisfied."},responsibilities:{vi:["Lập và giám sát kế hoạch bảo trì phòng ngừa cho hệ thống điện, HVAC, thang máy, PCCC và cấp thoát nước.","Tiếp nhận, phân loại ưu tiên và xử lý sự cố theo SLA, lưu vết trên hệ thống CMMS.","Quản lý nhà thầu dịch vụ: an ninh, vệ sinh, bảo trì chuyên ngành, nghiệm thu theo hợp đồng.","Theo dõi năng lượng, chốt chỉ số công tơ và lập hóa đơn điện nước, phí dịch vụ cho khách thuê.","Duy trì hồ sơ pháp lý PCCC, kiểm định thiết bị, diễn tập thoát nạn và báo cáo chủ đầu tư."],en:["Plan and supervise preventive maintenance for power, HVAC, lifts, fire protection and plumbing.","Receive, prioritize and resolve incidents to SLA, keeping an audit trail in the CMMS.","Manage service contractors for security, cleaning and specialist maintenance and accept work per contract.","Track energy, take meter readings and issue utility and service charge bills to tenants.","Keep fire safety records, equipment inspection certificates and evacuation drills current and report to the owner."]},competencies:[{name:{vi:"Kỹ thuật hệ thống tòa nhà",en:"Building systems engineering"},desc:{vi:"Hiểu nguyên lý điện hạ thế, chiller, AHU, bơm, thang máy và hệ thống BMS để chẩn đoán đúng sự cố.",en:"Understand low-voltage power, chillers, AHUs, pumps, lifts and the BMS well enough to diagnose faults."}},{name:{vi:"Quản lý bảo trì & SLA",en:"Maintenance & SLA management"},desc:{vi:"Xây dựng lịch bảo trì phòng ngừa, phân loại ưu tiên sự cố và đo thời gian phản hồi, khắc phục.",en:"Build preventive schedules, prioritize incidents and measure response and fix times."}},{name:{vi:"Quản lý năng lượng & chi phí",en:"Energy & cost control"},desc:{vi:"Đọc công tơ đo gián tiếp, phân bổ chi phí minh bạch và tìm giải pháp tiết kiệm năng lượng.",en:"Read CT-connected meters, allocate costs transparently and find energy savings."}},{name:{vi:"An toàn & tuân thủ",en:"Safety & compliance"},desc:{vi:"Giữ hệ thống PCCC, thang máy, thiết bị áp lực luôn sẵn sàng và đủ hồ sơ kiểm định, không ghi khống.",en:"Keep fire protection, lifts and pressure equipment ready with valid certificates and never falsify records."}},{name:{vi:"Dịch vụ khách thuê & nhà thầu",en:"Tenant & contractor service"},desc:{vi:"Giao tiếp rõ ràng với khách thuê, chủ đầu tư và nhà thầu; giải trình hóa đơn và sự cố bằng dữ liệu.",en:"Communicate clearly with tenants, owners and contractors and explain bills and incidents with data."}}],knowledge:{vi:["ISO 41001 về hệ thống quản lý cơ sở vật chất (Facility Management).","ISO 50001 về hệ thống quản lý năng lượng và nguyên tắc đo lường, giám sát tiêu thụ.","QCVN 06:2022/BXD về an toàn cháy cho nhà và công trình cùng quy định hiện hành về PCCC.","Nguyên lý đo đếm điện gián tiếp qua biến dòng, biến điện áp và cách tính hệ số nhân công tơ.","Quy định hiện hành về kiểm định kỹ thuật an toàn thang máy, thiết bị áp lực và an toàn lao động.","Nguyên tắc bảo trì phòng ngừa, bảo trì theo tình trạng và quản lý vòng đời tài sản."],en:["ISO 41001 for facility management systems.","ISO 50001 for energy management and the principles of metering and monitoring consumption.","QCVN 06:2022/BXD on fire safety of buildings and the current fire protection regulations.","CT and VT metering principles and how to calculate the meter multiplier.","Current rules on safety inspection of lifts, pressure equipment and occupational safety.","Preventive and condition-based maintenance and asset lifecycle management."]},tools:["Hệ thống quản lý tòa nhà BMS","Phần mềm quản lý bảo trì CMMS","Hệ thống báo cháy địa chỉ","Camera nhiệt và đồng hồ đo điện","Microsoft Excel / Power BI","Ứng dụng phản ánh của khách thuê"],kpis:{vi:["Tỷ lệ phiếu P1 được phản hồi trong 15 phút và khắc phục đúng hạn.","Tỷ lệ hoàn thành kế hoạch bảo trì phòng ngừa trong tháng.","Cường độ tiêu thụ năng lượng (kWh/m2/năm) so với kế hoạch.","Tỷ lệ hóa đơn khách thuê không phát sinh khiếu nại."],en:["Share of P1 tickets answered within 15 minutes and fixed on time.","Monthly preventive maintenance completion rate.","Energy use intensity (kWh/m2/year) against plan.","Share of tenant bills issued without complaints."]},day:[{time:"07:30",vi:"Đi tuần kỹ thuật, xem cảnh báo BMS và nhật ký trực đêm.",en:"Walk the plant rooms, review BMS alarms and the night shift log."},{time:"09:00",vi:"Họp giao ban với đội kỹ thuật, an ninh, vệ sinh và phân công phiếu công việc.",en:"Brief the technical, security and cleaning teams and assign work orders."},{time:"11:00",vi:"Giám sát chạy thử tuần bơm chữa cháy và máy phát điện dự phòng.",en:"Witness the weekly fire pump and standby generator tests."},{time:"14:00",vi:"Chốt chỉ số công tơ, đối chiếu hệ số nhân và lập hóa đơn khách thuê.",en:"Take meter readings, check multipliers and prepare tenant bills."},{time:"16:30",vi:"Làm việc với nhà thầu, cập nhật CMMS và báo cáo chủ đầu tư.",en:"Meet contractors, update the CMMS and report to the owner."}],mistakes:{vi:["Xếp sự cố hệ thống an toàn sinh mạng vào mức ưu tiên thông thường.","Quên nhân hệ số biến dòng khi tính điện cho công tơ đo gián tiếp.","Ký biên bản bảo trì “đạt” khi thiết bị chưa được kiểm tra thực tế."],en:["Treating a life-safety system fault as a routine priority.","Forgetting the CT multiplier when billing a CT-connected meter.","Signing a maintenance record as passed without actually testing the equipment."]},career:[{vi:"Kỹ thuật viên vận hành tòa nhà",en:"Building operations technician"},{vi:"Trưởng ca kỹ thuật / Giám sát kỹ thuật",en:"Shift lead / Technical supervisor"},{vi:"Quản lý vận hành tòa nhà",en:"Building operations manager"},{vi:"Giám đốc quản lý bất động sản & cơ sở vật chất",en:"Head of property & facility management"}],glossary:[{term:"BMS",vi:"Hệ thống quản lý tòa nhà giám sát, điều khiển tập trung HVAC, điện, bơm và cảnh báo.",en:"Building management system that centrally monitors and controls HVAC, power, pumps and alarms."},{term:"CMMS",vi:"Phần mềm quản lý bảo trì lưu phiếu công việc, lịch bảo trì, vật tư và lịch sử thiết bị.",en:"Maintenance software holding work orders, schedules, spares and equipment history."},{term:"SLA",vi:"Cam kết mức dịch vụ: thời gian phản hồi và khắc phục theo từng mức ưu tiên.",en:"Service level agreement setting response and fix times for each priority."},{term:"Biến dòng (CT)",vi:"Thiết bị hạ dòng điện lớn xuống mức đo được; công tơ đo qua CT phải nhân hệ số nhân.",en:"Current transformer that steps current down for metering; readings must be multiplied by its ratio."},{term:"PPM",vi:"Bảo trì phòng ngừa theo kế hoạch, thực hiện định kỳ trước khi thiết bị hỏng.",en:"Planned preventive maintenance carried out periodically before equipment fails."}],quiz:[{q:{vi:"Công tơ qua biến dòng 300/5 A, chỉ số tăng 120,0 trong tháng. Sản lượng tính tiền là bao nhiêu?",en:"A meter on a 300/5 A CT advances 120.0 in a month. What is the billable energy?"},options:{vi:["120 kWh","600 kWh","7200 kWh","36000 kWh"],en:["120 kWh","600 kWh","7200 kWh","36000 kWh"]},answer:2,explain:{vi:"Hệ số nhân = 300/5 = 60; sản lượng = 120 x 60 = 7200 kWh.",en:"Multiplier = 300/5 = 60; energy = 120 x 60 = 7200 kWh."}},{q:{vi:"Sự cố nào phải xếp mức ưu tiên cao nhất?",en:"Which incident must get the highest priority?"},options:{vi:["Thang máy kẹt người","Bóng đèn hành lang hỏng","Vòi nước nhà vệ sinh rỉ","Thảm sảnh bị bẩn"],en:["A lift with people trapped","A broken corridor lamp","A dripping restroom tap","A dirty lobby carpet"]},answer:0,explain:{vi:"Sự cố đe dọa an toàn sinh mạng luôn là P1, phải phản hồi ngay.",en:"Anything threatening life safety is always P1 and needs an immediate response."}},{q:{vi:"Chủ đầu tư yêu cầu ký biên bản bơm chữa cháy “đạt” dù bơm đang lỗi. Bạn làm gì?",en:"The owner asks you to sign the fire pump as passed although it is faulty. What do you do?"},options:{vi:["Ký cho kịp đoàn kiểm tra","Ghi đúng tình trạng, sửa khẩn và báo cáo bằng văn bản","Ký nhưng ghi chú miệng với đội kỹ thuật","Không làm gì chờ chủ đầu tư"],en:["Sign it before the inspection","Record the true status, repair urgently and report in writing","Sign it and tell the team verbally","Do nothing and wait for the owner"]},answer:1,explain:{vi:"Ghi khống hồ sơ PCCC là vi phạm và đe dọa sinh mạng; phải trung thực, khắc phục và báo cáo.",en:"Falsifying fire records is a violation that endangers lives; be truthful, fix it and escalate."}},{q:{vi:"Tiêu chuẩn quốc tế nào dành cho hệ thống quản lý cơ sở vật chất?",en:"Which international standard covers facility management systems?"},options:{vi:["ISO 9001","ISO 27001","ISO 14001","ISO 41001"],en:["ISO 9001","ISO 27001","ISO 14001","ISO 41001"]},answer:3,explain:{vi:"ISO 41001 quy định yêu cầu cho hệ thống quản lý cơ sở vật chất (FM).",en:"ISO 41001 sets requirements for facility management systems."}}],tools_en:["Building management system (BMS)","CMMS maintenance management software","Addressable fire alarm system","Thermal camera and electrical meters","Microsoft Excel / Power BI","Tenant feedback app"]}},"KK-642":{scenario:{company:"Truc Lam Urban Planning Studio",supervisor:{name:"Lương Thu Hà",role:{vi:"Trưởng phòng Quy hoạch & GIS",en:"Head of Planning & GIS"}},ref_code:"QH-2618",title:{vi:"Đúng hệ tọa độ. Đúng chỉ tiêu. Đúng quy hoạch.",en:"Right datum. Right indicators. Right plan."},brief:{vi:"Bạn kiểm tra hồ sơ đề xuất dự án QH-2618 cho một lô đất hỗn hợp tại Hà Nội. Lô đất có tổng diện tích 2400 m2, trong đó 300 m2 nằm trong chỉ giới đường đỏ của tuyến đường quy hoạch; quy hoạch chi tiết 1/500 đã duyệt cho hệ số sử dụng đất tối đa 3,5. Ranh lô do tư vấn nộp được số hóa ở hệ WGS84. Đối chiếu phiếu kiểm tra nháp với tài liệu gốc, sửa hệ tọa độ nộp hồ sơ và tổng diện tích sàn tối đa (m2), rồi lập báo cáo có căn cứ.",en:"You are checking project proposal QH-2618 for a mixed-use plot in Hanoi. The plot covers 2400 m2 in total, of which 300 m2 lies inside the red line of a planned road; the approved 1/500 detailed plan allows a maximum floor area ratio of 3.5. The consultant digitized the plot boundary in WGS84. Compare the draft checklist with the source documents, correct the submission coordinate system and the maximum gross floor area (m2), then write an evidence-based report."},reference_title:{vi:"Quy định dữ liệu & bản đồ QHCT 1/500 đã duyệt",en:"Data rules & approved 1/500 detailed plan"},fields:[{id:"CRS",label:{vi:"Hệ tọa độ dữ liệu nộp",en:"Submission coordinate system"},initial:"WGS84-UTM48N",expected:"VN2000-TM3-105",choices:["WGS84-UTM48N","VN2000-TM3-105","VN2000-UTM48"],reference:"Quy định nộp dữ liệu GIS",ref_value:{vi:"Hệ VN-2000, múi chiếu 3 độ, kinh tuyến trục 105°00' cho Hà Nội (mã nội bộ VN2000-TM3-105)",en:"VN-2000 datum, 3-degree zone, central meridian 105°00' for Hanoi (internal code VN2000-TM3-105)"},hint:{vi:"Dữ liệu địa chính, quy hoạch cấp tỉnh dùng VN-2000 múi 3 độ với kinh tuyến trục riêng của tỉnh.",en:"Provincial cadastral and planning data use VN-2000 in a 3-degree zone with the province's own central meridian."}},{id:"GFA_MAX",label:{vi:"Tổng diện tích sàn tối đa (m2)",en:"Maximum gross floor area (m2)"},initial:"8400",expected:"7350",reference:"Bảng chỉ tiêu lô đất HH-04",ref_value:{vi:"Tổng diện tích 2400 m2; trong chỉ giới đường đỏ 300 m2; hệ số sử dụng đất tối đa 3,5",en:"Total area 2400 m2; inside the red line 300 m2; maximum FAR 3.5"},hint:{vi:"Phần đất nằm trong chỉ giới đường đỏ dành cho đường, không được tính vào diện tích lô khi áp chỉ tiêu.",en:"Land inside the red line is reserved for the road and is excluded from the plot area when applying indicators."}}],sop32:{vi:"Tổng diện tích sàn tối đa = diện tích lô đất trong phạm vi quy hoạch (đã trừ phần nằm trong chỉ giới đường đỏ) x hệ số sử dụng đất tối đa theo quy hoạch chi tiết đã duyệt.",en:"Maximum gross floor area = plot area within the plan boundary (after removing land inside the red line) x the maximum floor area ratio of the approved detailed plan."},context:{label:"GIS / QH-2618",metrics:[{label:{vi:"Tổng diện tích lô",en:"Total plot area"},value:"2400 m2"},{label:{vi:"Trong chỉ giới đường đỏ",en:"Inside the red line"},value:"300 m2"},{label:{vi:"Hệ số sử dụng đất tối đa",en:"Maximum FAR"},value:"3.5"},{label:{vi:"Tỷ lệ bản đồ quy hoạch",en:"Plan map scale"},value:"1/500"}]},crisis:{vi:"Đại diện chủ đầu tư gọi: “Em cứ tính trên 2400 m2, bao giờ mở đường mới thu hồi. Nhờ em dịch ranh lô trên lớp GIS ra 2 m phía đường cho khớp bản vẽ. Bên anh có quà cảm ơn.”",en:"The developer's representative calls: “Just use 2400 m2, the road land will only be taken when the road is built. Please shift the plot boundary 2 m toward the road in the GIS layer to match our drawing. We have a thank-you gift for you.”"},options:{safe:{vi:"Từ chối quà và yêu cầu sai, giữ ranh theo dữ liệu đo đạc, tính trên 2100 m2, báo Trưởng phòng bằng văn bản và hướng dẫn chủ đầu tư thủ tục điều chỉnh quy hoạch hợp lệ.",en:"Decline the gift and the request, keep the surveyed boundary, compute on 2100 m2, report to the Head of Planning in writing and point the developer to the lawful plan amendment process."},shortcut:{vi:"Dịch ranh 2 m và tính trên 2400 m2 cho kịp tiến độ, sau này có sai thì điều chỉnh.",en:"Shift the boundary 2 m and compute on 2400 m2 to stay on schedule, adjusting later if needed."},wait:{vi:"Treo hồ sơ, không phản hồi chủ đầu tư và chờ ai đó quyết thay.",en:"Park the file, ignore the developer and wait for someone else to decide."}},questions:{vi:["Vì sao dữ liệu phải ở hệ VN2000-TM3-105 và ranh lô lệch thế nào khi chồng lớp WGS84 lên nền quy hoạch?","Trình bày cách tính 7350 m2 và rủi ro pháp lý nếu tính trên toàn bộ 2400 m2."],en:["Why must the data be in VN2000-TM3-105, and how does the boundary shift when a WGS84 layer is overlaid on the planning base?","Explain how you reached 7350 m2 and the legal risk of using the full 2400 m2."]},hints:{vi:["Đọc quy định nộp dữ liệu GIS: hệ quy chiếu, múi chiếu và kinh tuyến trục của địa phương.","Tách phần đất trong chỉ giới đường đỏ trước khi nhân hệ số sử dụng đất ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không nhận quà, không sửa dữ liệu không gian theo yêu cầu của bên được thẩm định."],en:["Read the GIS submission rules: datum, zone width and the local central meridian.","Remove the land inside the red line before applying the FAR in SOP 3.2.","Re-read SOP 4.2: accept no gifts and never alter spatial data at the request of the party under review."]}},learning:{summary:{vi:"Chuyên viên quy hoạch đô thị và GIS xây dựng, quản lý cơ sở dữ liệu không gian phục vụ lập, thẩm định và quản lý quy hoạch. Người làm nghề số hóa bản đồ, kiểm soát hệ tọa độ, tính toán chỉ tiêu sử dụng đất, phân tích hạ tầng, dân số và môi trường để tham mưu quyết định. Nghề đòi hỏi chính xác về dữ liệu, hiểu pháp luật quy hoạch và giữ liêm chính trước áp lực lợi ích.",en:"An urban planning and GIS specialist builds and manages the spatial database used to prepare, review and administer urban plans. The role digitizes maps, controls coordinate systems, calculates land-use indicators and analyses infrastructure, population and environment to support decisions. It requires precise data, sound knowledge of planning law and integrity under pressure from vested interests."},responsibilities:{vi:["Xây dựng, cập nhật cơ sở dữ liệu GIS quy hoạch: ranh lô, chức năng sử dụng đất, chỉ giới, hạ tầng.","Kiểm tra hệ tọa độ, độ chính xác và siêu dữ liệu của dữ liệu do tư vấn, đơn vị đo đạc nộp.","Tính toán, đối chiếu chỉ tiêu: mật độ xây dựng, hệ số sử dụng đất, tầng cao, dân số, chỗ đỗ xe.","Phân tích không gian về giao thông, ngập úng, bán kính phục vụ công trình công cộng.","Lập bản đồ chuyên đề, báo cáo thẩm định và cung cấp thông tin quy hoạch cho tổ chức, cá nhân."],en:["Build and update the planning GIS: plot boundaries, land-use functions, building lines and infrastructure.","Check the coordinate system, accuracy and metadata of data submitted by consultants and surveyors.","Calculate and cross-check indicators: site coverage, FAR, height, population and parking.","Run spatial analysis on transport, flooding and service radii of public facilities.","Produce thematic maps and review reports and provide planning information to the public."]},competencies:[{name:{vi:"Hệ quy chiếu & trắc địa",en:"Datums & geodesy"},desc:{vi:"Hiểu VN-2000, WGS84, múi chiếu 3 độ và 6 độ, chuyển đổi tọa độ đúng tham số.",en:"Understand VN-2000, WGS84, 3-degree and 6-degree zones and transform coordinates with correct parameters."}},{name:{vi:"Phân tích không gian",en:"Spatial analysis"},desc:{vi:"Chồng lớp, tạo vùng đệm, phân tích mạng lưới và thống kê theo ô lô để trả lời câu hỏi quy hoạch.",en:"Overlay, buffer, run network analysis and plot-level statistics to answer planning questions."}},{name:{vi:"Chỉ tiêu quy hoạch",en:"Planning indicators"},desc:{vi:"Tính đúng mật độ xây dựng, hệ số sử dụng đất, tầng cao và kiểm tra theo quy chuẩn.",en:"Calculate site coverage, FAR and height correctly and check them against the national code."}},{name:{vi:"Quản trị dữ liệu",en:"Data governance"},desc:{vi:"Chuẩn hóa thuộc tính, siêu dữ liệu, phiên bản và phân quyền để dữ liệu tin cậy, truy vết được.",en:"Standardize attributes, metadata, versions and access so the data is trusted and traceable."}},{name:{vi:"Liêm chính công vụ",en:"Public-service integrity"},desc:{vi:"Không nhận quà, không chỉnh dữ liệu theo lợi ích riêng; minh bạch căn cứ khi tham mưu.",en:"Accept no gifts, never bend data for private interests and keep the basis of advice transparent."}}],knowledge:{vi:["Luật Quy hoạch đô thị và nông thôn cùng các nghị định, thông tư hướng dẫn hiện hành.","QCVN 01:2021/BXD về quy hoạch xây dựng: mật độ xây dựng, hệ số sử dụng đất, khoảng lùi.","Hệ quy chiếu và hệ tọa độ quốc gia VN-2000, kinh tuyến trục theo từng tỉnh, thành phố.","Các cấp độ quy hoạch: quy hoạch chung, phân khu 1/2000 (1/5000) và chi tiết 1/500.","Chuẩn dữ liệu địa lý: siêu dữ liệu ISO 19115, dịch vụ bản đồ OGC WMS/WFS.","Khái niệm chỉ giới đường đỏ, chỉ giới xây dựng và hành lang bảo vệ hạ tầng kỹ thuật."],en:["The Law on Urban and Rural Planning with its current implementing decrees and circulars.","QCVN 01:2021/BXD on construction planning: site coverage, FAR and setbacks.","The national VN-2000 datum and coordinate system with each province's central meridian.","Planning levels: general plan, zoning plan 1/2000 (1/5000) and detailed plan 1/500.","Geographic data standards: ISO 19115 metadata and OGC WMS/WFS map services.","Red line, building line and technical infrastructure protection corridors."]},tools:["QGIS","ArcGIS Pro","PostgreSQL / PostGIS","AutoCAD / MicroStation","Máy thu GNSS RTK","Phần mềm chuyển đổi tọa độ VN-2000"],kpis:{vi:["Tỷ lệ hồ sơ thẩm định đúng hạn và không phải trả lại do sai số liệu.","Độ lệch vị trí trung bình của dữ liệu nộp so với nền chuẩn (mục tiêu dưới ngưỡng cho phép).","Tỷ lệ lớp dữ liệu có siêu dữ liệu đầy đủ và cập nhật.","Số khiếu nại về thông tin quy hoạch do sai dữ liệu (mục tiêu bằng 0)."],en:["Share of reviews completed on time without being returned for data errors.","Average positional offset of submitted data against the reference base (below tolerance).","Share of data layers with complete, current metadata.","Complaints about planning information caused by data errors (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra hồ sơ mới nộp, hệ tọa độ và siêu dữ liệu của từng lớp dữ liệu.",en:"Check new submissions, coordinate systems and metadata for each layer."},{time:"09:30",vi:"Chồng lớp ranh lô lên nền quy hoạch đã duyệt, đánh dấu sai lệch vị trí.",en:"Overlay plot boundaries on the approved plan base and flag positional offsets."},{time:"11:00",vi:"Tính chỉ tiêu mật độ xây dựng, hệ số sử dụng đất và lập bảng đối chiếu.",en:"Calculate site coverage and FAR and build the comparison table."},{time:"14:00",vi:"Họp với tư vấn thiết kế, giải thích yêu cầu chỉnh sửa có dẫn căn cứ.",en:"Meet the design consultant and explain required changes with references."},{time:"16:00",vi:"Cập nhật cơ sở dữ liệu, xuất bản đồ chuyên đề và hoàn thiện báo cáo thẩm định.",en:"Update the database, export thematic maps and finalize the review report."}],mistakes:{vi:["Nhận dữ liệu WGS84 hoặc sai kinh tuyến trục mà không chuyển đổi, gây lệch ranh lô.","Tính hệ số sử dụng đất trên cả phần đất nằm trong chỉ giới đường đỏ.","Chỉnh ranh hoặc chỉ tiêu theo yêu cầu của chủ đầu tư mà không có quyết định điều chỉnh quy hoạch."],en:["Accepting WGS84 data or the wrong central meridian without transformation, shifting plot boundaries.","Applying the FAR to land that lies inside the red line.","Changing boundaries or indicators at a developer's request without an approved plan amendment."]},career:[{vi:"Kỹ thuật viên GIS / số hóa bản đồ",en:"GIS technician / map digitizer"},{vi:"Chuyên viên quy hoạch & GIS",en:"Urban planning & GIS specialist"},{vi:"Chủ trì đồ án quy hoạch / Trưởng nhóm dữ liệu không gian",en:"Lead planner / Spatial data team lead"},{vi:"Giám đốc quy hoạch & đô thị thông minh",en:"Director of planning & smart city"}],glossary:[{term:"VN-2000",vi:"Hệ quy chiếu và hệ tọa độ quốc gia của Việt Nam dùng cho đo đạc, bản đồ địa chính và quy hoạch.",en:"Vietnam's national datum and coordinate system for surveying, cadastral mapping and planning."},{term:"Hệ số sử dụng đất (FAR)",vi:"Tỷ số giữa tổng diện tích sàn công trình và diện tích lô đất.",en:"Ratio of a building's gross floor area to the plot area."},{term:"Mật độ xây dựng",vi:"Tỷ lệ diện tích chiếm đất của công trình trên tổng diện tích lô đất.",en:"Share of the plot area covered by the building footprint (site coverage)."},{term:"Chỉ giới đường đỏ",vi:"Đường ranh giới phân định phần đất dành cho đường giao thông, hạ tầng với phần đất xây dựng.",en:"Boundary line separating land reserved for roads and infrastructure from buildable land."},{term:"Kinh tuyến trục",vi:"Kinh tuyến gốc của múi chiếu; mỗi tỉnh dùng một kinh tuyến trục riêng trong VN-2000 múi 3 độ.",en:"The central meridian of a projection zone; each province has its own in VN-2000 3-degree zones."}],quiz:[{q:{vi:"Lô đất 1800 m2, trong đó 200 m2 nằm trong chỉ giới đường đỏ, hệ số sử dụng đất 4,0. Tổng diện tích sàn tối đa là bao nhiêu?",en:"A 1800 m2 plot has 200 m2 inside the red line and a FAR of 4.0. What is the maximum gross floor area?"},options:{vi:["7200 m2","6400 m2","8000 m2","1600 m2"],en:["7200 m2","6400 m2","8000 m2","1600 m2"]},answer:1,explain:{vi:"Diện tích tính chỉ tiêu = 1800 - 200 = 1600 m2; 1600 x 4,0 = 6400 m2.",en:"Indicator area = 1800 - 200 = 1600 m2; 1600 x 4.0 = 6400 m2."}},{q:{vi:"Dữ liệu quy hoạch cấp tỉnh thường phải nộp ở hệ tọa độ nào?",en:"Which coordinate system is usually required for provincial planning data?"},options:{vi:["WGS84 kinh độ, vĩ độ","WGS84 UTM múi 6 độ","Hệ tọa độ giả định của tư vấn","VN-2000 múi 3 độ, kinh tuyến trục của tỉnh"],en:["WGS84 latitude and longitude","WGS84 UTM 6-degree zone","The consultant's local grid","VN-2000 3-degree zone with the province's central meridian"]},answer:3,explain:{vi:"Bản đồ địa chính và quy hoạch tỷ lệ lớn dùng VN-2000 múi 3 độ với kinh tuyến trục của từng tỉnh.",en:"Large-scale cadastral and planning maps use VN-2000 3-degree zones with each province's central meridian."}},{q:{vi:"Chủ đầu tư đề nghị dịch ranh lô trên GIS và tặng quà cảm ơn. Bạn làm gì?",en:"A developer asks you to shift a plot boundary in the GIS and offers a gift. What do you do?"},options:{vi:["Từ chối, giữ dữ liệu đo đạc và báo cáo bằng văn bản","Nhận quà nhưng không dịch ranh","Dịch ranh vì sai lệch nhỏ","Im lặng và để hồ sơ tồn đọng"],en:["Refuse, keep the surveyed data and report in writing","Take the gift but leave the boundary","Shift it since the gap is small","Stay silent and let the file stall"]},answer:0,explain:{vi:"Nhận quà và sửa dữ liệu theo lợi ích riêng vi phạm liêm chính công vụ; phải từ chối và báo cáo.",en:"Taking gifts or bending data breaches public integrity; refuse and report."}},{q:{vi:"Mật độ xây dựng được tính như thế nào?",en:"How is site coverage calculated?"},options:{vi:["Tổng diện tích sàn / diện tích lô","Số tầng x diện tích lô","Diện tích chiếm đất của công trình / diện tích lô","Diện tích cây xanh / diện tích lô"],en:["Gross floor area / plot area","Number of floors x plot area","Building footprint / plot area","Green area / plot area"]},answer:2,explain:{vi:"Mật độ xây dựng là tỷ lệ diện tích chiếm đất của công trình trên diện tích lô; tổng sàn / lô là hệ số sử dụng đất.",en:"Site coverage is footprint over plot area; gross floor area over plot area is the FAR."}}],tools_en:["QGIS","ArcGIS Pro","PostgreSQL / PostGIS","AutoCAD / MicroStation","GNSS RTK receiver","VN-2000 coordinate transformation software"]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(8)})(window.KKR);
